# --- Supabase 連線池（程式啟動時建立一次，取代每次呼叫都開新連線） ---
_db_url = os.environ.get("DATABASE_URL")
if not _db_url:
    raise RuntimeError("DATABASE_URL 未設定，無法啟動 Stock Bot。")
_url = urlparse(_db_url)
if not _url.hostname:
    raise RuntimeError("DATABASE_URL 格式錯誤：缺少 hostname。")
_ipv4_addr = socket.gethostbyname(_url.hostname)

# 一定要用 ThreadedConnectionPool 而不是 SimpleConnectionPool。
# gunicorn 開了多執行緒之後，SimpleConnectionPool 可能把同一條連線
# 同時交給兩個執行緒，兩邊交錯寫入同一個 SSL 串流，就會出現
# 「SSL error: decryption failed or bad record mac」——
# 錯誤訊息看起來像憑證問題，實際上是併發問題，很容易查錯方向。
# 單執行緒時永遠不會發生，所以加上 --threads 之前都相安無事。

# ===== DB 診斷模式（只記錄慢的連線／SQL，不改資料） =====
DB_DIAG_ENABLED = os.environ.get("DB_DIAG_ENABLED", "1") != "0"
DB_DIAG_CONN_WARN_MS = float(os.environ.get("DB_DIAG_CONN_WARN_MS", "100"))
DB_DIAG_SQL_WARN_MS = float(os.environ.get("DB_DIAG_SQL_WARN_MS", "500"))
DB_DIAG_HOLD_WARN_MS = float(os.environ.get("DB_DIAG_HOLD_WARN_MS", "1000"))
_DB_DIAG_LOCAL = threading.local()
_DB_CONN_CHECKOUT = {}
_DB_CONN_LOCK = threading.Lock()


def _db_diag_set(operation=None, request_id=None):
    if operation is not None:
        _DB_DIAG_LOCAL.operation = str(operation)
    if request_id is not None:
        _DB_DIAG_LOCAL.request_id = str(request_id)


def _db_diag_context():
    return (getattr(_DB_DIAG_LOCAL, "operation", "-"),
            getattr(_DB_DIAG_LOCAL, "request_id", "-"))


def _db_diag_sql(sql):
    try:
        text = re.sub(r"\s+", " ", str(sql)).strip()
        if len(text) > 220:
            text = text[:220] + "…"
        return text
    except Exception:
        return "<sql-format-error>"


class _TimedCursor(psycopg2.extensions.cursor):
    def execute(self, query, vars=None):
        if not DB_DIAG_ENABLED:
            return super().execute(query, vars)
        started = time.monotonic()
        try:
            return super().execute(query, vars)
        finally:
            elapsed_ms = (time.monotonic() - started) * 1000
            if elapsed_ms >= DB_DIAG_SQL_WARN_MS:
                operation, request_id = _db_diag_context()
                print(
                    "🐢 DB慢SQL %.0fms | op=%s | req=%s | sql=%s" %
                    (elapsed_ms, operation, request_id, _db_diag_sql(query)),
                    flush=True,
                )

    def fetchall(self):
        if not DB_DIAG_ENABLED:
            return super().fetchall()
        started = time.monotonic()
        try:
            return super().fetchall()
        finally:
            elapsed_ms = (time.monotonic() - started) * 1000
            if elapsed_ms >= DB_DIAG_SQL_WARN_MS:
                operation, request_id = _db_diag_context()
                print(
                    "🐢 DB慢fetchall %.0fms | op=%s | req=%s" %
                    (elapsed_ms, operation, request_id),
                    flush=True,
                )


class _TimedConnection(psycopg2.extensions.connection):
    def cursor(self, *args, **kwargs):
        kwargs.setdefault("cursor_factory", _TimedCursor)
        return super().cursor(*args, **kwargs)


DB_POOL_MIN = int(os.environ.get("DB_POOL_MIN", "1"))
DB_POOL_MAX = int(os.environ.get("DB_POOL_MAX", "10"))
if DB_POOL_MAX < DB_POOL_MIN:
    raise RuntimeError("DB_POOL_MAX 不可小於 DB_POOL_MIN。")

connection_pool = psycopg2.pool.ThreadedConnectionPool(
    DB_POOL_MIN, DB_POOL_MAX,
    database=_url.path[1:],
    user=_url.username,
    password=_url.password,
    host=_ipv4_addr,
    port=_url.port,
    sslmode='require',
    options='-c timezone=Asia/Taipei',
    connect_timeout=10,
    # 連線被 Supabase pooler 中途切斷時，下次借出才會發現而丟出例外。
    # 開啟 keepalive 讓閒置連線不被靜默斷開。
    keepalives=1,
    keepalives_idle=30,
    keepalives_interval=10,
    keepalives_count=3,
    connection_factory=_TimedConnection,
)


def get_db_connection():
    """
    借一條連線。診斷模式會量測「排隊等 connection」的時間，
    這是目前要確認首頁 6~10 秒波動是否來自 connection pool 的關鍵。
    """
    for _attempt in range(3):
        checkout_started = time.monotonic()
        try:
            conn = connection_pool.getconn()
        except pool.PoolError as e:
            print(f"⚠️ DB 連線池暫滿（第 {_attempt + 1}/3 次）：{e}")
            if _attempt < 2:
                time.sleep(0.1 * (_attempt + 1))
                continue
            raise
        try:
            if conn.closed:
                connection_pool.putconn(conn, close=True)
                continue
            wait_ms = (time.monotonic() - checkout_started) * 1000
            with _DB_CONN_LOCK:
                _DB_CONN_CHECKOUT[id(conn)] = time.monotonic()
            if DB_DIAG_ENABLED and wait_ms >= DB_DIAG_CONN_WARN_MS:
                operation, request_id = _db_diag_context()
                try:
                    in_use = len(connection_pool._used)
                except Exception:
                    in_use = "?"
                print(
                    "⏳ DB等連線 %.0fms | in_use=%s/%s | op=%s | req=%s" %
                    (wait_ms, in_use, DB_POOL_MAX, operation, request_id),
                    flush=True,
                )
            return conn
        except Exception as e:
            print(f"⚠️ 取得連線異常，丟棄重試: {e}")
            try:
                connection_pool.putconn(conn, close=True)
            except Exception:
                pass
            if _attempt < 2:
                time.sleep(0.1 * (_attempt + 1))
    raise RuntimeError("無法取得資料庫連線")


def release_db_connection(conn):
    """
    歸還連線。診斷模式同時量測一條 connection 被持有多久，
    避免「SQL 很快，但連線被某段 Python 工作長時間佔住」被誤判成 DB 慢。
    """
    hold_ms = None
    try:
        with _DB_CONN_LOCK:
            checkout_ts = _DB_CONN_CHECKOUT.pop(id(conn), None)
        if checkout_ts is not None:
            hold_ms = (time.monotonic() - checkout_ts) * 1000
    except Exception:
        pass
    if DB_DIAG_ENABLED and hold_ms is not None and hold_ms >= DB_DIAG_HOLD_WARN_MS:
        operation, request_id = _db_diag_context()
        print(
            "🔒 DB連線持有 %.0fms | op=%s | req=%s" %
            (hold_ms, operation, request_id),
            flush=True,
        )
    """
    歸還連線。交易若停在異常狀態，必須先 rollback 再放回，
    否則下一個借到這條連線的人會直接收到
    「current transaction is aborted」而摸不著頭緒。
    """
    if not conn:
        return
    try:
        # 連線處於錯誤或交易中的狀態時先清乾淨
        if conn.closed:
            connection_pool.putconn(conn, close=True)
            return
        if conn.get_transaction_status() not in (
                psycopg2.extensions.TRANSACTION_STATUS_IDLE,):
            conn.rollback()
        connection_pool.putconn(conn)
    except Exception as e:
        print(f"⚠️ 歸還連線失敗，關閉該連線: {e}")
        try:
            connection_pool.putconn(conn, close=True)
        except Exception:
            pass

def _cleanup_legacy_same_day_corrections(cursor, today=None):
    """一次性清理舊版「同日新增後全部刪除」但沒有 delete log 的殘留紀錄。

    同時檢查今天與昨天，因為使用者可能在前一天完成「新增→刪除」，
    今天才第一次重新整理頁面。只有該日全部是正向 add、目前該檔已無持股、
    且更早沒有未歸零的歷史基準時才清理，避免碰到真正的歷史交易。
    """
    try:
        from datetime import timedelta
        day = today or taiwan_today()
        target_days = (day, day - timedelta(days=1))
        removed = 0
        for target_day in target_days:
            cursor.execute("""
                SELECT user_id, code, COALESCE(SUM(shares_delta),0) AS day_delta
                FROM position_change_logs
                WHERE trade_date=%s
                GROUP BY user_id, code
                HAVING BOOL_AND(action='add' AND shares_delta > 0)
            """, (target_day,))
            groups = cursor.fetchall()
            for uid, code, _day_delta in groups:
                cursor.execute(
                    "SELECT COALESCE(SUM(shares),0) FROM positions WHERE user_id=%s AND code=%s",
                    (uid, code))
                if int(cursor.fetchone()[0] or 0) != 0:
                    continue
                cursor.execute(
                    "SELECT COALESCE(SUM(shares_delta),0) FROM position_change_logs "
                    "WHERE user_id=%s AND code=%s AND trade_date < %s",
                    (uid, code, target_day))
                if int(cursor.fetchone()[0] or 0) > 0:
                    continue
                cursor.execute(
                    "DELETE FROM position_change_logs WHERE user_id=%s AND code=%s "
                    "AND trade_date=%s AND action='add' AND shares_delta>0",
                    (uid, code, target_day))
                removed += int(cursor.rowcount or 0)
        return removed
    except Exception as exc:
        print(f"⚠️ 舊版同日撤回紀錄清理失敗：{exc}")
        return 0


def init_db():
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS watchlists (
                user_id TEXT,
                code TEXT,
                PRIMARY KEY (user_id, code)
            )
        ''')
        # 自選股分類（長線／短線／觀察）。用 ALTER 而非寫在 CREATE 裡，
        # 因為 CREATE TABLE IF NOT EXISTS 對既有的表不會補欄位，
        # 舊使用者的自選清單早就建好了，只靠 CREATE 這個欄位永遠不會出現。
        cursor.execute('''
            ALTER TABLE watchlists ADD COLUMN IF NOT EXISTS tag TEXT
        ''')
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS users (
                user_id TEXT PRIMARY KEY,
                notify BOOLEAN DEFAULT FALSE
            )
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS notify BOOLEAN DEFAULT FALSE
        ''')
        # 存 LINE 顯示名稱，這樣在 Supabase 後台才認得出誰是誰，
        # 要開通推播直接把那一列的 notify 改成 true 即可
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS display_name TEXT
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS last_seen TIMESTAMP
        ''')
        # 是否申請過推播，讓管理者一眼看出誰在等開通
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS requested BOOLEAN DEFAULT FALSE
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS anomaly_notify BOOLEAN DEFAULT FALSE
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS anomaly_daily_limit INTEGER DEFAULT 5
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS anomaly_cooldown_minutes INTEGER DEFAULT 60
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS anomaly_s_bypass_limit BOOLEAN DEFAULT TRUE
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS quiet_hours_enabled BOOLEAN DEFAULT FALSE
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS quiet_start SMALLINT DEFAULT 23
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS quiet_end SMALLINT DEFAULT 7
        ''')
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS line_anomaly_sent (
                id BIGSERIAL PRIMARY KEY,
                snapshot_date DATE NOT NULL,
                user_id TEXT NOT NULL,
                event_key TEXT NOT NULL,
                sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                UNIQUE(snapshot_date, user_id, event_key)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_line_anomaly_sent_time
            ON line_anomaly_sent(sent_at DESC)
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS last_feature TEXT
        ''')
        cursor.execute('''
            ALTER TABLE users ADD COLUMN IF NOT EXISTS activity_count INTEGER DEFAULT 0
        ''')
        # 使用者活動紀錄：只記錄功能與時間，不記錄持股內容。
        # 未來若要搬到 Web 管理後台，可直接沿用此表查詢。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS activity_log (
                id BIGSERIAL PRIMARY KEY,
                user_id TEXT NOT NULL,
                feature TEXT NOT NULL,
                action TEXT NOT NULL DEFAULT 'open',
                source TEXT NOT NULL DEFAULT 'line',
                metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
                occurred_at TIMESTAMP NOT NULL DEFAULT NOW()
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_activity_log_user_time
            ON activity_log(user_id, occurred_at DESC)
        ''')
        # LINE 可能因網路或回應逾時重送同一 webhook；用資料庫唯一鍵跨 worker 去重。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS line_event_dedup (
                event_id TEXT PRIMARY KEY,
                received_at TIMESTAMP NOT NULL DEFAULT NOW()
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_line_event_dedup_received
            ON line_event_dedup(received_at DESC)
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_activity_log_feature_time
            ON activity_log(feature, occurred_at DESC)
        ''')
        # ── 網頁版：持股、問卷設定、登入權杖 ──
        # 持股與自選股分開存：自選股是「在看的」，持股是「真的買了的」，
        # 只有後者才有股數與成本，組合分析也只該算後者。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS positions (
                id SERIAL PRIMARY KEY,
                user_id TEXT NOT NULL,
                code TEXT NOT NULL,
                shares INTEGER NOT NULL,
                cost REAL NOT NULL,
                bought_on DATE,
                note TEXT,
                created_at TIMESTAMP DEFAULT NOW()
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_positions_user ON positions (user_id)
        ''')
        # 持股操作日誌：獨立於目前庫存與已實現損益，保留每次加碼／減碼事件。
        # shares_delta 正數代表加碼，負數代表減碼；成交價與備註由使用者輸入或由既有交易流程帶入。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS position_change_logs (
                id BIGSERIAL PRIMARY KEY,
                user_id TEXT NOT NULL,
                code TEXT NOT NULL,
                action TEXT NOT NULL,
                shares_delta INTEGER NOT NULL,
                trade_price REAL,
                trade_date DATE NOT NULL DEFAULT CURRENT_DATE,
                note TEXT,
                source TEXT NOT NULL DEFAULT 'web',
                created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                CONSTRAINT position_change_logs_action_ck
                    CHECK (action IN ('add', 'reduce')),
                CONSTRAINT position_change_logs_shares_ck
                    CHECK (shares_delta <> 0)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_position_change_logs_user_date
            ON position_change_logs (user_id, trade_date DESC, id DESC)
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_position_change_logs_user_code
            ON position_change_logs (user_id, code, trade_date DESC, id DESC)
        ''')
        # V74：一次清理舊版「昨天新增、昨天全部刪除」但殘留在操作日報的資料。
        legacy_removed = _cleanup_legacy_same_day_corrections(cursor)
        if legacy_removed:
            print(f"🧹 V74 舊版同日撤回紀錄已清理：{legacy_removed} 筆")
        # 問卷與門檻設定。前四題必填，其餘可略過，所以全部允許 NULL。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS user_profile (
                user_id TEXT PRIMARY KEY,
                age_band TEXT,
                horizon TEXT,
                asset_share TEXT,
                income_type TEXT,
                drawdown_experience TEXT,
                loss_alert_pct INTEGER,
                position_alert_pct INTEGER,
                check_frequency TEXT,
                holding_period TEXT,
                other_assets TEXT,
                fee_discount REAL,
                min_fee INTEGER,
                updated_at TIMESTAMP DEFAULT NOW()
            )
        ''')
        # 既有資料表不會因 CREATE TABLE IF NOT EXISTS 而新增欄位，
        # 之後補的欄位一律用 ALTER TABLE，否則舊使用者存不進去。
        for _col, _type in [
            ("fee_discount", "REAL"),
            ("min_fee", "INTEGER"),
            ("loss_alert_pct", "INTEGER"),
            ("position_alert_pct", "INTEGER"),
            ("check_frequency", "TEXT"),
            ("holding_period", "TEXT"),
            ("other_assets", "TEXT"),
            ("drawdown_experience", "TEXT"),
        ]:
            cursor.execute(
                f"ALTER TABLE user_profile ADD COLUMN IF NOT EXISTS {_col} {_type}")

        # 網頁登入權杖：LINE 傳「網頁」時產生，點連結即登入，
        # 這樣不必另外做 LINE Login 也不必讓使用者記帳號密碼。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS web_sessions (
                token TEXT PRIMARY KEY,
                user_id TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT NOW(),
                expires_at TIMESTAMP NOT NULL
            )
        ''')
        # 一次性登入驗證碼。
        # LINE 內建瀏覽器的 cookie 跟外部瀏覽器不互通，點連結登入的方式
        # 一換瀏覽器就失效；讓使用者拿一組短碼自己輸入，就能在任何裝置
        # 任何瀏覽器登入，不必再回 LINE 重拿連結。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS web_codes (
                code TEXT PRIMARY KEY,
                user_id TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT NOW(),
                expires_at TIMESTAMP NOT NULL,
                used BOOLEAN DEFAULT FALSE
            )
        ''')
        # 每日三大法人買賣超歷史（用來算「連續買超天數」等長線指標）
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS inst_history (
                code TEXT,
                trade_date DATE,
                name TEXT,
                foreign_net_lots INTEGER,
                trust_net_lots INTEGER,
                dealer_net_lots INTEGER,
                total_net_lots INTEGER,
                PRIMARY KEY (code, trade_date)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_inst_history_code_date
            ON inst_history (code, trade_date DESC)
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_inst_history_trade_date_code
            ON inst_history (trade_date DESC, code)
        ''')
        # 上市公司基本資料（產業別）：抓一次即可，用來做「產業趨勢」分析
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS stock_info (
                code TEXT PRIMARY KEY,
                name TEXT,
                industry TEXT
            )
        ''')
        cursor.execute(
            "ALTER TABLE stock_info ADD COLUMN IF NOT EXISTS market TEXT")
        # 每月營收快照：TWSE 只提供最新一期，歷史必須自己每月累積
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS revenue_history (
                code TEXT,
                period TEXT,
                yoy_pct REAL,
                cum_yoy_pct REAL,
                mom_pct REAL,
                month_revenue REAL,
                PRIMARY KEY (code, period)
            )
        ''')
        # 已實現損益：賣出當下記一筆快照（成本、賣價、損益），
        # 跟目前持股分開存──賣掉之後那筆持股就從 positions 消失了，
        # 沒有這張表就永遠算不出「這一季賺賠多少」「勝率」這類長期指標。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS realized_trades (
                id SERIAL PRIMARY KEY,
                user_id TEXT NOT NULL,
                code TEXT NOT NULL,
                shares INTEGER NOT NULL,
                buy_cost REAL NOT NULL,
                sell_price REAL NOT NULL,
                realized_pl REAL,
                realized_pct REAL,
                bought_on DATE,
                sold_on DATE DEFAULT CURRENT_DATE,
                created_at TIMESTAMP DEFAULT NOW()
            )
        ''')
        # 賣出理由（選填）。用 ALTER 而非改 CREATE：
        # CREATE TABLE IF NOT EXISTS 對既有的表不會補欄位，
        # 舊使用者的 realized_trades 早就建好了，只靠 CREATE 這欄永遠不會出現。
        cursor.execute('''
            ALTER TABLE realized_trades ADD COLUMN IF NOT EXISTS sell_reason TEXT
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_realized_trades_user
            ON realized_trades (user_id, sold_on DESC)
        ''')
        # 賣出時實際付出的手續費與證交稅。使用者自己填才準——
        # 各券商折扣、最低收費、當沖減半都不一樣，程式算的只能是估計值。
        for _col, _type in [("fee", "REAL"), ("tax", "REAL")]:
            cursor.execute(
                f"ALTER TABLE realized_trades ADD COLUMN IF NOT EXISTS {_col} {_type}")
        # 每日組合快照：市值與大盤指數各存一筆，用來畫「我的組合 vs 大盤」走勢圖。
        # 沒有這張表就沒有歷史可畫，所以越早開始存越好，畫圖是之後的事。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS portfolio_snapshots (
                id SERIAL PRIMARY KEY,
                user_id TEXT NOT NULL,
                snapshot_date DATE NOT NULL,
                total_value REAL,
                total_cost REAL,
                taiex_close REAL,
                UNIQUE(user_id, snapshot_date)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_portfolio_snapshots_user
            ON portfolio_snapshots (user_id, snapshot_date)
        ''')
        # 自選股每日評分快照。分數本身每次查都算得出來，但「昨天幾分」算不出來——
        # 沒有這張表就永遠只能顯示靜態分數，看不出誰在變強、誰在轉弱，
        # 而變化往往比絕對分數更有訊號價值。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS watchlist_scores (
                user_id TEXT,
                code TEXT,
                snapshot_date DATE,
                total INTEGER,
                chip INTEGER,
                position INTEGER,
                revenue INTEGER,
                valuation INTEGER,
                close REAL,
                support REAL,
                resistance REAL,
                asset_type TEXT NOT NULL DEFAULT 'stock',
                PRIMARY KEY (user_id, code, snapshot_date)
            )
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores
            ADD COLUMN IF NOT EXISTS asset_type TEXT NOT NULL DEFAULT 'stock'
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS category TEXT
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_revenue INTEGER
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_valuation INTEGER
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_momentum INTEGER
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_streak INTEGER
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_chip_tech INTEGER
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores ADD COLUMN IF NOT EXISTS factor_caps TEXT
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores
            ADD COLUMN IF NOT EXISTS support REAL
        ''')
        cursor.execute('''
            ALTER TABLE watchlist_scores
            ADD COLUMN IF NOT EXISTS resistance REAL
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_watchlist_scores_lookup
            ON watchlist_scores (user_id, code, snapshot_date DESC)
        ''')
        # 產業動能排名的歷史。get_industry_momentum() 每次都算得出當期排名，
        # 但「這個族群是正在變強還是變弱」需要跟過去比，那要自己累積。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS industry_momentum_history (
                industry TEXT,
                snapshot_date DATE,
                p75 REAL,
                median REAL,
                rank INTEGER,
                count INTEGER,
                PRIMARY KEY (industry, snapshot_date)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_industry_momentum_date
            ON industry_momentum_history (snapshot_date DESC)
        ''')
        # 選股成效追蹤：每天把黑馬／雷達選出來的名單存起來，
        # 之後回頭算它們的報酬率。
        # 這是唯一能回答「這套評分到底有沒有用」的方式——
        # 沒有這張表，選股邏輯永遠只是一套說得通但沒被驗證過的規則。
        # 存的是「當下的推薦價」，之後用現價比對即可算出報酬。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS pick_history (
                mode TEXT,
                code TEXT,
                pick_date DATE,
                rank INTEGER,
                score INTEGER,
                name TEXT,
                industry TEXT,
                price REAL,
                PRIMARY KEY (mode, code, pick_date)
            )
        ''')
        # 推薦當下的技術面訊號。用 ALTER 而非改 CREATE：
        # CREATE TABLE IF NOT EXISTS 對既有的表不會補欄位。
        #
        # 為什麼要存：現在無法回答「有黃金交叉的推薦是不是真的比較好」，
        # 因為既有的 51 筆紀錄沒有記下當時有沒有交叉。
        # 不存的話，兩週後想驗證仍然沒有資料，只能繼續憑感覺調權重——
        # 而雷達的分數已經證明過「聽起來合理的指標實際上可能是反向的」。
        cursor.execute('''
            ALTER TABLE pick_history ADD COLUMN IF NOT EXISTS ma_cross TEXT
        ''')
        cursor.execute('''
            ALTER TABLE pick_history ADD COLUMN IF NOT EXISTS macd_cross TEXT
        ''')
        # 各評分成分。只存總分的話，成效分析只能得出「總分沒有預測力」，
        # 卻看不出是哪一項沒用——五項混在一起，
        # 可能其中兩項有效卻被另外三項的雜訊蓋掉。
        for _col in ("score_rev", "score_val", "score_mom",
                     "score_streak", "score_chip"):
            cursor.execute(
                "ALTER TABLE pick_history ADD COLUMN IF NOT EXISTS %s NUMERIC"
                % _col)
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_pick_history_date
            ON pick_history (pick_date DESC, mode)
        ''')
        # 選股完整結果快照：pick_history 只保存前5名供成效追蹤；
        # 這張表保存 warmup 已完成的完整黑馬／雷達清單，供各 worker 快速讀取。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS screener_result_snapshots (
                mode TEXT PRIMARY KEY,
                snapshot_date DATE NOT NULL,
                computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                rows_json JSONB NOT NULL,
                skipped_liquidity INTEGER NOT NULL DEFAULT 0,
                momentum_json JSONB NOT NULL DEFAULT '{}'::jsonb,
                source_meta JSONB NOT NULL DEFAULT '{}'::jsonb
            )
        ''')
        # 選股盤中分數變化歷史：保留同一天前後兩次快照的差異，
        # 讓使用者點進今日黑馬時能直接看到「哪一項變了」。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS screener_score_change_history (
                change_id BIGSERIAL PRIMARY KEY,
                mode TEXT NOT NULL,
                code TEXT NOT NULL,
                snapshot_date DATE NOT NULL,
                changed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                old_score NUMERIC,
                new_score NUMERIC,
                old_factors JSONB NOT NULL DEFAULT '{}'::jsonb,
                new_factors JSONB NOT NULL DEFAULT '{}'::jsonb
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_screener_score_change_today
            ON screener_score_change_history (mode, code, snapshot_date, changed_at DESC)
        ''')
        # 排行榜成員。預設不參加，要自己填暱稱加入——
        # 排行榜會把報酬率給別人看，那跟「持股只用於你自己的分析」是兩件事，
        # 必須明確 opt-in 才不會違背當初給使用者的承諾。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS leaderboard_members (
                user_id TEXT PRIMARY KEY,
                nickname TEXT NOT NULL,
                joined_on DATE DEFAULT CURRENT_DATE,
                created_at TIMESTAMP DEFAULT NOW()
            )
        ''')
        # 是否公開持股內容。獨立於「參加排行榜」之外，預設關閉——
        # 早期加入的人是在「不會顯示持股內容」的承諾下同意的，
        # 不能因為後來加了功能就把他們的持股攤開來。
        cursor.execute(
            "ALTER TABLE leaderboard_members "
            "ADD COLUMN IF NOT EXISTS show_holdings BOOLEAN DEFAULT FALSE")
        # 排行榜每日名次快照：用來顯示昨日到今日的上升／下降與連續天數。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS leaderboard_rank_snapshots (
                board TEXT NOT NULL,
                snapshot_date DATE NOT NULL,
                user_id TEXT NOT NULL,
                rank INTEGER NOT NULL,
                return_pct REAL,
                PRIMARY KEY (board, snapshot_date, user_id)
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_leaderboard_rank_history
            ON leaderboard_rank_snapshots (board, user_id, snapshot_date DESC)
        ''')
        # 共享資料快照：跨 Gunicorn worker／重啟保存非即時、可追溯的來源資料。
        # 網頁優先讀這裡的完整 JSON；資料日與 computed_at 一起保存，避免把舊資料冒充今天。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS shared_data_snapshots (
                snapshot_key TEXT PRIMARY KEY,
                data_date DATE,
                computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                payload JSONB NOT NULL,
                source_meta JSONB NOT NULL DEFAULT '{}'::jsonb
            )
        ''')
        cursor.execute('''
            CREATE INDEX IF NOT EXISTS idx_shared_data_snapshots_computed
            ON shared_data_snapshots (computed_at DESC)
        ''')
        # 背景工作狀態。
        # 原本只存在記憶體，但那有兩個問題：gunicorn 開多個 worker 時，
        # 工作在 A 執行、查詢卻可能連到 B，看到的是空的；服務一重啟也全沒了。
        # 存資料庫就沒有這些問題，而且每個工作只佔一列，成本極低。
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS job_runs (
                name TEXT PRIMARY KEY,
                running BOOLEAN DEFAULT FALSE,
                started_at TIMESTAMP,
                finished_at TIMESTAMP,
                seconds REAL,
                result TEXT,
                run_id TEXT,
                progress_stage TEXT DEFAULT 'industry',
                progress_index INTEGER DEFAULT 0,
                progress_total INTEGER
            )
        ''')
        for _col, _type in [
            ("run_id", "TEXT"),
            ("progress_stage", "TEXT DEFAULT 'industry'"),
            ("progress_index", "INTEGER DEFAULT 0"),
            ("progress_total", "INTEGER"),
        ]:
            cursor.execute(
                f"ALTER TABLE job_runs ADD COLUMN IF NOT EXISTS {_col} {_type}")

        # 早期欄位是 TIMESTAMP WITHOUT TIME ZONE；當時 Render／Supabase
        # 可能以 UTC 寫入，導致管理名單看到的時間少 8 小時。只在欄位仍是
        # 無時區型別時執行一次 migration，避免每次啟動重複轉換。
        timestamp_targets = {
            "users": ("last_seen",),
            "activity_log": ("occurred_at",),
            "job_runs": ("started_at", "finished_at"),
        }
        cursor.execute("""
            SELECT table_name, column_name, data_type
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = ANY(%s)
              AND column_name = ANY(%s)
        """, (list(timestamp_targets),
              [column for columns in timestamp_targets.values() for column in columns]))
        for _table, _column, _data_type in cursor.fetchall():
            if _data_type == "timestamp without time zone":
                cursor.execute(
                    f'''ALTER TABLE "{_table}" ALTER COLUMN "{_column}"
                        TYPE TIMESTAMPTZ
                        USING "{_column}" AT TIME ZONE 'UTC' ''')
        conn.commit()
        cursor.close()
    except Exception as e:
        conn.rollback()
        print(f"❌ 初始化資料庫錯誤: {e}")
    finally:
        release_db_connection(conn)

init_db()

def add_user_to_db(user_id):
    """
    記錄使用者。順便抓 LINE 顯示名稱存起來——沒有名字的話，
    後台看到的只有一串亂碼 user_id，無法判斷要開通誰的推播。
    抓名字失敗不影響主要流程。
    """
    uid = str(user_id).strip()
    name = None
    try:
        name = line_bot_api.get_profile(uid).display_name
    except Exception as e:
        print(f"⚠️ 取得使用者名稱失敗 {uid}: {e}")

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            INSERT INTO users (user_id, display_name, last_seen)
            VALUES (%s, %s, NOW())
            ON CONFLICT (user_id) DO UPDATE SET
                display_name = COALESCE(EXCLUDED.display_name, users.display_name),
                last_seen = NOW()
            """,
            (uid, name)
        )
        conn.commit()
        cursor.close()
    except Exception as e:
        conn.rollback()
        print(f"❌ 新增使用者錯誤: {e}")
    finally:
        release_db_connection(conn)

