def save_revenue_history(period, data):
    """
    存下這一期的月營收快照。TWSE 只給最新一期，所以歷史只能這樣一個月一個月累積。
    累積幾期之後就能算「連續成長月數」。
    """
    if not period or not data:
        return
    rows = [
        (code, str(period),
         info.get("yoy_pct"), info.get("cum_yoy_pct"),
         info.get("mom_pct"), info.get("month_revenue"))
        for code, info in data.items()
    ]

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        execute_values(
            cursor,
            """
            INSERT INTO revenue_history
                (code, period, yoy_pct, cum_yoy_pct, mom_pct, month_revenue)
            VALUES %s
            ON CONFLICT (code, period) DO UPDATE SET
                yoy_pct = EXCLUDED.yoy_pct,
                cum_yoy_pct = EXCLUDED.cum_yoy_pct,
                mom_pct = EXCLUDED.mom_pct,
                month_revenue = EXCLUDED.month_revenue
            """,
            rows,
            page_size=500,
        )
        conn.commit()
        cursor.close()
        print(f"💾 已存入月營收快照（{period}），共 {len(rows)} 檔")
    except Exception as e:
        conn.rollback()
        print(f"❌ 寫入月營收快照失敗（{period}）: {e}")
    finally:
        release_db_connection(conn)


def get_revenue_growth_months(codes, max_months=12):
    """
    算「單月營收年增率連續為正的月數」。需要資料庫累積多期才有意義，
    現在只有一期，所有股票都會是 0 或 1，屬預期行為。
    """
    codes = [str(c).strip() for c in codes]
    if not codes:
        return {}

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT code, period, yoy_pct FROM revenue_history
            WHERE code = ANY(%s)
            ORDER BY code, period DESC
            """,
            (codes,),
        )
        rows = cursor.fetchall()
        cursor.close()
    except Exception as e:
        print(f"❌ 查詢營收連續成長失敗: {e}")
        return {}
    finally:
        release_db_connection(conn)

    series = {}
    for code, _period, yoy in rows:
        series.setdefault(code, []).append(yoy)

    result = {}
    for code in codes:
        streak = 0
        for yoy in series.get(code, [])[:max_months]:
            if yoy is not None and yoy > 0:
                streak += 1
            else:
                break
        result[code] = streak
    return result


# --- 估值資料（TWSE 每日本益比／殖利率／股價淨值比） ---
_valuation_cache = {"date": None, "data": {},
                    "source": "none", "source_date": None}
_VALUATION_FILE_CACHE = "/tmp/stock_bot_valuation_cache.json"
_VALUATION_FILE_CACHE_TTL = 86400
_valuation_file_lock = threading.Lock()
_VALUATION_REFRESH_LOCK = threading.Lock()


def _load_valuation_file_cache(today):
    try:
        with _valuation_file_lock:
            if (not os.path.exists(_VALUATION_FILE_CACHE) or
                    time.time() - os.path.getmtime(_VALUATION_FILE_CACHE) > _VALUATION_FILE_CACHE_TTL):
                return None
            with open(_VALUATION_FILE_CACHE, "r", encoding="utf-8") as fh:
                payload = json.load(fh)
            if payload.get("date") != today or not payload.get("data"):
                return None
            return payload["data"]
    except Exception as exc:
        print(f"⚠️ 讀取估值檔案快取失敗: {exc}")
        return None


def _write_valuation_file_cache(today, data):
    temp_path = _VALUATION_FILE_CACHE + f".{os.getpid()}.tmp"
    try:
        with _valuation_file_lock:
            with open(temp_path, "w", encoding="utf-8") as fh:
                json.dump({"date": today, "data": data}, fh,
                          ensure_ascii=False, separators=(",", ":"))
            os.replace(temp_path, _VALUATION_FILE_CACHE)
    except Exception as exc:
        print(f"⚠️ 寫入估值檔案快取失敗: {exc}")
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass


def fetch_valuation():
    """
    抓全市場本益比、殖利率、股價淨值比。一天快取一次。
    注意：TWSE 的本益比是用「近四季已申報財報」算的歷史本益比，
    不是分析師預估的未來本益比，看的時候要記得這點。
    """
    today = taiwan_now().strftime("%Y%m%d")
    if _valuation_cache["date"] == today and _valuation_cache["data"]:
        return _valuation_cache["data"]

    file_data = _load_valuation_file_cache(today)
    if file_data:
        _valuation_cache["date"] = today
        _valuation_cache["data"] = file_data
        _valuation_cache["source"] = "file"
        _valuation_cache["source_date"] = today
        print("⚡ 估值改讀同日檔案快照，共 %s 筆" % len(file_data))
        return file_data

    shared = _load_shared_data_snapshot("valuation")
    shared_data = (shared.get("payload") if shared else None) or {}
    if isinstance(shared_data, dict) and shared_data:
        _valuation_cache["date"] = today
        _valuation_cache["data"] = shared_data
        _valuation_cache["source"] = "shared"
        _valuation_cache["source_date"] = shared.get("data_date")
        print("⚡ 估值改讀 Supabase 快照（來源日 %s），共 %s 筆" %
              (shared.get("data_date") or "未標日期", len(shared_data)))
        return shared_data

    def to_float(v):
        try:
            f = float(str(v).replace(",", "").strip())
            return f if f > 0 else None
        except (ValueError, TypeError):
            return None

    result = {}
    # 上市與上櫃兩個端點並行抓，不必等第一個回來才發第二個
    twse_url = f"{TWSE_BASE}/exchangeReport/BWIBBU_ALL"
    tpex_url = f"{TPEX_BASE}/tpex_mainboard_peratio_analysis"
    fetched = fetch_json_bulk([twse_url, tpex_url])

    # 上市
    for row in fetched.get(twse_url) or []:
        code = _pick(row, "Code")
        if code:
            result[code] = {"pe": to_float(row.get("PEratio")),
                            "pb": to_float(row.get("PBratio")),
                            "yield": to_float(row.get("DividendYield"))}
    # 上櫃（欄位名稱與上市不同，要另外對應）
    for row in fetched.get(tpex_url) or []:
        code = _pick(row, "SecuritiesCompanyCode", "Code")
        if code:
            result[code] = {"pe": to_float(row.get("PriceEarningRatio")),
                            "pb": to_float(row.get("PriceBookRatio")),
                            "yield": to_float(row.get("YieldRatio"))}

    if result:
        _valuation_cache["date"] = today
        _valuation_cache["data"] = result
        _valuation_cache["source"] = "external"
        _valuation_cache["source_date"] = taiwan_today()
        _write_valuation_file_cache(today, result)
        _save_shared_data_snapshot(
            "valuation", result, data_date=taiwan_today(),
            source_meta={"source": "TWSE+TPEx", "retrieved_on": today},
        )
        print(f"✅ 估值資料抓取成功，共 {len(result)} 筆（含上櫃）")
    return result


def score_from_valuation(pe, growth_pct):
    """
    估值分數（0-25）。用 PEG 概念：本益比 ÷ 成長率。
    這裡的成長率用「累計營收年增率」代替標準PEG的EPS成長率——
    因為免費資料拿不到預估EPS。方向正確，但不是標準PEG。

    重要：PEG 極低（<0.3）通常不是真的便宜，而是景氣循環股從谷底反彈
    造成的失真——營收年增率因去年基期低而暴衝，但本益比用的是過去四季
    獲利，兩者時間軸對不上。循環股最危險的買點恰好就是本益比看起來
    最低的時候，所以這段不給滿分，改為示警。
    回傳 (分數, PEG值或None, 說明)
    """
    if pe is None:
        return 10, None, "無本益比資料（可能虧損或剛上市）"
    if growth_pct is None or growth_pct <= 0:
        if pe <= 12:
            return 14, None, f"本益比 {pe:.1f} 偏低，但缺乏成長性"
        if pe <= 20:
            return 8, None, f"本益比 {pe:.1f}"
        return 3, None, f"本益比 {pe:.1f} 偏高且無成長"

    peg = pe / growth_pct

    # 成長率高到不合常理時，多半是去年基期極低所致，不是本業真的翻倍
    if growth_pct >= 100:
        return 12, peg, (f"本益比 {pe:.1f}，PEG {peg:.2f}\n"
                         f"　　⚠️ 年增 {growth_pct:.0f}% 恐為低基期效應，"
                         f"PEG 失真，需自行查核獲利品質")
    if peg <= 0.3:
        return 15, peg, (f"本益比 {pe:.1f}，PEG {peg:.2f}\n"
                         f"　　⚠️ PEG 異常低，留意是否為景氣循環股高獲利期")
    if peg <= 0.5:
        return 25, peg, f"本益比 {pe:.1f}，PEG {peg:.2f}，明顯低估"
    if peg <= 1.0:
        return 20, peg, f"本益比 {pe:.1f}，PEG {peg:.2f}，估值合理"
    if peg <= 1.5:
        return 13, peg, f"本益比 {pe:.1f}，PEG {peg:.2f}，估值偏高"
    if peg <= 2.5:
        return 6, peg, f"本益比 {pe:.1f}，PEG {peg:.2f}，成長已充分反映"
    return 2, peg, f"本益比 {pe:.1f}，PEG {peg:.2f}，估值昂貴"


def score_stock_by_category(code, ind_map, price, cum_yoy, val, streak,
                            cum_lots, turnover, momentum_stats):
    """
    依股票所屬類別套用對應的評分規則，讓不同類股的分數可以互相比較。
    回傳 dict，金融股回傳 category="金融" 且 total=None（不評分）。
    """
    cat = stock_category(code, ind_map)
    pe = (val or {}).get("pe")
    pb = (val or {}).get("pb")
    dy = (val or {}).get("yield")

    if cat == "金融":
        # 金融股不評分：真正該看的 ROE、利差、逾放比在免費資料中沒有，
        # 硬給分數只會讓人誤以為那個數字有意義。
        return {"category": cat, "total": None, "pe": pe, "pb": pb, "yield": dy,
                "detail": "金融股不評分，僅列事實供判讀"}

    mom_score, mom_desc = score_from_industry_momentum(
        momentum_stats.get(ind_map.get(str(code).strip())))
    streak_score_raw = score_from_streak(streak)
    chip_amount = score_from_chip_amount(
        cum_lots, price.get("avg_price_10d"), price.get("turnover_10d_billion")
    )
    technical_score = score_from_technical_structure(price)
    chip_tech = round(chip_amount + technical_score)

    if cat == "電子":
        rev = round(score_from_cum_revenue_growth(cum_yoy) * 25 / 40)   # 0-25
        val_score, peg, val_desc = score_from_valuation(pe, cum_yoy)     # 0-25
        mom = mom_score                                                  # 0-20
        streak_score = round(streak_score_raw * 20 / 30)                 # 0-20
        caps = ("25", "25", "20", "20", "10")
    else:  # 傳產：成長門檻放低、估值改看 PB 與殖利率、產業動能加重
        rev = score_revenue_traditional(cum_yoy)                         # 0-20
        val_score, val_desc = score_value_traditional(pb, dy, pe)        # 0-25
        peg = (pe / cum_yoy) if (pe and cum_yoy and cum_yoy > 0) else None
        mom = round(mom_score * 25 / 20)                                 # 0-25
        streak_score = round(streak_score_raw * 20 / 30)                 # 0-20
        caps = ("20", "25", "25", "20", "10")

    return {
        "category": cat,
        "total": rev + val_score + mom + streak_score + chip_tech,
        "rev": rev, "val": val_score, "mom": mom,
        "streak_score": streak_score, "chip": chip_tech,
        "chip_amount_score": round(chip_amount, 1),
        "technical_score": round(technical_score, 1),
        "net_amount_billion": (round(float(cum_lots) * float(price.get("avg_price_10d")) / 100_000.0, 2)
                                if cum_lots is not None and price.get("avg_price_10d") is not None else None),
        "turnover_10d_billion": price.get("turnover_10d_billion"),
        "caps": caps, "peg": peg, "pe": pe, "pb": pb, "yield": dy,
        "val_desc": val_desc, "mom_desc": mom_desc,
    }


def _build_factor_details(code, stock, model, cum_yoy, val, streak, cum_lots, category):
    """Build transparent explanations using the SAME color semantics as factor cards.

    Color meaning is intentionally unified everywhere:
      🔴 strong (>=80% of factor max)
      🟡 medium (60-79%)
      🟢 weak (>0-59%)
      ⚪ data / no contribution
    The colors describe scoring strength, not "red=bad / green=good".
    """
    stock = stock or {}
    val = val or {}
    close = stock.get("close")
    ma20 = stock.get("ma20")
    ma20_prev = stock.get("ma20_prev")
    ma60 = stock.get("ma60")
    ma60_prev = stock.get("ma60_prev")
    low10 = stock.get("low_10d")
    high20 = stock.get("high_20d")
    high60 = stock.get("high_60d")
    support = stock.get("support")
    broke_support = bool(stock.get("broke_support"))
    vol_ratio = float(stock.get("vol_ratio") or 0)
    avg_price_10d = stock.get("avg_price_10d")
    turnover10 = stock.get("turnover_10d_billion")

    def fmt_num(v, digits=1):
        try:
            return f"{float(v):.{digits}f}"
        except Exception:
            return "—"

    def signed(v, digits=1, suffix="%"):
        try:
            return f"{float(v):+.{digits}f}{suffix}"
        except Exception:
            return "—"

    def icon(score, max_score):
        try:
            r = float(score) / float(max_score) if float(max_score) > 0 else 0
        except Exception:
            r = 0
        if r >= 0.8:
            return "🔴"
        if r >= 0.6:
            return "🟡"
        if r > 0:
            return "🟢"
        return "⚪"

    # 1) Revenue
    rev_score = float(model.get("rev") or 0)
    rev_max = 25.0 if category == "電子" else 20.0
    if cum_yoy is None:
        rev_lines = ["⚪ 最新累計營收年增率無資料，模型使用缺資料基準分"]
    else:
        rev_lines = [f"{icon(rev_score, rev_max)} 累計營收年增 {signed(cum_yoy)}"]
        if category == "電子":
            if cum_yoy >= 50: bucket = "≥50%，落在最高成長級距"
            elif cum_yoy >= 30: bucket = "30%～49.9%，落在高成長級距"
            elif cum_yoy >= 20: bucket = "20%～29.9%，落在成長級距"
            elif cum_yoy >= 10: bucket = "10%～19.9%，落在中度成長級距"
            elif cum_yoy >= 5: bucket = "5%～9.9%，落在低度成長級距"
            elif cum_yoy > 0: bucket = "0%～4.9%，僅保留小幅成長分"
            elif cum_yoy > -10: bucket = "-10%～0%，進入衰退級距"
            else: bucket = "≤-10%，進入最弱級距"
        else:
            if cum_yoy >= 25: bucket = "≥25%，傳產成長最高級距"
            elif cum_yoy >= 15: bucket = "15%～24.9%"
            elif cum_yoy >= 10: bucket = "10%～14.9%"
            elif cum_yoy >= 5: bucket = "5%～9.9%"
            elif cum_yoy > 0: bucket = "0%～4.9%"
            elif cum_yoy > -10: bucket = "-10%～0%"
            else: bucket = "≤-10%"
        rev_lines.append(f"⚪ {bucket} → 營收成長 {rev_score:.0f}/{rev_max:.0f}")
    rev_lines.append(f"⚪ 本因子權重上限 {rev_max:.0f} 分")

    # 2) Valuation
    val_score = float(model.get("val") or 0)
    val_max = 25.0
    val_lines = []
    pe = val.get("pe")
    pb = val.get("pb")
    dy = val.get("yield")
    if category == "電子":
        peg = model.get("peg")
        if pe is not None: val_lines.append(f"⚪ PE {fmt_num(pe)} 倍")
        else: val_lines.append("⚪ PE 無資料")
        if cum_yoy is not None and float(cum_yoy) > 0 and pe is not None:
            val_lines.append(f"⚪ 估值模型使用 PE ÷ 累計營收成長率，PEG ≈ {fmt_num(peg,2) if peg is not None else '—'}")
        elif cum_yoy is not None:
            val_lines.append(f"⚪ 累計營收年增 {signed(cum_yoy)}")
        desc = model.get("val_desc")
        if desc: val_lines.append("⚪ " + str(desc).replace("\n", " ").strip())
    else:
        if pb is not None: val_lines.append(f"⚪ PB {fmt_num(pb,2)} 倍")
        else: val_lines.append("⚪ PB 無資料")
        if dy is not None: val_lines.append(f"⚪ 殖利率 {fmt_num(dy,2)}%")
        else: val_lines.append("⚪ 殖利率無資料")
        if pe is not None: val_lines.append(f"⚪ PE {fmt_num(pe)} 倍（輔助）")
        desc = model.get("val_desc")
        if desc: val_lines.append("⚪ " + str(desc).replace("\n", " ").strip())
    val_lines.append(f"{icon(val_score, val_max)} 本因子得分 {val_score:.0f}/{val_max:.0f}")

    # 3) Industry momentum
    mom_score = float(model.get("mom") or 0)
    mom_max = 20.0 if category == "電子" else 25.0
    mom_desc = str(model.get("mom_desc") or "產業動能資料不足").replace("\n", " ").strip()
    mom_lines = ["⚪ " + mom_desc, f"{icon(mom_score, mom_max)} 本因子得分 {mom_score:.0f}/{mom_max:.0f}"]

    # 4) Institutional continuity
    streak_score = float(model.get("streak_score") or 0)
    streak_max = 20.0
    streak_val = int(streak or 0)
    if streak_val >= 8: streak_bucket = "≥8天 → 原始30分"
    elif streak_val >= 5: streak_bucket = "5～7天 → 原始25分"
    elif streak_val >= 3: streak_bucket = "3～4天 → 原始18分"
    elif streak_val >= 2: streak_bucket = "2天 → 原始10分"
    elif streak_val >= 1: streak_bucket = "1天 → 原始5分"
    else: streak_bucket = "0天 → 原始0分"
    streak_lines = [
        f"{icon(streak_score, streak_max)} 法人連續買超 {streak_val} 天",
        f"⚪ {streak_bucket}",
        f"{icon(streak_score, streak_max)} 換算後法人連續性 {streak_score:.0f}/{streak_max:.0f}",
    ]

    # 5) Chip / technical
    chip_score = float(model.get("chip_amount_score") or 0)
    tech_score = float(model.get("technical_score") or 0)
    chip_tech_score = float(model.get("chip") or 0)
    chip_lines = []
    if cum_lots is None or avg_price_10d is None or turnover10 is None:
        chip_lines.append("⚪ 法人資金強度資料不足")
    else:
        net_amt = model.get("net_amount_billion")
        ratio = (float(net_amt) / float(turnover10) * 100.0) if float(turnover10 or 0) > 0 and net_amt is not None else None
        direction = "淨買超" if float(cum_lots) > 0 else "淨賣超／無買超"
        chip_lines.append(f"{icon(chip_score, 5)} 近10日法人{direction} {float(cum_lots):+.0f} 張")
        chip_lines.append(f"⚪ 換算淨買超金額約 {fmt_num(net_amt,2)} 億元")
        chip_lines.append(f"⚪ 占近10日成交金額 {signed(ratio) if ratio is not None else '—'}")
    chip_lines.append(f"{icon(chip_score, 5)} 籌碼子分數 {chip_score:.1f}/5")

    tech_lines = []
    if close is None:
        tech_lines.append("⚪ 股價資料不足，無法判斷技術結構")
    else:
        if ma20 is not None:
            diff20 = (float(close)-float(ma20))/float(ma20)*100 if ma20 else 0
            tech_lines.append(f"{icon(tech_score, 5)} 股價 {fmt_num(close,2)} {'站上' if close >= ma20 else '跌破'} 20MA {fmt_num(ma20,2)}（{signed(diff20)}）")
            if ma20_prev is not None:
                tech_lines.append(f"{icon(tech_score, 5)} 20MA {'向上' if ma20 > ma20_prev else '向下或持平'}（前值 {fmt_num(ma20_prev,2)}）")
        else:
            tech_lines.append("⚪ 20MA 資料不足")
        if ma60 is not None:
            tech_lines.append(f"{icon(tech_score, 5)} 股價 {'站上' if close >= ma60 else '跌破'} 60MA {fmt_num(ma60,2)}")
            if ma60_prev is not None:
                tech_lines.append(f"{icon(tech_score, 5)} 60MA {'向上' if ma60 > ma60_prev else '向下或持平'}")
        if low10 is not None and ma20 is not None and close >= ma20 and low10 <= ma20*1.03:
            tech_lines.append(f"{icon(tech_score, 5)} 近10日曾回踩20MA附近，之後重新站在20MA上方")
        elif support is not None and not broke_support and low10 is not None and low10 <= support*1.03:
            tech_lines.append(f"{icon(tech_score, 5)} 近10日曾回踩支撐 {fmt_num(support,2)} 附近且未有效跌破")
        else:
            tech_lines.append("⚪ 未偵測到明確的近期均線／支撐回踩訊號")
        if high20 is not None and close > high20:
            tech_lines.append(f"{icon(tech_score, 5)} 突破近20日高點")
        else:
            tech_lines.append("⚪ 尚未突破近20日高點")
        if high60 is not None and close >= high60:
            tech_lines.append(f"{icon(tech_score, 5)} 站上近60日高點")
        if high20 is not None and close > high20 and vol_ratio >= 1.3:
            tech_lines.append(f"{icon(tech_score, 5)} 突破時量能約為20日均量 {vol_ratio:.2f} 倍")
        elif vol_ratio >= 1.5 and close >= (ma20 or close):
            tech_lines.append(f"🟡 上攻時量能約為20日均量 {vol_ratio:.2f} 倍")
        else:
            tech_lines.append(f"⚪ 目前量能約為20日均量 {vol_ratio:.2f} 倍，未因量能額外加分")
    tech_lines.append(f"{icon(tech_score, 5)} 技術子分數 {tech_score:.1f}/5")
    chip_lines.append(f"{icon(chip_tech_score, 10)} 籌碼／技術合計 {chip_tech_score:.0f}/10")

    return [
        {"name": "營收成長", "lines": rev_lines},
        {"name": "估值", "lines": val_lines},
        {"name": "產業動能", "lines": mom_lines},
        {"name": "法人連續性", "lines": streak_lines},
        {"name": "籌碼／技術", "lines": ["<b>籌碼 5 分</b>"] + chip_lines + ["<b>技術 5 分</b>"] + tech_lines},
    ]


def get_industry_momentum(revenue_data, industry_map):
    """
    用真實資料推導「產業動能」：把全市場月營收依產業別加總，
    算出各產業的累計營收年增率中位數，排出哪些族群整體需求在成長。

    這是用資料反推需求，不是預測。產業營收集體暴衝，通常就代表
    該環節供不應求、產品在漲價——跟研究機構說的「供給緊張」是同一件事，
    差別在這是已發生的驗證，而且每月自動更新，不需人工維護。

    回傳 {產業代碼: {"median": 中位數年增率, "count": 家數, "rank": 名次}}
    """
    buckets = {}
    for code, info in (revenue_data or {}).items():
        ind = industry_map.get(code)
        if not ind:
            continue
        cum = info.get("cum_yoy_pct")
        if cum is None:
            continue
        buckets.setdefault(ind, []).append(cum)

    stats = {}
    for ind, values in buckets.items():
        if len(values) < 3:  # 家數太少的產業，統計值沒有代表性
            continue
        values.sort()
        n = len(values)
        median = values[n // 2] if n % 2 else (values[n // 2 - 1] + values[n // 2]) / 2
        # 用第75百分位（領先群跑多快），而不是中位數。
        # 大產業動輒六七十家，中位數會被一堆平庸公司拉平，各產業幾乎沒差別；
        # 看領先群才分得出哪個族群真的有一批公司在噴。
        p75 = values[min(n - 1, int(n * 0.75))]
        stats[ind] = {"median": round(median, 1), "p75": round(p75, 1), "count": n}

    for rank, (ind, _s) in enumerate(
        sorted(stats.items(), key=lambda x: x[1]["p75"], reverse=True), start=1
    ):
        stats[ind]["rank"] = rank

    return stats


def save_industry_momentum(stats):
    """
    存下這一期的產業動能排名。營收一個月才更新一期，所以這張表長得很慢，
    但沒有它就只能看到「現在誰最強」，看不到「誰正在變強」——
    後者才是抓題材轉換的依據。
    """
    if not stats:
        return
    rows = [(ind, s.get("p75"), s.get("median"), s.get("rank"), s.get("count"))
            for ind, s in stats.items()]
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        execute_values(
            cursor,
            """
            INSERT INTO industry_momentum_history
                (industry, snapshot_date, p75, median, rank, count)
            VALUES %s
            ON CONFLICT (industry, snapshot_date) DO UPDATE SET
                p75 = EXCLUDED.p75, median = EXCLUDED.median,
                rank = EXCLUDED.rank, count = EXCLUDED.count
            """,
            rows,
            template="(%s, CURRENT_DATE, %s, %s, %s, %s)",
            page_size=200,
        )
        conn.commit()
        cursor.close()
        print(f"💾 已存入產業動能排名，共 {len(rows)} 個產業")
    except Exception as e:
        conn.rollback()
        print(f"❌ 寫入產業動能排名失敗: {e}")
    finally:
        release_db_connection(conn)


def save_picks(mode, rows, top_n=5):
    """
    存下今天這個模式選出的前 N 名。同一天重複跑會覆蓋，cron 跑兩次不會重複。
    存「當下價格」是關鍵——之後要算報酬得知道推薦當天是多少錢，
    事後再回頭抓歷史價會對不上（推薦時是盤中價，收盤價又是另一個數字）。
    """
    if not rows:
        return 0
    # 一併存下各評分成分。
    #
    # 先前只存總分，成效分析就只能得出「總分沒有預測力」這種結論，
    # 卻看不出是哪一項沒用——五個成分混在一起，
    # 可能其中兩項有效、被另外三項的雜訊蓋掉。
    # 要據以調整權重，就得逐項對照後續報酬。
    def _pick_num(r, *keys):
        # 相容不同版本的欄位名稱；非數字維持 NULL，不猜值。
        for key in keys:
            v = r.get(key) if isinstance(r, dict) else None
            if v is None or v == "" or isinstance(v, bool):
                continue
            try:
                v = float(v)
                if math.isfinite(v):
                    return v
            except (TypeError, ValueError, OverflowError):
                continue
        return None

    picks = []
    for i, r in enumerate(rows[:top_n], start=1):
        picks.append((
            mode, r["code"], i, r.get("score"), r.get("name"),
            r.get("industry"), r.get("close"),
            r.get("ma_cross"), r.get("macd_cross"),
            _pick_num(r, "score_rev", "rev", "revenue_score", "revenue"),
            _pick_num(r, "score_val", "val", "valuation_score", "valuation"),
            _pick_num(r, "score_mom", "mom", "industry_score", "momentum_score"),
            _pick_num(r, "score_streak", "streak_score", "continuity_score", "streak"),
            _pick_num(r, "score_chip", "chip", "chip_score", "technical_score"),
        ))
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        execute_values(
            cursor,
            """
            INSERT INTO pick_history
                (mode, code, pick_date, rank, score, name, industry, price,
                 ma_cross, macd_cross,
                 score_rev, score_val, score_mom, score_streak, score_chip)
            VALUES %s
            ON CONFLICT (mode, code, pick_date) DO UPDATE SET
                rank = EXCLUDED.rank, score = EXCLUDED.score,
                name = EXCLUDED.name, industry = EXCLUDED.industry,
                price = EXCLUDED.price,
                ma_cross = EXCLUDED.ma_cross, macd_cross = EXCLUDED.macd_cross,
                score_rev = COALESCE(EXCLUDED.score_rev, pick_history.score_rev),
                score_val = COALESCE(EXCLUDED.score_val, pick_history.score_val),
                score_mom = COALESCE(EXCLUDED.score_mom, pick_history.score_mom),
                score_streak = COALESCE(EXCLUDED.score_streak, pick_history.score_streak),
                score_chip = COALESCE(EXCLUDED.score_chip, pick_history.score_chip)
            """,
            picks,
            template="(%s, %s, CURRENT_DATE, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
            page_size=100,
        )
        conn.commit()
        cursor.close()
        print(f"💾 已存入 {mode} 選股名單，共 {len(picks)} 檔")
        return len(picks)
    except Exception as e:
        conn.rollback()
        print(f"❌ 寫入選股名單失敗: {e}")
        return 0
    finally:
        release_db_connection(conn)


def get_picks_since(mode, days=90):
    """取近 N 天的選股名單，供成效計算。"""
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT code, pick_date, rank, score, name, industry, price,
                   ma_cross, macd_cross,
                   score_rev, score_val, score_mom, score_streak, score_chip
            FROM pick_history
            WHERE mode = %s AND pick_date >= CURRENT_DATE - %s
              AND price IS NOT NULL AND price > 0
            ORDER BY pick_date DESC, rank
            """,
            (mode, days),
        )
        rows = cursor.fetchall()
        cursor.close()
        return [{"code": r[0], "date": r[1], "rank": r[2], "score": r[3],
                 "name": r[4], "industry": r[5], "price": r[6],
                 "ma_cross": r[7], "macd_cross": r[8],
                 "score_rev": r[9], "score_val": r[10], "score_mom": r[11],
                 "score_streak": r[12], "score_chip": r[13]} for r in rows]
    except Exception as e:
        print(f"❌ 讀取選股名單失敗: {e}")
        return []
    finally:
        release_db_connection(conn)


def _pick_return_split_safe(cur, pick_date, raw_price):
    """
    計算推薦至今報酬，額外處理股票面額變更／換股造成的機械性價格縮放。

    Yahoo adjclose 主要處理除權息，但不一定會把台股面額變更
    （例如 10 元面額改 0.5 元、1 股換 20 股）當成 split 修正。
    這類事件會讓價格看起來瞬間變成 1/20，但投資人的經濟價值沒有
    瞬間剩 1/20，因此不能把它當成 -95%/-96% 的選股虧損。

    只在價格跳變接近常見整數倍／分割倍數，而且 Yahoo adjclose
    也同步跳變時視為結構性縮放；一般大跌不會因為只是跌很多就自動修正。
    """
    if not cur or not raw_price:
        return None, False, False
    if isinstance(pick_date, datetime):
        pick_date = pick_date.date()
    elif isinstance(pick_date, str):
        try:
            pick_date = datetime.fromisoformat(pick_date[:10]).date()
        except (TypeError, ValueError):
            try:
                pick_date = datetime.strptime(pick_date[:10], "%Y-%m-%d").date()
            except (TypeError, ValueError):
                return None, False, False
    if not isinstance(pick_date, date):
        return None, False, False
    dates = cur.get("close_dates") or []
    closes = cur.get("closes") or []
    adjs = cur.get("adj_closes") or []
    if not (dates and closes and len(dates) == len(closes)):
        return None, False, False
    idx = next((i for i, d in enumerate(dates) if d >= pick_date), None)
    if idx is None or idx >= len(closes) or not closes[idx] or not closes[-1]:
        return None, False, False

    start_adj = (adjs[idx] if len(adjs) == len(dates) and adjs[idx]
                 else closes[idx])
    end_adj = (adjs[-1] if len(adjs) == len(dates) and adjs[-1]
               else closes[-1])
    use_yahoo_adj = len(adjs) == len(dates) and bool(adjs[idx]) and bool(adjs[-1])

    scale = 1.0
    common_ratios = (0.05, 0.1, 0.2, 0.25, 1/3, 0.5, 2.0, 3.0, 4.0, 5.0, 10.0, 20.0)
    split_detected = False
    for j in range(max(idx + 1, 1), len(closes)):
        prev = closes[j - 1]
        cur_close = closes[j]
        if not prev or not cur_close:
            continue
        rr = cur_close / prev
        if rr <= 0.25 or rr >= 4.0:
            nearest = min(common_ratios, key=lambda x: abs(x - rr))
            if abs(rr / nearest - 1.0) <= 0.03:
                adj_ok = True
                if len(adjs) == len(dates) and j > 0 and adjs[j] and adjs[j - 1]:
                    ar = adjs[j] / adjs[j - 1]
                    adj_ok = abs(ar / rr - 1.0) <= 0.03
                if adj_ok:
                    split_detected = True
                    if rr < 1:
                        scale /= rr
                    else:
                        scale *= rr

    if split_detected:
        end_adj *= scale
        return (end_adj - start_adj) / start_adj * 100, True, True
    if use_yahoo_adj:
        return (end_adj - start_adj) / start_adj * 100, True, False
    return (closes[-1] - raw_price) / raw_price * 100, False, False



def _score_validation_horizon_return(cur, pick_date, raw_price, horizon):
    """以推薦日後第 N 個交易日收盤計算價格報酬；只使用推薦當下已知的 score。"""
    if not cur or not raw_price:
        return None
    dates=cur.get("close_dates") or []
    closes=cur.get("closes") or []
    if not dates or not closes or len(dates)!=len(closes):
        return None
    if isinstance(pick_date, datetime):
        pick_date=pick_date.date()
    elif isinstance(pick_date,str):
        try: pick_date=datetime.fromisoformat(pick_date[:10]).date()
        except Exception: return None
    if not isinstance(pick_date,date):
        return None
    idx=None
    for i,d in enumerate(dates):
        try:
            dd=d.date() if isinstance(d,datetime) else (datetime.fromisoformat(str(d)[:10]).date() if isinstance(d,str) else d)
            if dd>=pick_date:
                idx=i; break
        except Exception:
            continue
    if idx is None or idx+horizon>=len(closes):
        return None
    try:
        start=float(raw_price); end=float(closes[idx+horizon])
    except (TypeError,ValueError):
        return None
    if start<=0 or end<=0:
        return None
    # 還原面額變更／split，避免把機械性 1/20 變價當成真實虧損。
    scale=1.0; split=False
    ratios=(0.05,0.1,0.2,0.25,1/3,0.5,2.0,3.0,4.0,5.0,10.0,20.0)
    for j in range(idx+1,idx+horizon+1):
        try: prev=float(closes[j-1]); now=float(closes[j])
        except (TypeError,ValueError): continue
        if prev<=0 or now<=0: continue
        rr=now/prev
        if rr<=0.25 or rr>=4.0:
            nearest=min(ratios,key=lambda x:abs(x-rr))
            if abs(rr/nearest-1.0)<=0.03:
                split=True
                scale *= (1.0/rr if rr<1 else rr)
    if split:
        end*=scale
    ret=(end-start)/start*100.0
    return ret if math.isfinite(ret) else None


def _score_validation(mode, days=180, code=None):
    """驗證「推薦當下分數」與後續 5/10/20 個交易日價格報酬的關聯。
    不改任何選股規則；只做 out-of-sample 回看，並明確排除尚未成熟樣本。
    """
    picks=get_picks_since(mode,days)
    if code:
        code=normalize_code(code)
        picks=[p for p in picks if normalize_code(p.get('code',''))==code]
    if not picks:
        return {"mode":mode,"n_total":0,"mature":{},"history":[]}
    # 個股展開時只抓這一檔，不能把 180 天全部推薦股票一起抓；否則一個詳情抽屜就可能觸發數十／上百檔 Yahoo 請求，容易造成 HTTP 500 或逾時。
    pick_codes={normalize_code(p.get('code')) for p in picks if p.get('code')}
    if code:
        pick_codes={code}
    try:
        price_map=get_realtime_stocks_bulk(sorted(pick_codes),workers=8,rng='1y') if pick_codes else {}
    except Exception as e:
        print(f'⚠️ 分數驗證行情抓取失敗 {mode} {code}: {type(e).__name__}: {e}')
        price_map={}
    today=taiwan_today()
    horizons=(5,10,20)
    all_rows=[]
    for p in picks:
        pd=p.get('date')
        if isinstance(pd,datetime): pd=pd.date()
        if isinstance(pd,str):
            try: pd=datetime.fromisoformat(pd[:10]).date()
            except Exception: continue
        if not isinstance(pd,date): continue
        score=None
        try:
            if p.get('score') is not None and str(p.get('score')).strip()!='': score=float(p['score'])
        except Exception: score=None
        raw_code=p.get("code")
        raw_rank=p.get("rank")
        raw_price=p.get("price")
        try:
            safe_rank=int(raw_rank) if raw_rank is not None else None
        except Exception:
            safe_rank=None
        try:
            safe_price=float(raw_price) if raw_price is not None else None
        except Exception:
            safe_price=None
        row={"code":normalize_code(raw_code) if raw_code else "","name":str(p.get("name") or ""),"date":pd.isoformat(),"rank":safe_rank,"score":score,"price":safe_price}
        cur=price_map.get(normalize_code(p.get("code")))
        for h in horizons:
            row[f'r{h}']=_score_validation_horizon_return(cur,pd,p.get('price'),h)
        all_rows.append(row)
    def nums(key, rows):
        return [r[key] for r in rows if isinstance(r.get(key),(int,float)) and not isinstance(r.get(key),bool) and math.isfinite(float(r[key]))]
    def med(vals):
        if not vals:return None
        a=sorted(float(x) for x in vals); n=len(a)
        return a[n//2] if n%2 else (a[n//2-1]+a[n//2])/2
    def pearson(rows,key):
        pairs=[]
        for r in rows:
            if r.get('score') is None or r.get(key) is None: continue
            pairs.append((float(r['score']),float(r[key])))
        n=len(pairs)
        if n<5:return None
        mx=sum(x for x,y in pairs)/n; my=sum(y for x,y in pairs)/n
        denx=sum((x-mx)**2 for x,y in pairs); deny=sum((y-my)**2 for x,y in pairs)
        if denx<=0 or deny<=0:return None
        return sum((x-mx)*(y-my) for x,y in pairs)/(denx*deny)**0.5
    result={"mode":mode,"n_total":len(all_rows),"history":all_rows if code else [],"mature":{}}
    for h in horizons:
        key=f'r{h}'; mature=[r for r in all_rows if r.get(key) is not None]
        scored=[r for r in mature if r.get('score') is not None]
        if scored:
            cut=sorted(r['score'] for r in scored)[len(scored)//2]
            hi=[r for r in scored if r['score']>=cut]; lo=[r for r in scored if r['score']<cut]
            hiavg=sum(r[key] for r in hi)/len(hi) if hi else None
            loavg=sum(r[key] for r in lo)/len(lo) if lo else None
            gap=hiavg-loavg if hiavg is not None and loavg is not None else None
            avg=sum(r[key] for r in mature)/len(mature)
            # 圖表資料：每一筆成熟推薦保留「當下分數 × 後續報酬」，前端直接畫散點，不重新計分。
            points=[{"score":float(r['score']),"return":float(r[key]),"date":r.get('date'),"code":r.get('code'),"name":r.get('name')} for r in scored if r.get(key) is not None and math.isfinite(float(r['score'])) and math.isfinite(float(r[key]))]
            result['mature'][str(h)]={"n":len(mature),"score_n":len(scored),"days":len(set(r['date'] for r in mature)),"avg":avg,"median":med(nums(key,mature)),"win":sum(1 for r in mature if r[key]>0)/len(mature)*100,"corr":pearson(scored,key),"cut":cut,"high_avg":hiavg,"low_avg":loavg,"gap":gap,"high_n":len(hi),"low_n":len(lo),"points":points}
        else:
            result['mature'][str(h)]={"n":len(mature),"score_n":0,"days":len(set(r['date'] for r in mature)),"avg":None,"median":med(nums(key,mature)),"win":sum(1 for r in mature if r[key]>0)/len(mature)*100 if mature else None,"corr":None}
    if code:
        result['verdict']='個股歷史樣本僅供觀察；樣本少於10筆不做準確度結論。'
    else:
        result['verdict']='只有在成熟樣本、推薦日分散且高低分組各至少10筆時，才把分數差異當成調權重依據。'
    return result

def evaluate_picks(mode, days=90):
    """
    計算選股成效：把每一筆推薦的當時價格跟現價比，並依「推薦後經過幾天」分組。

    誠實度的幾個要求：
    ・用現價算報酬，所以一筆推薦只能歸入一個天期——70 天前的推薦拿現價算，
      得到的是 70 天的報酬不是 5 天的。因此由長到短判斷，取它已經走過的
      最長區間，標籤也照實寫成區間而非定點。
    ・同時算大盤同期報酬做對照。多頭時什麼都在漲，沒有對照組的話
      「平均 +5%」看不出是選股有效還是單純市場好。
    ・樣本數一併呈現，讓人自己判斷這個數字可不可信。
    """
    picks = get_picks_since(mode, days)
    if not picks:
        return None

    # 抓長一點的區間：要能涵蓋最舊一筆推薦的日期，才找得到那天的還原價。
    # 除權息當天股價機械性下跌，用未還原價比較會把配息記成虧損，
    # 而 8～9 月正是台股除權息旺季，不修正會系統性低估成效。
    span = "1y" if days > 120 else "6mo"
    price_map = get_realtime_stocks_bulk(
        list({p["code"] for p in picks}), workers=16, rng=span)
    today = taiwan_today()

    def pick_return(code, pick_date, raw_price):
        ret, adjusted, _split_detected = _pick_return_split_safe(
            price_map.get(code), pick_date, raw_price)
        return ret, adjusted

    # 大盤對照：用快照裡存的加權指數，沒有就退回不比較
    taiex_by_date = {}
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT DISTINCT snapshot_date, taiex_close FROM portfolio_snapshots
            WHERE taiex_close IS NOT NULL AND snapshot_date >= CURRENT_DATE - %s
            """,
            (days,))
        taiex_by_date = {r[0]: r[1] for r in cursor.fetchall()}
        cursor.close()
    except Exception as e:
        print(f"⚠️ 讀取大盤對照失敗: {e}")
    finally:
        release_db_connection(conn)

    taiex_now = None
    t = fetch_taiex_summary()
    if t and t.get("close"):
        try:
            taiex_now = float(str(t["close"]).replace(",", ""))
        except (TypeError, ValueError):
            taiex_now = None

    horizons = [(60, "60 日以上"), (20, "20–59 日"), (5, "5–19 日")]
    buckets = {label: [] for _d, label in horizons}
    market = {label: [] for _d, label in horizons}

    for p in picks:
        cur = price_map.get(p["code"])
        if not cur:
            continue
        elapsed = (today - p["date"]).days
        ret, adjusted = pick_return(p["code"], p["date"], p["price"])
        if ret is None:
            continue
        p = {**p, "adjusted": adjusted}
        for d, label in horizons:       # 由長到短，落在第一個符合的區間
            if elapsed >= d:
                buckets[label].append((ret, p))
                base = taiex_by_date.get(p["date"])
                if base and taiex_now:
                    market[label].append((taiex_now - base) / base * 100)
                break

    result = {}
    for _d, label in reversed(horizons):   # 顯示時由短到長
        vals = [r for r, _p in buckets[label]]
        if not vals:
            continue
        vals_sorted = sorted(vals)
        n = len(vals_sorted)
        median = (vals_sorted[n // 2] if n % 2
                  else (vals_sorted[n // 2 - 1] + vals_sorted[n // 2]) / 2)
        mk = market[label]
        samples = []
        for sample_ret, sample_pick in buckets[label]:
            sample_base = taiex_by_date.get(sample_pick["date"])
            sample_market = None
            if sample_base and taiex_now:
                sample_market = (taiex_now - sample_base) / sample_base * 100
            samples.append({
                "date": sample_pick["date"],
                "code": sample_pick["code"],
                "name": sample_pick.get("name") or sample_pick["code"],
                "rank": sample_pick.get("rank"),
                "score": sample_pick.get("score"),
                "ret": sample_ret,
                "adjusted": bool(sample_pick.get("adjusted")),
                "market": sample_market,
                "excess": (sample_ret - sample_market)
                          if sample_market is not None else None,
            })
        result[label] = {
            "n": n,
            "avg": sum(vals) / n,
            "median": median,
            "win_rate": len([v for v in vals if v > 0]) / n * 100,
            "best": max(buckets[label], key=lambda x: x[0]),
            "worst": min(buckets[label], key=lambda x: x[0]),
            "market": (sum(mk) / len(mk)) if mk else None,
            "samples": samples,
        }

    pending = len([p for p in picks if (today - p["date"]).days < 5])
    # 有多少筆真的用了還原價。若這個數字是 0，代表 Yahoo 沒回傳 adjclose，
    # 那結果就跟修正前一樣，不該以為除權息已經處理好了。
    counted = [pk for _lbl, rows in buckets.items() for _r, pk in rows]
    adjusted_n = len([pk for pk in counted if pk.get("adjusted")])
    return {"horizons": result, "total_picks": len(picks), "pending": pending,
            "adjusted_n": adjusted_n, "counted_n": len(counted)}


def score_from_industry_momentum(ind_stats):
    """
    產業動能分數（0-20）。看的是「這檔股票所在的產業，領先群跑得多快」，
    而不是這一家公司自己好不好——後者已由營收成長那項評分。
    回傳 (分數, 說明文字)
    """
    if not ind_stats:
        return 8, "產業動能資料不足"

    p75 = ind_stats["p75"]
    median = ind_stats["median"]
    rank = ind_stats.get("rank")
    count = ind_stats["count"]
    detail = f"（前25%為 {p75:+.1f}%、中位 {median:+.1f}%，{count} 家，排名第 {rank}）"

    if p75 >= 80:
        return 20, f"族群領先群強勁噴發{detail}"
    if p75 >= 50:
        return 17, f"族群領先群高速成長{detail}"
    if p75 >= 30:
        return 14, f"族群領先群成長明確{detail}"
    if p75 >= 15:
        return 10, f"族群領先群穩健成長{detail}"
    if p75 > 0:
        return 5, f"族群成長有限{detail}"
    return 1, f"族群整體衰退{detail}"


# ── 類股分類與各自的評分規則 ──
# 電子、傳產、金融三類的財務結構差很多，用同一套標準會系統性失真：
#   電子成長股 → 看 PEG，營收年增 15% 只算普通
#   傳產循環股 → 看 PB 與殖利率，營收年增 15% 已經很好；
#                而且景氣循環股最危險的時候正好是本益比最低的時候
#   金融股     → 「營收」是利息與投資收益，且真正該看的 ROE、利差、
#                逾放比在免費資料裡都沒有，因此不評分，只列事實
ELECTRONIC_INDUSTRIES = {
    "13",  # 電子工業（舊總類）
    "24",  # 半導體業
    "25",  # 電腦及週邊設備業
    "26",  # 光電業
    "27",  # 通信網路業
    "28",  # 電子零組件業
    "29",  # 電子通路業
    "30",  # 資訊服務業
    "31",  # 其他電子業
    "36",  # 數位雲端
}

# ── BOT 自訂類股歸類 ──
# 這裡不是覆蓋證交所官方產業分類，而是「五大因子評分模型」的分析分組。
# 例如 8996 高力官方產業分類屬電機機械／傳統產業，
# 但因使用者希望在本 BOT 中把它視為電子股，因此套用電子股評分規則。
CUSTOM_ELECTRONIC_CODES = {
    "8996",  # 高力：BOT 分析上歸入電子股
}


def stock_category(code, ind_map):
    """回傳 電子 / 金融 / 傳產；BOT 可用自訂代碼覆蓋官方產業分類。"""
    code = str(code).strip()
    raw = ind_map.get(code)
    ind = str(raw).strip().zfill(2) if raw else ""
    if ind == "17":
        return "金融"
    if code in CUSTOM_ELECTRONIC_CODES or ind in ELECTRONIC_INDUSTRIES:
        return "電子"
    return "傳產"


def score_revenue_traditional(cum_yoy_pct):
    """
    傳產的營收成長分數（0-20）。門檻比電子低：
    電子 +15% 只算普通，傳產 +15% 已經相當好。
    """
    if cum_yoy_pct is None:
        return 6
    if cum_yoy_pct >= 25:
        return 20
    if cum_yoy_pct >= 15:
        return 17
    if cum_yoy_pct >= 10:
        return 14
    if cum_yoy_pct >= 5:
        return 10
    if cum_yoy_pct > 0:
        return 6
    if cum_yoy_pct > -10:
        return 3
    return 0


def score_value_traditional(pb, dividend_yield, pe):
    """
    傳產的估值分數（0-25）。以股價淨值比與殖利率為主，本益比只作輔助。
    循環股的本益比在獲利高點時最低，單看 PE 會在最危險的時候給最高分。
    回傳 (分數, 說明)
    """
    score, parts = 0, []

    if pb is None:
        score += 8
        parts.append("無淨值比資料")
    elif pb <= 0.8:
        score += 14
        parts.append(f"PB {pb:.2f}，低於淨值")
    elif pb <= 1.2:
        score += 12
        parts.append(f"PB {pb:.2f}，接近淨值")
    elif pb <= 2.0:
        score += 8
        parts.append(f"PB {pb:.2f}")
    elif pb <= 3.5:
        score += 4
        parts.append(f"PB {pb:.2f} 偏高")
    else:
        score += 1
        parts.append(f"PB {pb:.2f} 明顯偏高")

    if dividend_yield is None:
        score += 3
        parts.append("無殖利率資料")
    elif dividend_yield >= 6:
        score += 11
        parts.append(f"殖利率 {dividend_yield:.1f}%")
    elif dividend_yield >= 4:
        score += 9
        parts.append(f"殖利率 {dividend_yield:.1f}%")
    elif dividend_yield >= 2:
        score += 6
        parts.append(f"殖利率 {dividend_yield:.1f}%")
    elif dividend_yield > 0:
        score += 3
        parts.append(f"殖利率 {dividend_yield:.1f}% 偏低")
    else:
        score += 1
        parts.append("未配息")

    if pe:
        parts.append(f"PE {pe:.1f}")
    return min(25, score), "，".join(parts)


def score_from_cum_revenue_growth(cum_yoy_pct):
    """
    累計營收年增率轉分數（0-40）。用「今年至今 vs 去年同期」而非單月，
    比較不會被單月出貨遞延或去年基期異常扭曲，適合長線判斷。
    """
    if cum_yoy_pct is None:
        return 8  # 無資料給基本分，不因缺資料被過度懲罰
    if cum_yoy_pct >= 50:
        return 40
    if cum_yoy_pct >= 30:
        return 34
    if cum_yoy_pct >= 20:
        return 28
    if cum_yoy_pct >= 10:
        return 22
    if cum_yoy_pct >= 5:
        return 16
    if cum_yoy_pct > 0:
        return 10
    if cum_yoy_pct > -10:
        return 4
    return 0


def score_from_streak(streak):
    """連續買超天數轉分數（0-30）。連續性比單日大買更能代表法人真的在佈局。"""
    if streak >= 8:
        return 30
    if streak >= 5:
        return 25
    if streak >= 3:
        return 18
    if streak >= 2:
        return 10
    if streak >= 1:
        return 5
    return 0


def get_top_by_investor(investor="trust", direction="buy", days=10, top_n=10,
                        min_days=None):
    """
    依「單一法人」的近 N 日累計買賣超排名，而不是三大法人合計。

    合計會把三種完全不同的人加在一起：外資常是指數被動調整、
    自營多為權證避險、投信才是做過研究的主動買盤。
    要看「誰在認養」就必須分開排，合計排行看不出來。

    「認養」的定義不只是量大，還要有持續性——連續幾天小買，
    比單日大買更像在建倉。所以同時要求累計量與買超天數。

    investor: foreign / trust / dealer
    direction: buy（買超）/ sell（賣超）
    min_days: 至少要有幾天站在該方向；None 表示不限
    回傳 [(code, name, 累計張數, 該方向天數, 總天數), ...]
    """
    col = {"foreign": "foreign_net_lots",
           "trust": "trust_net_lots",
           "dealer": "dealer_net_lots"}.get(investor, "trust_net_lots")
    sign = ">" if direction == "buy" else "<"
    order = "DESC" if direction == "buy" else "ASC"
    having = f"SUM(h.{col}) {sign} 0"
    if min_days:
        having += f" AND COUNT(*) FILTER (WHERE h.{col} {sign} 0) >= {int(min_days)}"

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            f"""
            WITH recent AS (
                SELECT DISTINCT trade_date FROM inst_history
                ORDER BY trade_date DESC LIMIT %s
            )
            SELECT h.code,
                   MAX(h.name) AS name,
                   SUM(h.{col}) AS cum,
                   COUNT(*) FILTER (WHERE h.{col} {sign} 0) AS hit_days,
                   COUNT(*) AS total_days
            FROM inst_history h
            JOIN recent r ON h.trade_date = r.trade_date
            WHERE length(h.code) = 4 AND h.code ~ '^[0-9]+$'
              AND h.code NOT LIKE '00%%'
            GROUP BY h.code
            HAVING {having}
            ORDER BY SUM(h.{col}) {order}
            LIMIT %s
            """,
            (days, top_n),
        )
        rows = cursor.fetchall()
        cursor.close()
        return [(r[0], r[1], r[2] or 0, r[3] or 0, r[4] or 0) for r in rows]
    except Exception as e:
        print(f"❌ 查詢 {investor} 排行失敗: {e}")
        return []
    finally:
        release_db_connection(conn)


def get_both_side_codes(direction="buy", days=10, top_n=10, min_days=6):
    """
    外資與投信「同方向」的標的。

    兩者立場不同卻同時站在同一邊，比單一法人的動作更值得注意——
    外資的被動調整與投信的主動研究同時指向同一檔，
    巧合的機率比較低。
    回傳 [(code, name, 外資張數, 投信張數, 合計), ...]
    """
    sign = ">" if direction == "buy" else "<"
    order = "DESC" if direction == "buy" else "ASC"
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            f"""
            WITH recent AS (
                SELECT DISTINCT trade_date FROM inst_history
                ORDER BY trade_date DESC LIMIT %s
            )
            SELECT h.code, MAX(h.name),
                   SUM(h.foreign_net_lots) AS f,
                   SUM(h.trust_net_lots) AS t,
                   COUNT(*) FILTER (
                       WHERE h.foreign_net_lots {sign} 0
                         AND h.trust_net_lots {sign} 0) AS both_days
            FROM inst_history h
            JOIN recent r ON h.trade_date = r.trade_date
            WHERE length(h.code) = 4 AND h.code ~ '^[0-9]+$'
              AND h.code NOT LIKE '00%%'
            GROUP BY h.code
            HAVING SUM(h.foreign_net_lots) {sign} 0
               AND SUM(h.trust_net_lots) {sign} 0
               AND COUNT(*) FILTER (
                       WHERE h.foreign_net_lots {sign} 0
                         AND h.trust_net_lots {sign} 0) >= %s
            ORDER BY (SUM(h.foreign_net_lots) + SUM(h.trust_net_lots)) {order}
            LIMIT %s
            """,
            (days, min_days, top_n),
        )
        rows = cursor.fetchall()
        cursor.close()
        return [(r[0], r[1], r[2] or 0, r[3] or 0, (r[2] or 0) + (r[3] or 0))
                for r in rows]
    except Exception as e:
        print(f"❌ 查詢雙方同向失敗: {e}")
        return []
    finally:
        release_db_connection(conn)


def get_institutional_shift_candidates(prior_days=5, top_n=12):
    """找出近幾日法人方向反轉或異常放大的標的；只使用已保存的 T86 歷史。"""
    try:
        prior_days = max(3, int(prior_days))
        top_n = max(1, int(top_n))
    except (TypeError, ValueError):
        prior_days, top_n = 5, 12
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT DISTINCT trade_date
            FROM inst_history
            ORDER BY trade_date DESC
            LIMIT %s
            """,
            (prior_days + 1,),
        )
        dates = [row[0] for row in cursor.fetchall()]
        if len(dates) < prior_days + 1:
            cursor.close()
            return []
        latest_date = dates[0]
        cursor.execute(
            """
            SELECT code, MAX(name) AS name, trade_date,
                   COALESCE(foreign_net_lots, 0),
                   COALESCE(trust_net_lots, 0),
                   COALESCE(dealer_net_lots, 0),
                   COALESCE(total_net_lots, 0)
            FROM inst_history
            WHERE trade_date = ANY(%s)
              AND length(code) = 4 AND code ~ '^[0-9]+$'
              AND code NOT LIKE '00%%'
            GROUP BY code, trade_date,
                     foreign_net_lots, trust_net_lots,
                     dealer_net_lots, total_net_lots
            ORDER BY code, trade_date DESC
            """,
            (dates,),
        )
        rows = cursor.fetchall()
        cursor.close()
    except Exception as exc:
        print(f"❌ 查詢法人方向突變失敗: {exc}")
        return []
    finally:
        release_db_connection(conn)

    by_code = {}
    for code, name, trade_date, foreign, trust, dealer, total in rows:
        item = by_code.setdefault(str(code), {"name": name or code, "rows": {}})
        item["rows"][trade_date] = {
            "foreign": int(foreign or 0),
            "trust": int(trust or 0),
            "dealer": int(dealer or 0),
            "total": int(total or 0),
        }

    investor_names = {"foreign": "外資", "trust": "投信", "dealer": "自營商"}
    candidates = []
    for code, item in by_code.items():
        latest = item["rows"].get(latest_date)
        prior = [item["rows"][d] for d in dates[1:] if d in item["rows"]]
        if not latest or len(prior) < prior_days:
            continue

        prior_avg = {
            key: sum(row[key] for row in prior) / len(prior)
            for key in ("foreign", "trust", "dealer", "total")
        }
        current_total = latest["total"]
        prior_total = prior_avg["total"]
        changed = []
        for key in ("foreign", "trust", "dealer"):
            current = latest[key]
            before = prior_avg[key]
            if current > 0 and before < 0:
                changed.append(f"{investor_names[key]}轉買")
            elif current < 0 and before > 0:
                changed.append(f"{investor_names[key]}轉賣")

        total_reversal = ((current_total > 0 and prior_total < 0) or
                          (current_total < 0 and prior_total > 0))
        avg_abs_total = sum(abs(row["total"]) for row in prior) / len(prior)
        magnitude_ratio = (abs(current_total) / avg_abs_total
                           if avg_abs_total > 0 else 0.0)
        magnitude_spike = (current_total != 0 and avg_abs_total > 0 and
                           magnitude_ratio >= 2.5)
        if not total_reversal and not changed and not magnitude_spike:
            continue

        current_signs = [latest[key] > 0 for key in ("foreign", "trust", "dealer")]
        current_neg_signs = [latest[key] < 0 for key in ("foreign", "trust", "dealer")]
        if all(current_signs):
            consensus = "三方同步買超"
        elif all(current_neg_signs):
            consensus = "三方同步賣超"
        elif ((latest["foreign"] > 0 and latest["trust"] > 0) or
              (latest["foreign"] < 0 and latest["trust"] < 0)):
            consensus = "外資、投信同向"
        else:
            consensus = "法人分歧"

        if total_reversal:
            event_type = "賣轉買" if current_total > 0 else "買轉賣"
            priority = 3
        elif changed:
            event_type = "單一法人轉向"
            priority = 2
        else:
            event_type = "買超放大" if current_total > 0 else "賣超放大"
            priority = 1
        priority += min(len(changed), 2)
        if magnitude_spike:
            priority += 1

        candidates.append({
            "code": code,
            "name": str(item["name"] or code),
            "event_type": event_type,
            "current_total_lots": current_total,
            "prior_avg_total_lots": round(prior_total, 1),
            "magnitude_ratio": round(magnitude_ratio, 2),
            "investor_changes": changed[:3],
            "consensus": consensus,
            "current": {key: latest[key] for key in ("foreign", "trust", "dealer", "total")},
            "prior_avg": {key: round(prior_avg[key], 1) for key in ("foreign", "trust", "dealer", "total")},
            "prior_days": len(prior),
            "data_date": str(latest_date),
            "priority": priority,
        })

    candidates.sort(key=lambda x: (x["priority"], abs(x["current_total_lots"]), x["code"]),
                    reverse=True)
    for item in candidates:
        item.pop("priority", None)
    return candidates[:top_n]


_TURNING_OBSERVATION_CACHE = {"at": 0, "data": None}
# 轉折頁需要比一般即時報價更穩定的批次快取；T86 與收盤資料更新後由 warmup 重建。
TURNING_OBSERVATION_CACHE_SECONDS = 900
TURNING_OBSERVATION_SHARED_MAX_AGE = 900
TURNING_OBSERVATION_SNAPSHOT_KEY = "turning_observation"
# 3：轉折項目新增 breakout（價格突破狀態）欄位。
# 版本要往上加，否則舊快照（沒有該欄位）會通過驗證被直接沿用，
# 畫面就永遠看不到新標示，而且不會有任何錯誤訊息。
TURNING_OBSERVATION_SCHEMA_VERSION = 3


def _turning_reason_details(inst_item, stock, direction, cross_up, cross_down,
                            up_streak, down_streak, vol_ratio, broke_support,
                            prior_days=5):
    """把轉折判斷用到的原始數值轉成逐項事實；不使用泛化的方向變化文案。"""
    current = inst_item.get("current") or {}
    prior_avg = inst_item.get("prior_avg") or {}
    investor_names = {"foreign": "外資", "trust": "投信", "dealer": "自營商"}

    def fmt_lots(value):
        try:
            return f"{float(value):+,.0f} 張"
        except (TypeError, ValueError):
            return "資料不足"

    def fmt_abs_lots(value):
        try:
            return f"{abs(float(value)):,.0f} 張"
        except (TypeError, ValueError):
            return "資料不足"

    def side_text(value):
        try:
            value = float(value)
        except (TypeError, ValueError):
            return "方向不明"
        if value > 0:
            return "買超"
        if value < 0:
            return "賣超"
        return "接近中性"

    def fmt_price(value):
        try:
            return f"{float(value):,.2f}"
        except (TypeError, ValueError):
            return "資料不足"

    details = []
    for key in ("foreign", "trust", "dealer"):
        current_value = current.get(key)
        prior_value = prior_avg.get(key)
        if current_value is None or prior_value is None:
            continue
        name = investor_names[key]
        try:
            current_number = float(current_value)
            prior_number = float(prior_value)
        except (TypeError, ValueError):
            continue
        if current_number > 0 and prior_number < 0:
            details.append(
                f"{name}由前{prior_days}日平均賣超 {abs(prior_number):,.0f} 張，"
                f"轉為今日買超 {current_number:,.0f} 張")
        elif current_number < 0 and prior_number > 0:
            details.append(
                f"{name}由前{prior_days}日平均買超 {prior_number:,.0f} 張，"
                f"轉為今日賣超 {abs(current_number):,.0f} 張")

    total = current.get("total", inst_item.get("current_total_lots"))
    prior_total = prior_avg.get("total", inst_item.get("prior_avg_total_lots"))
    if total is not None:
        total_text = (f"三大法人今日{side_text(total)} {fmt_abs_lots(total)}")
        if prior_total is not None:
            total_text += f"；前{prior_days}日平均{side_text(prior_total)} {fmt_abs_lots(prior_total)}"
        details.append(total_text)

    ratio = inst_item.get("magnitude_ratio")
    try:
        if ratio is not None and float(ratio) >= 2.5:
            details.append(f"今日合計絕對值約為前{prior_days}日平均的 {float(ratio):.1f} 倍")
    except (TypeError, ValueError):
        pass

    close = stock.get("close")
    ma20 = stock.get("ma20")
    if cross_up and close is not None and ma20 is not None:
        details.append(f"收盤 {fmt_price(close)} 站回20日均線 {fmt_price(ma20)}")
    elif cross_down and close is not None and ma20 is not None:
        details.append(f"收盤 {fmt_price(close)} 跌破20日均線 {fmt_price(ma20)}")
    elif close is not None and ma20 is not None:
        relation = "高於" if float(close) >= float(ma20) else "低於"
        details.append(f"收盤 {fmt_price(close)}，目前{relation}20日均線 {fmt_price(ma20)}，本日未形成均線穿越")
    else:
        details.append("20日均線資料不足，無法判定站回或跌破")

    if direction == "up":
        details.append(f"連續上漲 {up_streak} 天" if up_streak else "今日未形成連續上漲")
    elif direction == "down":
        details.append(f"連續下跌 {down_streak} 天" if down_streak else "今日未形成連續下跌")

    if vol_ratio > 0:
        details.append(f"成交量約為20日均量 {vol_ratio:.1f} 倍")
    else:
        details.append("20日均量資料不足")

    support = stock.get("support")
    resistance = stock.get("resistance")
    if support is not None:
        if broke_support:
            details.append(f"現價 {fmt_price(close)} 已跌破近期支撐參考 {fmt_price(support)}")
        else:
            details.append(f"現價 {fmt_price(close)} 尚在近期支撐 {fmt_price(support)} 上方")
    else:
        details.append("近期支撐資料不足")
    if resistance is not None:
        details.append(f"近期壓力參考 {fmt_price(resistance)}")
    return details[:10]


# 籌碼分布的下方價格底線：低於現價這個倍數的交易日不列入統計。
# 飆股早期的低價天量會稀釋上方套牢比例，而那些人早已獲利，
# 不會因為「解套」而賣，計入只會讓數字失真。
CHIP_PRICE_FLOOR_RATIO = 0.5


def chip_above_ratio(stock):
    """
    現價上方估算歷史成交量的比例（0~1）。給清單列顯示用。

    直接呼叫 compute_chip_bins 取結果，不另外寫一套。
    先前這裡是獨立實作（用收盤價、不做區間分攤），
    跟展開後的圖是兩種算法，同一檔會出現兩個不同的百分比。
    """
    data = compute_chip_bins(stock)
    if not data:
        return None
    return data.get("above_ratio")

def compute_chip_bins(stock, bins=14):
    """
    以每日成交量攤到當日高低價區間，估算歷史成交量的價格分布。

    這不是券商的分價量表。Yahoo 只給日 OHLCV，沒有盤中逐筆成交，
    所以無法知道每一筆成交發生在哪個價位。這裡的做法是：
    把當天的成交量，依「價格區間與當日 low~high 的重疊長度」按比例分攤。

    舉例：某天 low=100、high=140、volume=1000
      區間 100~110 佔 low~high 的 10/40 → 分到 250
      區間 110~140 佔 30/40             → 分到 750
      合計仍是 1000，成交量守恆。

    先前的做法是把整天的量全歸到收盤價那一格，一天內震盪大的標的
    位置會明顯偏掉——這是改用區間分攤的原因。

    價格底線（CHIP_PRICE_FLOOR_RATIO）改成「只裁掉低於門檻的那一段」，
    不再因為收盤價低於門檻就整天丟棄：
    某天 low=590、high=630、現價一半=612.5 時，
    612.5 以上那段的成交量仍然是有效的成本區。

    回傳 {"bins": [...], "days", "max_ratio", "price", "low", "high",
          "floor", "valid_volume", "above_volume", "above_ratio"}
    資料不足回 None。
    """
    closes = (stock or {}).get("closes") or []
    volumes = (stock or {}).get("volumes") or []
    highs = (stock or {}).get("highs") or []
    lows = (stock or {}).get("lows") or []
    n = len(closes)
    if n < 20 or len(volumes) != n:
        return None
    # 沒有高低價時退回用收盤價（等於舊行為），至少還算得出東西
    if len(highs) != n or len(lows) != n:
        highs, lows = list(closes), list(closes)

    price_now = closes[-1]
    if not price_now:
        return None
    floor_price = price_now * CHIP_PRICE_FLOOR_RATIO

    # 有效的日資料：把每天的價格區間裁到門檻之上
    days = []
    for c, h, l, v in zip(closes, highs, lows, volumes):
        try:
            v = float(v or 0)
        except (TypeError, ValueError):
            continue
        if v <= 0 or c is None:
            continue
        hi_d = float(h if h is not None else c)
        lo_d = float(l if l is not None else c)
        if hi_d < lo_d:
            hi_d, lo_d = lo_d, hi_d
        if hi_d <= floor_price:
            continue                      # 整天都在門檻之下，全數排除
        kept_lo = max(lo_d, floor_price)  # 只裁掉低於門檻的那一段
        span = hi_d - lo_d
        if span > 0:
            v = v * (hi_d - kept_lo) / span   # 成交量按保留比例縮減
        days.append((kept_lo, hi_d, v))
    if len(days) < 20:
        # 濾完剩太少就不設門檻，寧可看到含雜訊的分布，也不要整個消失
        days = []
        for c, h, l, v in zip(closes, highs, lows, volumes):
            try:
                v = float(v or 0)
            except (TypeError, ValueError):
                continue
            if v <= 0 or c is None:
                continue
            hi_d = float(h if h is not None else c)
            lo_d = float(l if l is not None else c)
            if hi_d < lo_d:
                hi_d, lo_d = lo_d, hi_d
            days.append((lo_d, hi_d, v))
        floor_price = None
    if len(days) < 20:
        return None

    lo = min(d[0] for d in days)
    hi = max(d[1] for d in days)
    if hi <= lo:
        return None
    step = (hi - lo) / bins

    buckets = [0.0] * bins
    total = 0.0
    for d_lo, d_hi, vol in days:
        total += vol
        d_span = d_hi - d_lo
        if d_span <= 0:
            # 一字板：整天只有一個價位，全部歸到那一格
            k = min(max(int((d_lo - lo) / step), 0), bins - 1)
            buckets[k] += vol
            continue
        # 只走與當日區間重疊的那幾格，不必掃全部
        k0 = min(max(int((d_lo - lo) / step), 0), bins - 1)
        k1 = min(max(int((d_hi - lo) / step), 0), bins - 1)
        for k in range(k0, k1 + 1):
            b_lo = lo + step * k
            b_hi = b_lo + step
            overlap = min(d_hi, b_hi) - max(d_lo, b_lo)
            if overlap > 0:
                buckets[k] += vol * overlap / d_span
    if total <= 0:
        return None

    out, above_volume = [], 0.0
    for k, v in enumerate(buckets):
        b_lo = lo + step * k
        b_hi = b_lo + step
        # 「上方」要整段都在現價之上：包含現價的那一格裡有一半的人是賺的，
        # 算成套牢並不正確。
        is_above = b_lo >= price_now
        if is_above:
            above_volume += v
        out.append({
            "low": round(b_lo, 2), "high": round(b_hi, 2),
            "mid": round((b_lo + b_hi) / 2, 2),
            "volume": v,
            "ratio": v / total,
            "above": is_above,
            "current": b_lo <= price_now <= b_hi,
        })

    return {"bins": out, "days": len(days),
            "max_ratio": max(b["ratio"] for b in out),
            "price": round(price_now, 2),
            "low": round(lo, 2), "high": round(hi, 2),
            "floor": round(floor_price, 2) if floor_price else None,
            "dropped": n - len(days),
            "valid_volume": total,
            "above_volume": above_volume,
            "above_ratio": above_volume / total}

def macd_cross_state(stock, fast=12, slow=26, signal=9, recent_days=5):
    """
    MACD 交叉判斷（DIF 穿越 MACD 訊號線）。

    DIF   = EMA(12) − EMA(26)
    MACD  = DIF 的 EMA(9)
    柱狀體 = DIF − MACD

    只描述事實，不加分、不改變雷達的篩選與排序。

    回傳 "MACD 金叉" / "MACD 死叉" / None。
    需要至少 slow + signal + recent_days 根日K；不足回 None，
    不用較短區間硬算——樣本不夠時 EMA 還沒收斂，算出來的交叉不可信。
    """
    closes = (stock or {}).get("closes") or []
    need = slow + signal + recent_days
    if len(closes) < need:
        return None

    def ema_series(values, period):
        """回傳與輸入等長的 EMA 序列；前 period 筆用簡單平均起步。"""
        if len(values) < period:
            return []
        k = 2.0 / (period + 1)
        seed = sum(values[:period]) / period
        out = [None] * (period - 1) + [seed]
        prev = seed
        for v in values[period:]:
            prev = v * k + prev * (1 - k)
            out.append(prev)
        return out

    fast_ema = ema_series(closes, fast)
    slow_ema = ema_series(closes, slow)
    if not fast_ema or not slow_ema:
        return None

    dif = [(f - s_) if (f is not None and s_ is not None) else None
           for f, s_ in zip(fast_ema, slow_ema)]
    dif_valid = [x for x in dif if x is not None]
    if len(dif_valid) < signal + recent_days:
        return None

    sig = ema_series(dif_valid, signal)
    if not sig:
        return None
    # 對齊：sig 對應 dif_valid 的尾段
    pairs = [(d, m) for d, m in zip(dif_valid, sig) if m is not None]
    if len(pairs) < recent_days + 1:
        return None

    today_dif, today_sig = pairs[-1]
    for back in range(1, recent_days + 1):
        if len(pairs) <= back:
            break
        prev_dif, prev_sig = pairs[-1 - back]
        if prev_dif <= prev_sig and today_dif > today_sig:
            return "MACD 金叉"
        if prev_dif >= prev_sig and today_dif < today_sig:
            return "MACD 死叉"
    return None


def golden_cross_state(stock, short_n=20, long_n=60, recent_days=5):
    """
    判斷 20 日均線與 60 日均線（季線）的黃金／死亡交叉。

    只描述事實，不加分、不改變雷達的篩選與排序——
    交接文件明訂不可因畫面需求自行改分數或排序，
    所以這裡只回傳一個標籤，讓使用者自己判斷。

    回傳：
      "黃金交叉" —— 近 N 日內 20MA 由下向上穿過 60MA
      "死亡交叉" —— 近 N 日內 20MA 由上向下穿過 60MA
      "站上季線" —— 沒有剛交叉，但 20MA 已在 60MA 上方
      None      —— 資料不足或不符合上述任一種

    需要至少 long_n + recent_days 根日K；不足就回 None，
    不用較短的區間硬算——那算出來的「季線」不是季線。
    """
    closes = (stock or {}).get("closes") or []
    need = long_n + recent_days
    if len(closes) < need:
        return None

    def ma(values, n, offset):
        """offset=0 是最新一日，往前推 offset 日的 n 日均線。"""
        end = len(values) - offset
        if end - n < 0:
            return None
        window = values[end - n:end]
        return sum(window) / n if window else None

    today_short, today_long = ma(closes, short_n, 0), ma(closes, long_n, 0)
    if today_short is None or today_long is None:
        return None

    # 往前找 recent_days 天內有沒有發生穿越
    for back in range(1, recent_days + 1):
        prev_short, prev_long = ma(closes, short_n, back), ma(closes, long_n, back)
        if prev_short is None or prev_long is None:
            break
        if prev_short <= prev_long and today_short > today_long:
            return "黃金交叉"
        if prev_short >= prev_long and today_short < today_long:
            return "死亡交叉"

    return "站上季線" if today_short > today_long else None


def _breakout_label(stock):
    """
    以既有的位階欄位判斷價格突破狀態，不做新的計算。

    resistance 為 None 代表已突破近 60 日高點（既有 fmt_resistance 的口徑）；
    pos_vs_60d_high 貼近 0 表示就在高點附近；跌破近期低點則反向標示。
    判斷不到就回 None，畫面不顯示，不硬給一個模稜兩可的字。
    """
    if not stock:
        return None
    if stock.get("resistance") is None and stock.get("close"):
        return "突破60日高"
    pos = stock.get("pos_vs_60d_high")
    if pos is not None:
        if pos >= -1:
            return "逼近60日高"
        if pos <= -30:
            return "距高點逾三成"
    if stock.get("broke_support"):
        return "跌破近期支撐"
    return None


def build_turning_observation(limit=60, prior_days=5, force_refresh=False):
    """以真實法人轉向搭配價格、均線與量能，建立轉折觀察三狀態。"""
    try:
        limit = max(10, min(int(limit), 120))
        prior_days = max(3, min(int(prior_days), 10))
    except (TypeError, ValueError):
        limit, prior_days = 60, 5
    now = time.time()
    with _realtime_cache_lock:
        cached = _TURNING_OBSERVATION_CACHE.get("data")
        if (not force_refresh and cached is not None and
                now - _TURNING_OBSERVATION_CACHE.get("at", 0) < TURNING_OBSERVATION_CACHE_SECONDS):
            return cached

    # 多 worker／重啟後先讀共享快照；這一步避免每個使用者重新並行抓數十檔 3mo 行情。
    try:
        shared = (None if force_refresh else _load_shared_data_snapshot(
            TURNING_OBSERVATION_SNAPSHOT_KEY,
            max_age_seconds=TURNING_OBSERVATION_SHARED_MAX_AGE))
        shared_payload = (shared.get("payload") if shared else None) or {}
        if (isinstance(shared_payload, dict) and isinstance(shared_payload.get("items"), list)
                and int(shared_payload.get("schema_version") or 0) >= TURNING_OBSERVATION_SCHEMA_VERSION
                and all(isinstance(item, dict) and item.get("reason_details")
                        for item in shared_payload.get("items") or [])):
            with _realtime_cache_lock:
                _TURNING_OBSERVATION_CACHE.update({"at": now, "data": shared_payload})
            return shared_payload
    except Exception as exc:
        print(f"⚠️ 讀取轉折觀察共享快照失敗: {exc}")

    institutional = get_institutional_shift_candidates(prior_days=prior_days, top_n=limit)
    if not institutional:
        result = {"data_date": None, "prior_days": prior_days, "items": []}
        with _realtime_cache_lock:
            _TURNING_OBSERVATION_CACHE["at"] = time.time()
            _TURNING_OBSERVATION_CACHE["data"] = result
        try:
            _save_shared_data_snapshot(
                TURNING_OBSERVATION_SNAPSHOT_KEY, result,
                data_date=taiwan_today(),
                source_meta={"source": "turning_observation", "item_count": 0})
        except Exception as exc:
            print(f"⚠️ 保存轉折觀察空快照失敗: {exc}")
        return result

    codes = [item.get("code") for item in institutional if item.get("code")]
    # 1mo 已涵蓋 20 日均線與近期位階；只有少數新上市／資料缺口標的才回補 3mo。
    # 抓 3mo 而不是 1mo：壓力位要用近 60 日高點判斷，
    # 只抓 20 根日K 時 high_60d 永遠是 None，程式就會走到
    # 「無壓力位」那條分支——但那不是真的沒有壓力，是根本沒看到。
    #
    # 實際發生過：良維 6290 收 270、頭上 6 月有 375、7 月有 320 的套牢區，
    # 畫面卻寫「無壓力位」。20 日的視野看不到三個月前的高點。
    #
    # 同時也讓 20/60 均線交叉與 MACD 算得出來（都需要 60 根以上）。
    prices = get_realtime_stocks_bulk(codes, workers=16, rng="3mo")
    fallback_codes = [code for code in codes
                      if len((prices.get(code) or {}).get("closes") or []) < 20]
    if fallback_codes:
        prices.update(get_realtime_stocks_bulk(fallback_codes, workers=12, rng="3mo"))
    items = []
    state_order = {"confirmed": 3, "observing": 2, "invalid": 1}
    for inst_item in institutional:
        code = str(inst_item.get("code") or "")
        stock = prices.get(code) or {}
        close = stock.get("close")
        if close is None:
            continue
        series = [float(x) for x in (stock.get("closes") or []) if x not in (None, 0)]
        if len(series) < 3:
            continue
        prev_close = series[-2]
        ma20 = stock.get("ma20")
        prev_window = series[:-1][-20:]
        prev_ma20 = sum(prev_window) / len(prev_window) if prev_window else None
        cross_up = bool(prev_ma20 and ma20 and prev_close < prev_ma20 <= close)
        cross_down = bool(prev_ma20 and ma20 and prev_close > prev_ma20 >= close)
        up_streak = int(stock.get("up_streak") or 0)
        down_streak = int(stock.get("down_streak") or 0)
        vol_ratio = float(stock.get("vol_ratio") or 0)
        broke_support = bool(stock.get("broke_support"))
        current_total = int(inst_item.get("current_total_lots") or 0)
        changes = inst_item.get("investor_changes") or []
        inst_up = current_total > 0 and (
            inst_item.get("event_type") == "賣轉買" or any("轉買" in str(x) for x in changes))
        inst_down = current_total < 0 and (
            inst_item.get("event_type") == "買轉賣" or any("轉賣" in str(x) for x in changes))
        direction = "up" if current_total > 0 else "down" if current_total < 0 else "neutral"
        if direction == "neutral":
            continue

        reasons = []
        score = 0
        if inst_up or inst_down:
            reasons.append("法人方向反轉")
            score += 1
        if cross_up or cross_down:
            reasons.append("站回20日均線" if cross_up else "跌破20日均線")
            score += 1
        if (direction == "up" and up_streak >= 2) or (direction == "down" and down_streak >= 2):
            reasons.append(f"連續{'上漲' if direction == 'up' else '下跌'} {up_streak if direction == 'up' else down_streak} 天")
            score += 1
        if vol_ratio >= 1.3:
            reasons.append(f"量能約20日均量 {vol_ratio:.1f} 倍")
            score += 1
        if (direction == "up" and not broke_support and close > (stock.get("low_20d") or close)):
            reasons.append("價格未跌破近期支撐")
            score += 1
        if direction == "down" and broke_support:
            reasons.append("近期支撐已跌破")
            score += 1

        invalid_reasons = []
        if direction == "up" and broke_support:
            support_reference = (stock.get("low_20d") or stock.get("low_60d")
                                 or stock.get("support"))
            try:
                if support_reference is not None and float(support_reference) >= float(close):
                    invalid_reasons.append(
                        f"現價 {float(close):,.2f} 已跌破近期支撐參考 {float(support_reference):,.2f}")
                else:
                    invalid_reasons.append(
                        f"現價 {float(close):,.2f} 下方未找到有效的近期支撐，支撐條件已失效")
            except (TypeError, ValueError):
                invalid_reasons.append(
                    f"現價 {float(close):,.2f} 已跌破近期支撐，支撐數值資料不足")
        if direction == "up" and down_streak >= 3:
            invalid_reasons.append(f"法人仍偏買方，但價格已連續下跌 {down_streak} 天")
        if direction == "down" and cross_up and up_streak >= 3:
            invalid_reasons.append(
                f"原本偏空，但收盤 {float(close):,.2f} 已站回20日均線 {float(ma20):,.2f}，且連續上漲 {up_streak} 天")
        if direction == "down" and cross_up and up_streak < 3:
            invalid_reasons.append(
                f"原本偏空，但收盤 {float(close):,.2f} 站回20日均線 {float(ma20):,.2f}")
        invalid = bool(invalid_reasons)
        reason_details = _turning_reason_details(
            inst_item, stock, direction, cross_up, cross_down,
            up_streak, down_streak, vol_ratio, broke_support, prior_days)
        if invalid:
            state = "invalid"
            state_label = "已失效"
            direction_label = "狀態已失效"
            state_reason = "；".join(invalid_reasons)
        elif score >= 3:
            state = "confirmed"
            state_label = "已確認"
            direction_label = "轉強" if direction == "up" else "轉弱"
            state_reason = "；".join(reason_details[:3]) or "已符合轉折確認條件"
        else:
            state = "observing"
            state_label = "觀察中"
            direction_label = "轉強" if direction == "up" else "轉弱"
            state_reason = "；".join(reason_details[:3]) or "目前資料不足以形成完整判讀"
        if invalid_reasons:
            reason_details = invalid_reasons + reason_details

        # 把「法人方向反轉」轉成使用者一眼可辨識的買賣流程；
        # event_type 與各法人 investor_changes 都來自已保存的 T86，不自行推測。
        event_type = str(inst_item.get("event_type") or "")
        if event_type == "賣轉買" or any("轉買" in str(x) for x in changes):
            direction_flow, direction_flow_label = "sell_to_buy", "賣轉買"
        elif event_type == "買轉賣" or any("轉賣" in str(x) for x in changes):
            direction_flow, direction_flow_label = "buy_to_sell", "買轉賣"
        elif current_total > 0:
            direction_flow, direction_flow_label = "buying_strength", "買方增強"
        elif current_total < 0:
            direction_flow, direction_flow_label = "selling_strength", "賣方增強"
        else:
            direction_flow, direction_flow_label = "unknown", "方向不明"

        items.append({
            "code": code,
            "name": inst_item.get("name") or stock_display_name(code, fallback=code),
            "direction": direction,
            "direction_label": direction_label,
            "direction_flow": direction_flow,
            "direction_flow_label": direction_flow_label,
            "state": state,
            "state_label": state_label,
            "state_reason": state_reason,
            "invalid_reasons": invalid_reasons,
            "event_type": inst_item.get("event_type") or "法人方向變化",
            "consensus": inst_item.get("consensus") or "法人分歧",
            "current_total_lots": current_total,
            "magnitude_ratio": inst_item.get("magnitude_ratio"),
            "reasons": reason_details[:4] or ["轉折細節資料不足，請以原始行情與法人明細核對"],
            "reason_details": reason_details[:10],
            "close": close,
            "pct": stock.get("pct"),
            "support": stock.get("support"),
            "resistance": stock.get("resistance"),
            "vol_ratio": vol_ratio,
            "data_date": inst_item.get("data_date"),
            "score": score,
            # 價格突破狀態。轉折本身只看法人方向，價格是否同步突破是另一回事——
            # 標出來讓人看得到「法人轉買而且價格也站上新高」跟
            # 「法人轉買但價格還在原地」的差別。
            # 只描述既有的位階事實，不新增篩選條件、不影響排序。
            "breakout": _breakout_label(stock),
            # 現價上方尚未解套的籌碼比例，清單列直接顯示。
            "chip_above": chip_above_ratio(stock),
        })
    items.sort(key=lambda x: (state_order.get(x["state"], 0), x["score"], abs(x["current_total_lots"])), reverse=True)
    result = {"schema_version": TURNING_OBSERVATION_SCHEMA_VERSION,
              "data_date": next((x.get("data_date") for x in items if x.get("data_date")), None),
              "prior_days": prior_days, "items": items[:limit]}
    with _realtime_cache_lock:
        _TURNING_OBSERVATION_CACHE["at"] = time.time()
        _TURNING_OBSERVATION_CACHE["data"] = result
    try:
        _save_shared_data_snapshot(
            TURNING_OBSERVATION_SNAPSHOT_KEY, result,
            data_date=result.get("data_date") or taiwan_today(),
            source_meta={"source": "turning_observation", "schema_version": TURNING_OBSERVATION_SCHEMA_VERSION,
                         "item_count": len(items),
                         "limit": limit, "prior_days": prior_days})
    except Exception as exc:
        print(f"⚠️ 保存轉折觀察共享快照失敗: {exc}")
    return result


_TURNING_REFRESH_LOCK = threading.Lock()
_TURNING_REFRESH_RUNNING = False
TURNING_STALE_SNAPSHOT_MAX_AGE_SECONDS = 7 * 86400


def _turning_snapshot_status(payload):
    """回傳轉折快照與是否為近三日資料；過舊資料只作暫存畫面並明示日期。"""
    if not isinstance(payload, dict) or not isinstance(payload.get("items"), list):
        return False
    data_date = _leaderboard_date(payload.get("data_date"))
    today = taiwan_today()
    return bool(data_date and data_date <= today and (today - data_date).days <= 3)


def _get_turning_web_snapshot():
    """網頁先取可用快照，不在 request 內執行完整轉折計算。"""
    now = time.time()
    with _realtime_cache_lock:
        cached = _TURNING_OBSERVATION_CACHE.get("data")
        cached_at = _TURNING_OBSERVATION_CACHE.get("at", 0)
        if cached is not None and now - cached_at < TURNING_OBSERVATION_CACHE_SECONDS:
            return cached, _turning_snapshot_status(cached), "記憶體快取"
    try:
        shared = _load_shared_data_snapshot(
            TURNING_OBSERVATION_SNAPSHOT_KEY,
            max_age_seconds=TURNING_STALE_SNAPSHOT_MAX_AGE_SECONDS)
        payload = (shared.get("payload") if shared else None) or {}
        if (isinstance(payload, dict) and isinstance(payload.get("items"), list)
                and int(payload.get("schema_version") or 0) >= TURNING_OBSERVATION_SCHEMA_VERSION
                and all(isinstance(item, dict) and item.get("reason_details")
                        for item in payload.get("items") or [])):
            with _realtime_cache_lock:
                _TURNING_OBSERVATION_CACHE.update({"at": now, "data": payload})
            return payload, _turning_snapshot_status(payload), "共享快照"
        if isinstance(payload, dict) and payload:
            return None, False, "舊版轉折快照"
    except Exception as exc:
        print(f"⚠️ 讀取轉折網頁快照失敗: {exc}")
    return None, False, "尚未建立快照"


def _start_turning_background_refresh():
    """每個 process 最多同時執行一個轉折刷新，避免多個使用者重複打外部行情。"""
    global _TURNING_REFRESH_RUNNING
    with _TURNING_REFRESH_LOCK:
        if _TURNING_REFRESH_RUNNING:
            return False
        _TURNING_REFRESH_RUNNING = True

    def worker():
        global _TURNING_REFRESH_RUNNING
        try:
            build_turning_observation(limit=60, prior_days=5, force_refresh=True)
        except Exception as exc:
            print(f"⚠️ 背景刷新轉折觀察失敗: {exc}")
        finally:
            with _TURNING_REFRESH_LOCK:
                _TURNING_REFRESH_RUNNING = False

    threading.Thread(target=worker, name="turning-refresh", daemon=True).start()
    return True


def build_holdings_text(uid):
    """
    把持股整理成純文字，供使用者複製後貼給其他 AI 檢視。

    為什麼是純文字而不是 Flex 卡片：卡片是圖形介面，複製不了內容。
    這個功能的用途就是「拿出去給別人／別的工具讀」，格式必須可複製。

    欄位用空白分隔而不是 CSV 的逗號——股價本來就有千分位逗號，
    兩者混在一起 AI 反而容易切錯欄。

    刻意不放黑馬／雷達分數與套牢籌碼比例：
    那是本專案自己的評分邏輯與估算值，外部 AI 無從判斷怎麼解讀，
    放進去只會被當成客觀指標，反而誤導。
    """
    positions = merge_positions(get_positions(uid))
    if not positions:
        return "目前沒有持股資料。到網頁的持股頁新增之後再試一次。"

    codes = [p["code"] for p in positions]
    prices = get_realtime_stocks_bulk(codes, workers=12, rng="3mo") or {}
    inst = fetch_institutional_data() or {}
    rev = fetch_monthly_revenue() or {}
    val = fetch_valuation() or {}
    ind_map = get_industry_map() or {}
    cum_map = {}
    try:
        cum_map = {c: (cl, bd) for c, _n, cl, bd
                   in (get_cumulative_net_buy(days=10, top_n=len(codes) * 3,
                                              codes=codes) or [])}
    except Exception as exc:
        print(f"⚠️ 持股匯出取法人資料失敗: {exc}")

    # 最近一次操作：從操作日誌取每檔最新一筆
    last_action = {}
    try:
        for log in (get_position_change_logs(uid, limit=2000) or []):
            code = str(log.get("code") or "").strip()
            d = log.get("trade_date")
            if not code or not d:
                continue
            cur = last_action.get(code)
            if cur is None or d > cur[0]:
                label, _cls = _position_change_journal_status(log)
                last_action[code] = (d, label, int(log.get("shares_delta") or 0))
    except Exception as exc:
        print(f"⚠️ 持股匯出取操作日誌失敗: {exc}")

    total_value = 0.0
    total_cost = 0.0
    enriched = []
    for p in positions:
        code = p["code"]
        q = prices.get(code) or {}
        px = q.get("close")
        sh = int(p["shares"])
        cost = float(p["cost"])
        value = (px * sh) if px else None
        if value:
            total_value += value
        total_cost += cost * sh
        enriched.append((p, q, px, sh, cost, value))

    total_pl = total_value - total_cost if total_value else None
    lines = [f"台股持股　{taiwan_today().strftime('%Y/%m/%d')}"]
    if total_value:
        pct = (total_pl / total_cost * 100) if total_cost else 0
        lines.append(f"總市值 {total_value:,.0f}　成本 {total_cost:,.0f}　"
                     f"未實現 {total_pl:+,.0f}（{pct:+.2f}%）　{len(positions)} 檔")
    lines.append("")

    enriched.sort(key=lambda x: -(x[5] or 0))
    for p, q, px, sh, cost, value in enriched:
        code = p["code"]
        name = stock_display_name(code, inst)
        # get_industry_map 回的是產業「代碼」（例如 27、28），要轉成中文。
        # 專案其他地方都是這樣做的（長度 ≤3 才轉，否則已經是名稱），
        # 這裡先前直接印代碼，輸出就變成「光聖｜27」。
        raw_ind = ind_map.get(code)
        industry = (industry_name(raw_ind) if raw_ind and len(str(raw_ind)) <= 3
                    else (str(raw_ind) if raw_ind else "產業未分類"))
        lines.append(f"{code} {name}｜{industry}")
        if px:
            pl = (px - cost) * sh
            pl_pct = (px / cost - 1) * 100 if cost else 0
            weight = (value / total_value * 100) if total_value else 0
            lines.append(f"  {sh:,}股 成本{cost:,.2f} 現價{px:,.2f}")
            lines.append(f"  損益 {pl:+,.0f}（{pl_pct:+.1f}%）"
                         f" 權重 {weight:.1f}%"
                         + (f" 持有 {(taiwan_today() - p['bought_on']).days}天"
                            if p.get("bought_on") else ""))
        else:
            lines.append(f"  {sh:,}股 成本{cost:,.2f} 現價查無資料")

        # 基本面與籌碼：缺值就整段不寫，不要填 0 或「無」造成誤讀
        facts = []
        pe = (val.get(code) or {}).get("pe")
        if pe:
            facts.append(f"PE {pe:.1f}")
        yoy = (rev.get(code) or {}).get("yoy_pct")
        if yoy is not None:
            facts.append(f"營收年增 {yoy:+.1f}%")
        cl, _bd = cum_map.get(code, (None, None))
        if cl is not None:
            facts.append(f"法人十日 {int(cl):+,}張")
        if facts:
            lines.append("  " + " ".join(facts))

        pos60 = q.get("pos_vs_60d_high")
        if pos60 is not None:
            lines.append(f"  距60日高 {pos60:+.1f}%")

        # 除權提醒：股價已因配股下跌、但股數還沒更新時，損益會顯示成大幅虧損。
        # 不標的話，貼給其他 AI 分析會被當成真的虧了六成
        # （實例：緯穎成本 6,178、現價 2,340，比值 2.64，是 1 股配股後的結果）。
        if px and cost and cost / px >= 1.4:
            lines.append("  ⚠ 成本約為現價的 %.1f 倍，可能是除權配股後股數尚未更新，"
                         "此處損益不代表實際虧損" % (cost / px))

        act = last_action.get(code)
        if act:
            d, label, delta = act
            lines.append(f"  最近 {d.strftime('%m/%d')} {label} {abs(delta):,}股")
        lines.append("")

    lines.append("以上為個人輸入之持股整理，不構成投資建議。")
    out = "\n".join(lines).rstrip()

    # LINE 單則訊息上限 5000 字。超過會被整則拒收（不是截斷），
    # 所以這裡自己截，並明確告訴使用者少了幾檔——
    # 悄悄少掉幾檔比講出來危險，貼給別人分析時會漏掉部位。
    limit = 4800
    if len(out) > limit:
        keep, used = [], 0
        for block in out.split("\n\n"):
            if used + len(block) > limit - 200:
                break
            keep.append(block)
            used += len(block) + 2
        shown = max(0, len(keep) - 1)
        out = ("\n\n".join(keep)
               + f"\n\n（訊息長度上限，僅列出前 {shown} 檔，共 {len(positions)} 檔。"
                 f"完整清單請到網頁的持股頁查看。）")
    return out


def build_chips_report(days=10):
    """
    籌碼超人：依「誰在買」分開列出，而不是把三大法人加在一起。

    排名用「金額」不是「張數」。用張數排會讓低價股整片霸榜——
    15 元的金融股買 10 萬張只要 15 億，1500 元的股票同樣金額只有 1,000 張。

    排版有兩個為了 LINE 而做的調整：
    1. 代號包在全形括號裡。「6805　116」這種「數字 空格 數字」會被 LINE
       判斷成電話號碼而變成藍色超連結，點下去還會跳出撥號——
       包起來就不會觸發偵測。
    2. 每區只給 3 檔、區塊間空行。LINE 沒有表格也不等寬，
       一檔佔兩行、每區五檔的話整則超過 50 行，滑到後面就忘了前面在看什麼。
    """
    hist_days = get_history_days_count()
    if hist_days < 3:
        return ("❌ 法人歷史還不夠\n\n"
                "籌碼超人要看「近 10 日誰在持續買賣」，"
                "至少需要幾個交易日的累積。\n"
                "資料每天由排程自動累積，過幾天再試。")

    inst = fetch_institutional_data() or {}
    actual = min(days, hist_days)
    TOP = 3

    raw = {
        "trust_buy": get_top_by_investor("trust", "buy", actual, 20, min_days=6),
        "foreign_buy": get_top_by_investor("foreign", "buy", actual, 20, min_days=6),
        "trust_sell": get_top_by_investor("trust", "sell", actual, 20, min_days=6),
    }
    both_buy = get_both_side_codes("buy", actual, 20, min_days=5)
    both_sell = get_both_side_codes("sell", actual, 20, min_days=5)

    all_codes = {c for rows in raw.values() for c, *_ in rows}
    all_codes |= {c for c, *_ in both_buy} | {c for c, *_ in both_sell}
    prices = get_realtime_stocks_bulk(list(all_codes), workers=16)

    def amount(code, lots):
        pr = prices.get(code)
        return (abs(lots) * 1000 * pr["close"] / 100_000_000) if pr else None

    def line(code, name, amt, hit=None, total=None):
        # 代號用全形括號包住，避免被當成電話號碼
        nm = (name or stock_display_name(code, inst))[:5]
        tail = f"・{hit}/{total}天" if hit is not None else ""
        return f"{nm}（{code}）{amt:,.0f}億{tail}"

    def block(title, note, rows, top_n=TOP):
        scored = []
        for code, name, cum, hit, total in rows:
            amt = amount(code, cum)
            if amt is not None:
                scored.append((amt, code, name, hit, total))
        scored.sort(reverse=True)
        out = [title, note] if note else [title]
        if not scored:
            out.append("近期無符合標的")
        out += [line(c, n, a, h, t) for a, c, n, h, t in scored[:top_n]]
        out.append("")
        return out

    def block_both(title, note, rows, top_n=TOP):
        scored = []
        for code, name, f_lots, t_lots, tot in rows:
            amt = amount(code, tot)
            if amt is not None:
                scored.append((amt, code, name))
        scored.sort(reverse=True)
        out = [title, note]
        if not scored:
            out.append("近期無符合標的")
        out += [line(c, n, a) for a, c, n in scored[:top_n]]
        out.append("")
        return out

    lines = [f"🦸 籌碼超人　近{actual}日", "把三大法人拆開看誰在買", ""]
    lines += block("🏦 投信認養",
                   "國內基金。要對績效負責，通常做過研究才買，連續買最有參考價值",
                   raw["trust_buy"])
    lines += block("🌐 外資認養",
                   "量最大，但常是指數調整或 ETF 被動買進，未必代表看好",
                   raw["foreign_buy"])
    lines += block_both("🔥 外資投信同買",
                        "兩種立場不同的資金同時站買方，巧合機率較低",
                        both_buy)
    lines += block("📉 投信調節",
                   "做研究的那批人正在減碼",
                   raw["trust_sell"])
    lines += block_both("❄️ 外資投信同賣",
                        "兩邊同時撤退，通常不是巧合",
                        both_sell)

    lines += [
        "─" * 12,
        "億＝該法人近10日買賣金額",
        "天數＝10日內幾天站同方向",
        "",
        "為什麼要拆開看：同樣「三大法人買超3千張」，",
        "可能是投信在建倉，也可能只是自營商的",
        "權證避險部位，兩者意義差很多。",
        "",
        "認養需 6/10 天以上持續同向，",
        "單日爆量隔天就跑的不算。",
        "只看籌碼，不含基本面與估值——",
        "法人買不代表便宜，法人賣不代表變壞。",
        "※ 上市＋上櫃，非投資建議",
    ]
    report = "\n".join(lines)
    return report[:4750] + "\n…（已截斷）" if len(report) > 4800 else report



_CHIPS_CACHE_SECONDS = 300
_chips_cache = {"at": 0, "result": None}
_chips_cache_lock = threading.Lock()
_CHIPS_REFRESH_LOCK = threading.Lock()
_CHIPS_REFRESH_RUNNING = False


def _start_chips_background_refresh():
    """籌碼網頁沒有快照時，背景執行一次完整整理，不讓 HTTP request 卡住。"""
    global _CHIPS_REFRESH_RUNNING
    with _CHIPS_REFRESH_LOCK:
        if _CHIPS_REFRESH_RUNNING:
            return False
        _CHIPS_REFRESH_RUNNING = True

    def worker():
        global _CHIPS_REFRESH_RUNNING
        try:
            build_chips_payload(force_refresh=True, persist=True)
            print("✅ 籌碼超人背景刷新完成")
        except Exception as exc:
            print("⚠️ 籌碼超人背景刷新失敗: %s" % exc)
        finally:
            with _CHIPS_REFRESH_LOCK:
                _CHIPS_REFRESH_RUNNING = False

    threading.Thread(target=worker, name="chips-refresh", daemon=True).start()
    return True


def _chips_data_date(value):
    """把法人資料日統一成 ISO 日期字串；無法確認時回傳 None。"""
    if isinstance(value, datetime):
        value = value.date()
    if isinstance(value, date):
        return value.isoformat()
    text = str(value or "").strip()
    if len(text) == 8 and text.isdigit():
        try:
            return date(int(text[:4]), int(text[4:6]), int(text[6:8])).isoformat()
        except ValueError:
            return None
    try:
        return date.fromisoformat(text[:10]).isoformat()
    except ValueError:
        return None


def _chips_amount(price, lots):
    """沿用原本籌碼超人的換算：以整理當下股價將張數換算成億元。"""
    if not price or lots is None:
        return None
    try:
        return abs(float(lots)) * 1000 * float(price) / 100_000_000
    except (TypeError, ValueError):
        return None


def _chips_group_rows(rows, prices, both=False):
    """將法人 SQL 結果轉成可保存、可供 LINE／網頁共用的純 JSON 資料。"""
    scored = []
    for row in rows or []:
        if both:
            code, name, foreign_lots, trust_lots, total_lots = row
            lots = total_lots
            extra = {
                "foreign_lots": int(foreign_lots or 0),
                "trust_lots": int(trust_lots or 0),
            }
        else:
            code, name, lots, hit_days, total_days = row
            extra = {"hit_days": int(hit_days or 0),
                     "total_days": int(total_days or 0)}
        price = (prices.get(code) or {}).get("close")
        amount = _chips_amount(price, lots)
        if amount is None:
            continue
        item = {"code": str(code), "name": str(name or code),
                "lots": int(lots or 0), "amount_billion": round(amount, 4),
                "snapshot_price": float(price) if price is not None else None,
                **extra}
        scored.append(item)
    scored.sort(key=lambda x: (x["amount_billion"], x["code"]), reverse=True)
    return scored


def _chips_result_from_persisted():
    snapshot = _load_shared_data_snapshot("chips_superman")
    if not snapshot:
        return None
    payload = snapshot.get("payload")
    if not isinstance(payload, dict) or not payload.get("available"):
        return None
    groups = payload.get("groups")
    if not isinstance(groups, dict):
        return None
    # 法人突變必須保存當日外資／投信／自營商拆分；舊快照只有總張數時不可冒充完整資料。
    shifts = payload.get("institutional_shifts")
    if not isinstance(shifts, list):
        return None
    if any(not isinstance(item, dict) or not isinstance(item.get("current"), dict)
           for item in shifts):
        return None
    return {"payload": payload, "source": "持久化快照",
            "data_date": _chips_data_date(snapshot.get("data_date") or payload.get("data_date")),
            "computed_at": snapshot.get("computed_at")}


def build_chips_payload(days=10, force_refresh=False, persist=True,
                        allow_compute=True):
    """建立籌碼超人共同 payload；快照命中時不重跑五組法人查詢。"""
    now = time.time()
    if not force_refresh:
        cached = _chips_cache.get("result")
        if cached and now - _chips_cache.get("at", 0) < _CHIPS_CACHE_SECONDS:
            return cached
        persisted = _chips_result_from_persisted()
        if persisted:
            with _chips_cache_lock:
                _chips_cache.update({"at": now, "result": persisted})
            print("⚡ 籌碼超人改讀 Supabase 快照（資料日 %s）" %
                  (persisted.get("data_date") or "未標日期"))
            return persisted

    if not allow_compute:
        return {"payload": {"available": False, "building": True,
                             "history_days": None, "groups": {},
                             "institutional_shifts": []},
                "source": "背景整理中", "data_date": None,
                "computed_at": None}

    with _chips_cache_lock:
        if not force_refresh:
            cached = _chips_cache.get("result")
            if cached and time.time() - _chips_cache.get("at", 0) < _CHIPS_CACHE_SECONDS:
                return cached
        hist_days = get_history_days_count()
        if hist_days < 3:
            result = {"payload": {"available": False, "history_days": hist_days,
                                  "groups": {}},
                      "source": "資料不足", "data_date": None,
                      "computed_at": None}
            _chips_cache.update({"at": time.time(), "result": result})
            return result

        inst = fetch_institutional_data() or {}
        actual = min(int(days), hist_days)
        raw = {
            "trust_buy": get_top_by_investor("trust", "buy", actual, 20, min_days=6),
            "foreign_buy": get_top_by_investor("foreign", "buy", actual, 20, min_days=6),
            "trust_sell": get_top_by_investor("trust", "sell", actual, 20, min_days=6),
        }
        both_buy = get_both_side_codes("buy", actual, 20, min_days=5)
        both_sell = get_both_side_codes("sell", actual, 20, min_days=5)
        institutional_shifts = get_institutional_shift_candidates(
            prior_days=min(5, max(3, actual - 1)), top_n=12)
        all_codes = {c for rows in raw.values() for c, *_ in rows}
        all_codes |= {c for c, *_ in both_buy} | {c for c, *_ in both_sell}
        prices = get_realtime_stocks_bulk(list(all_codes), workers=16) if all_codes else {}
        groups = {
            "trust_buy": _chips_group_rows(raw["trust_buy"], prices),
            "foreign_buy": _chips_group_rows(raw["foreign_buy"], prices),
            "both_buy": _chips_group_rows(both_buy, prices, both=True),
            "trust_sell": _chips_group_rows(raw["trust_sell"], prices),
            "both_sell": _chips_group_rows(both_sell, prices, both=True),
        }
        data_date = _chips_data_date(_t86_cache.get("data_date"))
        payload = {
            "available": True, "actual_days": actual,
            "history_days": hist_days,             "data_date": data_date,
            "groups": groups,
            "institutional_shifts": institutional_shifts,
            "shift_prior_days": min(5, max(3, actual - 1)),
            "amount_note": "金額以整理當下可取得的真實股價換算",

        }
        result = {"payload": payload, "source": "本次完整整理",
                  "data_date": data_date, "computed_at": taiwan_now().isoformat()}
        _chips_cache.update({"at": time.time(), "result": result})
        if persist and data_date:
            saved = _save_shared_data_snapshot(
                "chips_superman", payload, data_date=data_date,
                source_meta={"source": "chips_superman", "days": actual,
                             "group_count": len(groups),
                             "shift_count": len(institutional_shifts)},
            )
            print("💾 籌碼超人快照%s" % ("已保存" if saved else "保存失敗"))
        return result


def _line_full_web_url(user_id, base_url, target, extra_params=None):
    """所有 LINE「查看完整分析」共用同一套 token + 路由組裝。"""
    token=create_web_token(user_id)
    if not token: return None
    params=dict(extra_params or {}); params["t"]=token
    return f"{public_web_base_url(base_url)}{target}?{urlencode(params, doseq=True)}"


def _line_feature_web_url(user_id, feature, base_url=None, code=None):
    routes={
        "positions":("/web/portfolio",{}),
        "positions_export":("/web/positions",{}),
        "quote":("/web/stock",{"code":normalize_code(code or "")}),
        "etf":("/web/etf-detail",{"code":normalize_code(code or "")}),
        "news":("/web/news",{}),
        "premarket":("/web/premarket",{}),
        "debrief":("/web/postmarket",{}),
        "chips":("/web/workbench",{"tab":"籌碼"}),
        "turning":("/web/workbench",{"tab":"轉折"}),
        "blackhorse":("/web/workbench",{"tab":"黑馬"}),
        "radar":("/web/workbench",{"tab":"雷達"}),
        "leaderboard":("/web/leaderboard",{}),
    }
    target,params=routes.get(str(feature or ""),("/web/portfolio",{}))
    params={k:v for k,v in params.items() if v not in (None,"")}
    return _line_full_web_url(user_id,base_url,target,params)


def build_line_chips_message(user_id, base_url=None):
    """LINE 籌碼超人：只顯示三個重點區塊，完整五區資料由網頁查看。"""
    result = build_chips_payload()
    payload = result.get("payload") or {}
    if not payload.get("available"):
        return TextSendMessage(
            text="❌ 法人歷史資料還不夠，籌碼超人需要至少幾個交易日的累積；請稍後再試。")

    web_url = _line_feature_web_url(user_id, "chips", base_url)
    data_date = result.get("data_date") or payload.get("data_date") or "未標日期"
    actual = payload.get("actual_days") or 0
    contents = [
        {"type": "text", "text": "🦸 籌碼超人｜今日摘要", "weight": "bold",
         "size": "xl", "color": "#1B2027"},
        {"type": "text", "text": f"資料來源：{result.get('source')}・資料日：{data_date}・近 {actual} 日",
         "size": "xs", "color": "#767D85", "margin": "sm", "wrap": True},
    ]
    shift_items = (payload.get("institutional_shifts") or [])[:3]
    contents.append({"type": "separator", "margin": "lg", "color": "#E8EAE6"})
    contents.append({"type": "text", "text": "⚡ 法人籌碼突變", "weight": "bold",
                     "size": "md", "color": "#6E5228", "margin": "lg"})
    contents.append({"type": "text", "text": "比較最新 T86 與前幾個交易日方向，不代表即時法人資料。",
                     "size": "xs", "color": "#767D85", "margin": "xs", "wrap": True})
    if not shift_items:
        contents.append({"type": "text", "text": "目前沒有符合方向反轉或異常放大條件的標的。",
                         "size": "sm", "color": "#767D85", "margin": "sm", "wrap": True})
    for item in shift_items:
        changes = "、".join(item.get("investor_changes") or []) or "三大法人合計方向變化"
        current_total = int(item.get("current_total_lots") or 0)
        ratio = float(item.get("magnitude_ratio") or 0)
        ratio_text = f"・約前期平均 {ratio:.1f} 倍" if ratio >= 2.5 else ""
        contents.append({"type": "text", "text":
                         f"・{item.get('name')}（{item.get('code')}） {item.get('event_type')}｜"
                         f"{changes}｜今日 {current_total:+,} 張{ratio_text}｜{item.get('consensus')}",
                         "size": "sm", "color": "#454C55", "margin": "sm", "wrap": True})
    labels = [
        ("both_buy", "🔥 外資投信同買", "兩種資金同時站買方"),
        ("trust_buy", "🏦 投信認養", "至少 6／10 天持續同方向"),
        ("trust_sell", "📉 今日需留意調節", "投信近十日持續賣超"),
    ]
    for key, title, note in labels:
        contents.append({"type": "separator", "margin": "lg", "color": "#E8EAE6"})
        contents.append({"type": "text", "text": title, "weight": "bold",
                         "size": "md", "color": "#6E5228", "margin": "lg"})
        contents.append({"type": "text", "text": note, "size": "xs",
                         "color": "#767D85", "margin": "xs", "wrap": True})
        items = (payload.get("groups") or {}).get(key) or []
        if not items:
            contents.append({"type": "text", "text": "近期無符合標的", "size": "sm",
                             "color": "#767D85", "margin": "sm"})
        for item in items[:3]:
            days_text = (f"・{item.get('hit_days', 0)}/{item.get('total_days', 0)}天"
                         if key == "trust_buy" or key == "trust_sell" else "")
            contents.append({"type": "text", "text":
                             f"・{item.get('name')}（{item.get('code')}）"
                             f" {item.get('amount_billion', 0):,.0f}億{days_text}",
                             "size": "sm", "color": "#454C55", "margin": "sm", "wrap": True})
    if web_url:
        contents += [
            {"type": "separator", "margin": "lg", "color": "#E8EAE6"},
            {"type": "button", "style": "primary", "height": "sm",
             "color": "#6E5228", "margin": "lg",
             "action": {"type": "uri", "label": "查看完整籌碼分析", "uri": web_url}},
        ]
    bubble = {"type": "bubble",
              "body": {"type": "box", "layout": "vertical", "contents": contents,
                        "paddingAll": "18px", "backgroundColor": "#FFFFFF"},
              "styles": {"body": {"backgroundColor": "#FFFFFF"}}}
    alt = f"🦸 籌碼超人｜近 {actual} 日｜資料日 {data_date}"
    return FlexSendMessage(alt_text=alt, contents=bubble)


def render_chips_web_body(result):
    """網頁籌碼超人完整版：完整五區、資料日期與換算說明。"""
    payload = result.get("payload") or {}
    if payload.get("building"):
        return '''<section class="card"><div class="screener-fast-state"><span class="screener-fast-state-mark"></span><div>
<b>籌碼超人正在背景整理</b><div class="screener-fast-note">目前沒有可使用的完整快照，本頁已立即回應；法人資料整理完成後重新整理即可查看。</div>
<p><a class="btn" href="/web/chips">重新整理查看結果</a></p>
</div></div></section>'''
    if not payload.get("available"):
        return '<section class="card"><div class="empty">法人歷史資料還不夠，暫時無法建立近十日籌碼整理。</div></section>'
    esc = html.escape
    group_info = [
        ("trust_buy", "🏦 投信認養", "國內基金持續站在買方，至少 6／10 天才列入認養。"),
        ("foreign_buy", "🌐 外資認養", "外資近十日持續買超；外資也可能包含指數或 ETF 被動調整。"),
        ("both_buy", "🔥 外資投信同買", "外資與投信同時站買方，顯示兩類資金方向一致。"),
        ("trust_sell", "📉 投信調節", "投信近十日持續賣超，作為籌碼面的撤退訊號觀察。"),
        ("both_sell", "❄️ 外資投信同賣", "外資與投信同時站賣方，顯示兩類資金方向一致轉弱。"),
    ]
    sections = []
    shift_items = payload.get("institutional_shifts") or []
    shift_prior_days = int(payload.get("shift_prior_days") or 5)
    shift_rows = []
    for item in shift_items:
        changes = "、".join(item.get("investor_changes") or []) or "三大法人合計方向變化"
        current_total = int(item.get("current_total_lots") or 0)
        ratio = float(item.get("magnitude_ratio") or 0)
        ratio_text = f"；約前{shift_prior_days}日平均絕對值 {ratio:.1f} 倍" if ratio >= 2.5 else ""
        detail = (f"{item.get('event_type')}・{changes}・今日三大法人 {current_total:+,} 張"
                  f"・{item.get('consensus')}{ratio_text}")
        shift_rows.append(
            f'<div class="chips-row chips-row-rich"><div><b>{esc(str(item.get("name") or item.get("code")))}</b>'
            f'<small>（{esc(str(item.get("code") or ""))}）・{esc(detail)}</small>'
            f'<details class="chips-inline-chart" data-chips-code="{esc(str(item.get("code") or ""))}"><summary>查看近20日法人圖</summary><div class="chips-inline-chart-body"><span>點開後載入，不影響整頁速度。</span></div></details></div>'
            f'<strong>{esc(str(item.get("event_type") or "方向變化"))}</strong></div>')
    if not shift_rows:
        shift_rows.append('<div class="chips-empty">目前沒有符合「方向反轉或異常放大」條件的標的</div>')
    shift_section = (
        '<section class="chips-section chips-shift-section">'
        '<h2>⚡ 法人籌碼突變</h2>'
        f'<p>比較最新 T86 與前 {shift_prior_days} 個交易日平均方向；只列出方向反轉或異常放大的標的。</p>'
        f'{"".join(shift_rows)}</section>')
    for key, title, note in group_info:
        rows = []
        for item in ((payload.get("groups") or {}).get(key) or []):
            if key in ("trust_buy", "trust_sell"):
                detail = (f"投信 {int(item.get('lots') or 0):+,} 張・"
                          f"{item.get('hit_days', 0)}/{item.get('total_days', 0)} 天同方向")
            elif key == "foreign_buy":
                detail = f"外資 {int(item.get('lots') or 0):+,} 張"
            else:
                detail = (f"外資 {int(item.get('foreign_lots') or 0):+,} 張・"
                          f"投信 {int(item.get('trust_lots') or 0):+,} 張")
            rows.append(
                f'<div class="chips-row chips-row-rich"><div><b>{esc(str(item.get("name") or item.get("code")))}</b>'
                f'<small>（{esc(str(item.get("code") or ""))}）・{esc(detail)}</small>'
                f'<details class="chips-inline-chart" data-chips-code="{esc(str(item.get("code") or ""))}"><summary>查看近20日法人圖</summary><div class="chips-inline-chart-body"><span>點開後載入，不影響整頁速度。</span></div></details></div>'
                f'<strong>{float(item.get("amount_billion") or 0):,.0f} 億</strong></div>')
        if not rows:
            rows.append('<div class="chips-empty">近期無符合標的</div>')
        sections.append(
            f'<section class="chips-section"><h2>{esc(title)}</h2>'
            f'<p>{esc(note)}</p>{"".join(rows)}</section>')
    data_date = result.get("data_date") or payload.get("data_date") or "未標日期"
    source = result.get("source") or "未標來源"
    chips_script = r'''<script>(function(){
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}
function fmt(v){var n=Number(v)||0;return (n>0?'+':'')+Math.round(n).toLocaleString('zh-TW');}
function draw(box,data,mode){
  if(!Array.isArray(data)||!data.length){box.innerHTML='<div class="chips-chart-empty">目前沒有足夠的法人歷史資料。</div>';return;}
  var rows=data.slice(-20), labels={total:'三大法人',foreign:'外資',trust:'投信',dealer:'自營商'};
  var vals=rows.map(function(d){if(mode==='total')return (Number(d.foreign)||0)+(Number(d.trust)||0)+(Number(d.dealer)||0);return Number(d[mode])||0;});
  var max=1;vals.forEach(function(v){max=Math.max(max,Math.abs(v));});
  var w=760,h=350,p={l:58,r:18,t:28,b:48},pw=w-p.l-p.r,ph=h-p.t-p.b,step=pw/rows.length,barW=Math.min(22,step*0.58);
  function y(v){return p.t+ph/2-(v/max)*(ph/2-8);}
  var zero=y(0), svg='<svg class="chips-vsvg" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="近20日'+labels[mode]+'法人買賣超">';
  [-max,-max/2,0,max/2,max].forEach(function(v){var yy=y(v);svg+='<line x1="'+p.l+'" y1="'+yy+'" x2="'+(w-p.r)+'" y2="'+yy+'" class="'+(v===0?'zero':'grid')+'"/><text x="'+(p.l-8)+'" y="'+(yy+4)+'" text-anchor="end" class="tick">'+fmt(v)+'</text>';});
  svg+='<text x="'+(p.l+2)+'" y="'+(p.t-8)+'" class="axis-title">買超</text><text x="'+(p.l+2)+'" y="'+(h-p.b+26)+'" class="axis-title sell">賣超</text>';
  rows.forEach(function(d,i){var v=vals[i],x=p.l+i*step+(step-barW)/2,yy=v>=0?y(v):zero,hh=Math.max(1,Math.abs(y(v)-zero)),cls=v>0?'buy':v<0?'sell':'flat';svg+='<rect x="'+x.toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+barW.toFixed(1)+'" height="'+hh.toFixed(1)+'" rx="5" class="'+cls+'"><title>'+esc(String(d.day||''))+'　'+esc(labels[mode])+' '+esc(fmt(v))+' 張</title></rect>';if(Math.abs(v)>=max*0.32||i>=rows.length-2){var ly=v>=0?yy-7:yy+15;svg+='<text x="'+(x+barW/2).toFixed(1)+'" y="'+ly.toFixed(1)+'" text-anchor="middle" class="value '+cls+'">'+esc(fmt(v))+'</text>';}if(i%2===0||i===rows.length-1){svg+='<text x="'+(x+barW/2).toFixed(1)+'" y="'+(h-17)+'" text-anchor="middle" class="date">'+esc(String(d.day||'').slice(5))+'</text>';}});
  svg+='</svg>';
  var latest=vals[vals.length-1]||0, prior=vals.length>1?vals[vals.length-2]||0:0, change=latest-prior;
  box.innerHTML='<div class="chips-vchart-head"><div><b>'+esc(labels[mode])+' · 近20日</b><small>0 軸以上＝買超（紅）　0 軸以下＝賣超（綠）</small></div><strong class="'+(latest>=0?'buy-text':'sell-text')+'">最新 '+esc(fmt(latest))+' 張</strong></div><div class="chips-vchart">'+svg+'</div><div class="chips-vchart-summary"><span>最新交易日：<b>'+esc(String(rows[rows.length-1].day||'').replace(/-/g,'/'))+'</b></span><span>前一日：<b>'+esc(fmt(prior))+' 張</b></span><span>日變化：<b class="'+(change>=0?'buy-text':'sell-text')+'">'+esc(fmt(change))+' 張</b></span></div>';
}
function mount(details,data){
  var body=details.querySelector('.chips-inline-chart-body'); if(!body)return;
  var modes=[['total','三大法人'],['foreign','外資'],['trust','投信'],['dealer','自營商']];
  body.innerHTML='<div class="chips-chart-tabs">'+modes.map(function(m,i){return '<button type="button" class="chips-chart-tab '+(i===0?'active':'')+'" data-mode="'+m[0]+'">'+m[1]+'</button>';}).join('')+'</div><div class="chips-chart-view"></div>';
  var view=body.querySelector('.chips-chart-view');
  body.querySelectorAll('.chips-chart-tab').forEach(function(btn){btn.addEventListener('click',function(){body.querySelectorAll('.chips-chart-tab').forEach(function(b){b.classList.remove('active');});btn.classList.add('active');draw(view,data,btn.dataset.mode);});});
  draw(view,data,'total');
}
document.querySelectorAll('[data-chips-code]').forEach(function(d){d.addEventListener('toggle',function(){if(!d.open||d.dataset.loaded)return;d.dataset.loaded='1';var box=d.querySelector('.chips-inline-chart-body'),code=d.getAttribute('data-chips-code');fetch('/web/api/workbench/strategy-detail?code='+encodeURIComponent(code)+'&kind=institutional',{credentials:'same-origin',cache:'no-store'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}).then(function(x){if(!x.ok)throw new Error(x.error||'載入失敗');mount(d,x.data||[]);}).catch(function(e){d.dataset.loaded='';box.innerHTML='<span>載入失敗：'+esc(String(e.message||e))+'</span>';});});});})();</script>'''
    return f'''<div class="tabs">\n  <a href="/web/screener?mode=blackhorse&view=list">黑馬</a>\n  <a href="/web/screener?mode=radar&view=list">雷達</a>\n  <a href="/web/chips" class="on">籌碼超人</a>\n  <a href="/web/screener?mode=review">成效</a>\n  <a href="/web/screener?mode=turning">轉折觀察</a>\n  <a href="/web/etf">ETF 專區</a>\n</div>\n<div class="chips-meta">資料來源：<b>{esc(str(source))}</b>　資料日：<b>{esc(str(data_date))}</b>　近 <b>{int(payload.get("actual_days") or 0)}</b> 個交易日</div>
<div class="callout">億＝以整理當下可取得的真實股價，將法人近十日累計張數換算為億元；天數＝近十日站同方向的天數。這裡只看法人籌碼，不含基本面與估值。</div>
{shift_section}
{"".join(sections)}
<div class="callout">認養需至少 6／10 天持續同向；單日爆量隔天就跑的不算。法人買不代表便宜，法人賣不代表公司變壞。以上為公開資料整理，不構成投資建議。</div>{chips_script}'''


def get_cumulative_net_buy_for_codes(codes, days=10):
    """查指定股票近 N 個交易日的累計買超與買超天數。回傳 {code: (累計張數, 買超天數)}。"""
    codes = [str(c).strip() for c in codes]
    if not codes:
        return {}
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            WITH recent AS (
                SELECT DISTINCT trade_date FROM inst_history
                ORDER BY trade_date DESC LIMIT %s
            )
            SELECT h.code,
                   SUM(h.total_net_lots),
                   COUNT(*) FILTER (WHERE h.total_net_lots > 0)
            FROM inst_history h
            JOIN recent r ON h.trade_date = r.trade_date
            WHERE h.code = ANY(%s)
            GROUP BY h.code
            """,
            (days, codes),
        )
        rows = cursor.fetchall()
        cursor.close()
        return {r[0]: (r[1] or 0, r[2] or 0) for r in rows}
    except Exception as e:
        print(f"❌ 查詢自選股累計買超失敗: {e}")
        return {}
    finally:
        release_db_connection(conn)


def get_cumulative_net_buy(days=10, top_n=80, codes=None):
    """
    從 inst_history 撈「近 N 個交易日累計買超」前 top_n 名。
    這是黑馬候選池的來源——長線佈局往往是「量小但持續」，
    看單日買超排行會漏掉那種每天買 800 張、連買 15 天的股票。
    codes 若給定，只在該清單內排名——這對「依類股分別選股」很重要：
    全市場共用一份排行時，電子股的買超量遠大於傳產與金融，
    傳產股會被擠到幾百名之外，篩選後就整頁空白。
    回傳 [(code, name, 累計張數, 有買超的天數), ...]
    """
    # 不用「%s IS NULL OR ...」這種寫法：psycopg2 無法推斷該參數的型別，
    # 會直接丟型別錯誤，而錯誤被 except 吃掉後只會回傳空清單，
    # 表面上看起來像「這個類股沒有標的」，實際上是查詢從沒成功過。
    code_clause = ""
    params = [days]
    if codes is not None:
        if not codes:
            return []
        code_clause = "AND h.code = ANY(%s)"
        params.append(list(codes))
    params.append(top_n)

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            f"""
            WITH recent AS (
                SELECT DISTINCT trade_date FROM inst_history
                ORDER BY trade_date DESC LIMIT %s
            )
            SELECT h.code,
                   MAX(h.name) AS name,
                   SUM(h.total_net_lots) AS cum_lots,
                   COUNT(*) FILTER (WHERE h.total_net_lots > 0) AS buy_days
            FROM inst_history h
            JOIN recent r ON h.trade_date = r.trade_date
            WHERE length(h.code) = 4 AND h.code ~ '^[0-9]+$'
              AND h.code NOT LIKE '00%%'
              {code_clause}
            GROUP BY h.code
            HAVING SUM(h.total_net_lots) > 0
            ORDER BY cum_lots DESC
            LIMIT %s
            """,
            tuple(params),
        )
        rows = cursor.fetchall()
        cursor.close()
        return [(r[0], r[1], r[2] or 0, r[3] or 0) for r in rows]
    except Exception as e:
        print(f"❌ 查詢累計買超失敗: {e}")
        return []
    finally:
        release_db_connection(conn)


def check_data_integrity(days=30):
    """
    檢查法人歷史有沒有缺交易日。

    為什麼需要這個：缺資料不會報錯。「近 N 個交易日」是用
    SELECT DISTINCT trade_date ... LIMIT N 取的，少了一天它就默默
    往前多抓一天，統計照樣算得出來、數字也看起來合理，
    只有拿去跟券商對帳才會發現。這種錯誤在正式環境可以躺很久。

    判斷方式：把資料庫裡的日期序列跟「該區間內的工作日」比對。
    國定假日無法從程式判斷（每年不同），所以只回報「疑似」缺漏，
    由人自己確認那天是不是真的休市。

    回傳 (實際天數, 疑似缺漏的日期清單, 最新日期)
    """
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT DISTINCT trade_date FROM inst_history
            WHERE trade_date >= CURRENT_DATE - %s
            ORDER BY trade_date DESC
            """, (days,))
        dates = [r[0] for r in cursor.fetchall()]
        cursor.close()
    except Exception as e:
        print(f"❌ 檢查資料完整性失敗: {e}")
        return 0, [], None
    finally:
        release_db_connection(conn)

    if not dates:
        return 0, [], None

    have = set(dates)
    newest, oldest = dates[0], dates[-1]

    # 只檢查有資料的區間內部，不往未來或更早推——
    # 區間外沒資料是正常的（還沒抓 / 超出保留期限），不該報成缺漏
    missing, d = [], oldest
    while d <= newest:
        if d.weekday() < 5 and d not in have:   # 平日卻沒資料
            missing.append(d)
        d += timedelta(days=1)

    return len(dates), missing, newest


def get_history_days_count():
    """目前資料庫累積了幾個交易日的法人歷史（用來判斷連續指標可不可信）。"""
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(DISTINCT trade_date) FROM inst_history")
        n = cursor.fetchone()[0]
        cursor.close()
        return n or 0
    except Exception as e:
        print(f"❌ 查詢歷史天數失敗: {e}")
        return 0
    finally:
        release_db_connection(conn)


def fetch_tpex_institutional():
    """
    抓上櫃三大法人買賣超（TPEx openapi）。TWSE 的 T86 只含上市，
    少了這塊，上櫃股在籌碼相關的功能裡等於一片空白——
    連買天數永遠是 0、黑馬候選池也永遠不會出現上櫃股。

    這個端點只給「最新一個交易日」，不接受日期參數，
    所以歷史只能每天靠 cron 往前累積，無法像 T86 那樣回補。

    欄位名稱有兩個坑：
    1. JSON key 帶有多餘空格且命名不一致（例如
       'ForeignInvestorsInclude MainlandAreaInvestors-Difference' 中間有空格），
       所以用 _pick() 依序嘗試多個候選名稱，不能寫死一個。
    2. 「外資」有兩種口徑：含與不含外資自營商。這裡取「不含」的那個，
       跟 TWSE T86 的「外陸資買賣超股數(不含外資自營商)」對齊，
       否則兩個市場的外資數字定義不同，混在一起比較沒有意義。

    回傳 (資料 dict, 資料日期 YYYYMMDD) ；失敗回傳 (None, None)。
    """
    rows = _get_json(f"{TPEX_BASE}/tpex_3insti_daily_trading", timeout=20)
    if not rows:
        return None, None

    def to_int(s):
        try:
            return int(str(s).replace(",", "").strip())
        except (ValueError, TypeError):
            return 0

    # 民國年轉西元：1150814 → 20260814
    data_date = None
    raw_date = _pick(rows[0], "Date")
    if len(raw_date) == 7 and raw_date.isdigit():
        data_date = f"{int(raw_date[:3]) + 1911}{raw_date[3:]}"

    result = {}
    for row in rows:
        code = _pick(row, "SecuritiesCompanyCode", "Code")
        if not code:
            continue
        name = _pick(row, "CompanyName", "Name")

        foreign = to_int(_pick(
            row,
            "Foreign Investors include Mainland Area Investors (Foreign Dealers excluded)-Difference",
            "ForeignInvestorsIncludeMainlandAreaInvestors(ForeignDealersexcluded)-Difference"))
        foreign_dealer = to_int(_pick(row, "ForeignDealers-Difference",
                                      "Foreign Dealers-Difference"))
        trust = to_int(_pick(row, "SecuritiesInvestmentTrustCompanies-Difference"))
        dealer = to_int(_pick(row, "Dealers-Difference"))
        total = to_int(_pick(row, "TotalDifference"))

        # 沒有合計欄位時自行加總（外資不含自營，所以要另外把外資自營加回來）
        if not total:
            total = foreign + foreign_dealer + trust + dealer

        result[code] = {
            "name": name or code,
            "foreign_net_lots": shares_to_lots(foreign),
            "trust_net_lots": shares_to_lots(trust),
            "dealer_net_lots": shares_to_lots(dealer + foreign_dealer),
            "total_net_lots": shares_to_lots(total),
        }

    if not result:
        return None, None
    print(f"✅ 上櫃法人買賣超抓取成功（{data_date}），共 {len(result)} 檔")
    return result, data_date


def _load_latest_institutional_history():
    """從 inst_history 讀最近一個已保存的真實法人交易日。"""
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("""
            SELECT h.code, h.trade_date, h.name,
                   h.foreign_net_lots, h.trust_net_lots,
                   h.dealer_net_lots, h.total_net_lots
            FROM inst_history h
            JOIN (SELECT MAX(trade_date) AS latest_date FROM inst_history) d
              ON h.trade_date = d.latest_date
            ORDER BY h.code
        """)
        rows = cursor.fetchall()
        cursor.close()
    except Exception as exc:
        print(f"⚠️ 讀取最新法人歷史快照失敗: {exc}")
        return {}, None
    finally:
        release_db_connection(conn)

    if not rows:
        return {}, None
    data_date = rows[0][1].strftime("%Y%m%d") if rows[0][1] else None
    data = {
        row[0]: {
            "name": row[2] or row[0],
            "foreign_net_lots": row[3] or 0,
            "trust_net_lots": row[4] or 0,
            "dealer_net_lots": row[5] or 0,
            "total_net_lots": row[6] or 0,
        }
        for row in rows
    }
    return data, data_date


def fetch_institutional_data(codes=None):
    """
    抓當日三大法人買賣超，涵蓋上市（TWSE T86）與上櫃（TPEx）。

    上市的部分若今天還沒公布（盤中、假日），會自動往前找最近一個
    有資料的交易日，最多往前找 5 天。上櫃端點只給最新一日，不能指定日期。
    一天只需成功抓取一次，之後直接用快取。
    """
    tw_now = taiwan_now()
    today = tw_now.strftime("%Y%m%d")
    requested_codes = sorted({str(c).strip() for c in (codes or []) if str(c).strip()})

    # 首頁只需要自己的持股法人資料；不要為 12 檔持股讀完整 1.8 萬筆，
    # 更不要在首頁查不到快照時再打外部 T86/TPEx API。
    if requested_codes:
        conn = get_db_connection()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT h.code, h.trade_date, h.name,
                       h.foreign_net_lots, h.trust_net_lots,
                       h.dealer_net_lots, h.total_net_lots
                FROM inst_history h
                WHERE h.trade_date = (SELECT MAX(trade_date) FROM inst_history)
                  AND h.code = ANY(%s)
                ORDER BY h.code
            """, (requested_codes,))
            rows = cur.fetchall()
        except Exception as exc:
            print(f"⚠️ 首頁持股法人快照讀取失敗: {exc}")
            return {}
        finally:
            release_db_connection(conn)
        result = {}
        for row in rows:
            result[str(row[0]).strip()] = {
                "name": row[2] or row[0],
                "foreign_net_lots": row[3] or 0,
                "trust_net_lots": row[4] or 0,
                "dealer_net_lots": row[5] or 0,
                "total_net_lots": row[6] or 0,
            }
        print(f"⚡ 首頁法人只讀持股快照：{len(result)}/{len(requested_codes)} 檔")
        return result

    # 快取判斷不能只看「今天抓過了嗎」。
    # 早上抓的時候今天的 T86 還沒公布，往前找會拿到昨天的資料，
    # 然後這份昨天的資料就被當成「今天抓過了」而沿用一整天——
    # 即使下午三點半後今天的資料已經出來也不會更新。
    # 所以還要看「快取裡的資料是不是今天的」：不是的話，
    # 過了公布時間就定期重試，而不是等隔天。
    cached = _t86_cache.get("data")
    cache_fresh = _t86_cache.get("cache_date") == today and cached
    data_is_today = _t86_cache.get("data_date") == today
    last_try = _t86_cache.get("last_attempt", 0)

    # T86 約在收盤後陸續公布，15:00 前不必重試
    past_publish = tw_now.hour >= 15
    should_retry = (cache_fresh and not data_is_today and past_publish
                    and time.time() - last_try > 900)   # 每 15 分鐘重試一次

    # 同一程序已命中且尚未進入重試窗口時直接返回，不多做資料庫查詢。
    if cache_fresh and not should_retry:
        return cached

    # warmup 可能在另一個 Render worker 完成；若 DB 已有最新真實快照，
    # 不必因為程序記憶體是空的就再次打 TWSE／TPEx。週末更不應重試外部端點，
    # 因為資料不會在週末變成新的交易日。
    history_data, history_date = _load_latest_institutional_history()
    if history_data and (tw_now.weekday() >= 5 or history_date == today):
        _t86_cache["cache_date"] = today
        _t86_cache["data_date"] = history_date
        _t86_cache["data"] = history_data
        print(f"⚡ 法人改讀資料庫最新快照（{history_date}），共 {len(history_data)} 檔")
        return history_data

    _t86_cache["last_attempt"] = time.time()
    merged, data_date = {}, None
    for days_back in range(0, 6):
        query_date = (taiwan_now() - timedelta(days=days_back)).strftime("%Y%m%d")
        data = _fetch_t86_for_date(query_date)
        if data:
            merged.update(data)
            data_date = query_date
            save_t86_history(query_date, data)
            break

    # 上櫃：即使上市那邊抓失敗也照抓，兩個市場互相獨立，
    # 沒理由因為一邊沒資料就讓另一邊也一起沒有。
    try:
        tpex, tpex_date = fetch_tpex_institutional()
        if tpex:
            merged.update(tpex)
            # 只有在「上櫃日期跟上市同一天」時才存歷史。
            # 兩邊日期不同時（例如上市今天還沒公布、上櫃已經有了）若照存，
            # 資料庫會多出一個「只有上櫃股票」的交易日，
            # 而「近 N 個交易日」是用全市場的 DISTINCT trade_date 去數的——
            # 那一天會佔掉一個名額卻對上市股票貢獻 0，
            # 等於讓上市股票的統計區間悄悄少了一天，數字全部對不上。
            if tpex_date and tpex_date == data_date:
                save_t86_history(tpex_date, tpex)
            elif tpex_date and not data_date:
                # 上市完全沒資料時才單獨存上櫃，此時不會造成混合窗口問題
                save_t86_history(tpex_date, tpex)
                data_date = tpex_date
            elif tpex_date != data_date:
                print(f"⚠️ 上櫃資料日期（{tpex_date}）與上市（{data_date}）不同，"
                      f"本次不寫入歷史以免造成單一市場的交易日")
    except Exception as e:
        print(f"❌ 上櫃法人資料抓取失敗: {e}")

    if merged:
        _t86_cache["cache_date"] = today
        _t86_cache["data_date"] = data_date
        _t86_cache["data"] = merged
        return merged

    print("⚠️ 上市往前找了 5 天、上櫃也無資料")
    return _t86_cache["data"]


def format_data_date(yyyymmdd):
    """把 20260818 轉成 08/18；轉不了就原樣回傳，不要因為格式問題就沒有日期。"""
    d = str(yyyymmdd or "")
    if len(d) == 8 and d.isdigit():
        return f"{d[4:6]}/{d[6:8]}"
    return d or "未知"

# --- 真實評分邏輯 ---
def score_from_net_lots(lots):
    """保留舊函式供相容舊畫面；五大因子不再用張數直接計分。"""
    if lots >= 5000: return 40
    if lots >= 2000: return 35
    if lots >= 1000: return 28
    if lots >= 300: return 20
    if lots >= 50: return 12
    if lots > 0: return 5
    return 0

def calc_turnover_billion(close, volume_shares):
    """成交金額（億元）。"""
    if not close or not volume_shares:
        return 0.0
    return (close * volume_shares) / 100_000_000

def score_from_chip_amount(net_lots, avg_price_10d, turnover_10d_billion):
    """
    籌碼 0-5 分：用「近10日法人淨買超金額 / 近10日成交金額」評估資金強度。
    不直接用張數，避免 10 元股與 10,000 元股的張數不可比。
    """
    if net_lots is None or avg_price_10d is None or turnover_10d_billion is None:
        return 0.0
    if turnover_10d_billion <= 0 or net_lots <= 0:
        return 0.0
    net_amount_billion = float(net_lots) * float(avg_price_10d) / 100_000.0
    ratio_pct = net_amount_billion / float(turnover_10d_billion) * 100.0
    if ratio_pct >= 15:
        return 5.0
    if ratio_pct >= 10:
        return 4.2
    if ratio_pct >= 5:
        return 3.2
    if ratio_pct >= 2:
        return 2.0
    if ratio_pct > 0:
        return 0.8
    return 0.0

def score_from_technical_structure(price):
    """
    技術 0-5 分：看趨勢、均線位置、回踩支撐、突破與量價確認，
    不再用「今日漲跌幅」直接代表技術強弱。
    """
    if not price:
        return 0.0
    close = price.get("close")
    ma20 = price.get("ma20")
    ma20_prev = price.get("ma20_prev")
    ma60 = price.get("ma60")
    ma60_prev = price.get("ma60_prev")
    low_10d = price.get("low_10d")
    high_20d = price.get("high_20d")
    high_60d = price.get("high_60d")
    support = price.get("support")
    broke_support = bool(price.get("broke_support"))
    vol_ratio = price.get("vol_ratio") or 0

    if close is None:
        return 0.0

    score = 0.0

    # 1) 趨勢結構：價格站在均線之上，且均線本身向上。
    if ma20 and close >= ma20:
        score += 0.75
    if ma20 and ma20_prev and ma20 > ma20_prev:
        score += 0.75

    # 2) 均線位置：避免只因離20MA太遠就被當成「更強」。
    if ma20:
        diff20 = (close - ma20) / ma20 * 100
        if 0 <= diff20 <= 15:
            score += 0.5
        elif diff20 > 15:
            score += 0.3
    if ma60 and close >= ma60:
        score += 0.5

    # 3) 回踩支撐後守住：最近10日曾靠近20MA／支撐，現在重新站上。
    pullback = False
    if ma20 and low_10d is not None and close >= ma20:
        pullback = low_10d <= ma20 * 1.03
    if support and close >= support and not broke_support:
        if low_10d is not None and low_10d <= support * 1.03:
            pullback = True
    if pullback:
        score += 1.0

    # 4) 突破結構：近20日／60日高點，不用今天漲幅判斷。
    if high_20d and close > high_20d:
        score += 0.6
    if high_60d and close >= high_60d:
        score += 0.4

    # 5) 量價確認：只有在突破或明確上攻時才給量能加分。
    if high_20d and close > high_20d and vol_ratio >= 1.3:
        score += 0.5
    elif vol_ratio >= 1.5 and close >= (ma20 or close):
        score += 0.3

    return round(min(5.0, score), 1)

def score_from_technical(pct, turnover_billion):
    """舊介面相容函式；五大因子不再使用此舊的單日量價算法。"""
    pct_score = max(0, min(30, pct * 3))
    vol_score = max(0, min(30, turnover_billion))
    return round(pct_score + vol_score)

def fmt_resistance(r):
    """
    壓力為 None 代表「近 60 日內找不到更高的價位」，不等於上方真的沒有賣壓——
    更早之前的套牢區這個窗口看不到。寫「無壓力位」會讓人以為頭上淨空，
    所以改成明講判斷範圍。
    """
    return f"{r}" if r is not None else "近60日創高（更早的套牢區未納入）"


def fmt_support(price):
    """支撐顯示。近期支撐全跌破時要講清楚，否則只看到一個數字會誤以為還撐得住。"""
    s = price.get("support")
    if price.get("broke_support"):
        return f"{s}（已跌破近期支撐）"
    return f"{s}"


def build_position_desc(price):
    """
    描述「這根K棒站在什麼位置」，讓突破、追高、無量漲停能被區分開來。
    只陳述事實，不下買賣結論。
    """
    parts = []
    close = price.get("close")
    h20, h60 = price.get("high_20d"), price.get("high_60d")
    ma20 = price.get("ma20")
    vol_ratio = price.get("vol_ratio")
    up_streak = price.get("up_streak", 0)
    pos = price.get("pos_vs_60d_high")

    # 位階
    if h60 and close >= h60:
        parts.append("・突破近60日高點（創季線以來新高）")
    elif h20 and close >= h20:
        parts.append("・突破近20日高點")
    elif pos is not None:
        parts.append(f"・距近60日高點 {pos:+.1f}%")

    # 與均線關係
    if ma20 and close:
        diff = (close - ma20) / ma20 * 100
        if diff >= 15:
            parts.append(f"・站上20日均線 {diff:+.1f}%，乖離偏大")
        else:
            parts.append(f"・20日均線 {ma20}（{diff:+.1f}%）")

    # 量能相對自己過去的水準
    if vol_ratio:
        if vol_ratio >= 3:
            parts.append(f"・量能為20日均量的 {vol_ratio} 倍，爆量")
        elif vol_ratio >= 1.5:
            parts.append(f"・量能為20日均量的 {vol_ratio} 倍，明顯放大")
        elif vol_ratio < 0.8:
            parts.append(f"・量能僅20日均量的 {vol_ratio} 倍，量縮")
        else:
            parts.append(f"・量能為20日均量的 {vol_ratio} 倍")

    # 連漲／連跌天數。注意 up_streak==0 是「今天沒漲」，不是「首根上漲」。
    down_streak = price.get("down_streak", 0)
    if up_streak >= 5:
        parts.append(f"・已連續上漲 {up_streak} 天")
    elif up_streak >= 2:
        parts.append(f"・連續上漲 {up_streak} 天")
    elif up_streak == 1:
        parts.append("・今日為近期首根上漲K棒")
    elif down_streak >= 5:
        parts.append(f"・已連續下跌 {down_streak} 天")
    elif down_streak >= 2:
        parts.append(f"・連續下跌 {down_streak} 天")
    elif down_streak == 1:
        parts.append("・今日翻黑，為近期首根下跌K棒")

    return "\n".join(parts) if parts else "・位階資料不足"


def build_technical_desc(pct, volume_lots, net_lots, turnover_billion=None):
    parts = []
    if pct >= 3:
        parts.append(f"・當日大漲 {pct:.2f}%，漲勢強勁")
    elif pct >= 1:
        parts.append(f"・當日上漲 {pct:.2f}%")
    elif pct <= -3:
        parts.append(f"・當日重挫 {pct:.2f}%，賣壓沉重")
    elif pct < 0:
        parts.append(f"・當日下跌 {pct:.2f}%")
    else:
        parts.append(f"・當日持平（{pct:+.2f}%）")

    if turnover_billion is None:
        parts.append(f"・成交量 {volume_lots:,} 張")
    elif turnover_billion >= 50:
        parts.append(f"・成交金額 {turnover_billion:.1f} 億（{volume_lots:,} 張），量能爆發")
    elif turnover_billion >= 15:
        parts.append(f"・成交金額 {turnover_billion:.1f} 億（{volume_lots:,} 張），量能明顯放大")
    else:
        parts.append(f"・成交金額 {turnover_billion:.1f} 億（{volume_lots:,} 張）")

    if net_lots > 0:
        parts.append(f"・三大法人合計買超 {net_lots:,} 張")
    elif net_lots < 0:
        parts.append(f"・三大法人合計賣超 {abs(net_lots):,} 張，籌碼面偏空")
    else:
        parts.append("・三大法人買賣持平")

    return "\n".join(parts)

def build_risk_desc(pct, net_lots):
    if net_lots < 0 and pct > 0:
        return "・法人籌碼與股價走勢背離（法人賣超但股價上漲），須留意隔日反轉風險"
    if pct >= 5:
        return "・短線漲幅已大，乖離率偏高，慎防獲利了結賣壓"
    if net_lots > 0 and pct > 0:
        return "・籌碼與價格同步走強，仍須留意大盤系統性風險"
    return "・盤勢仍有變數，操作務必自行設好停損停利"

def fetch_quote(symbol):
    """抓單一標的最新收盤與漲跌。回傳 (價格, 漲跌幅%, 漲跌絕對值) 或 None。"""
    try:
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}?range=5d&interval=1d"
        res = requests.get(url, timeout=8, headers={'User-Agent': 'Mozilla/5.0'}).json()
        result = res.get('chart', {}).get('result', [])
        if not result:
            return None
        meta = result[0].get('meta', {})
        close = meta.get('regularMarketPrice')
        closes = [c for c in (result[0].get('indicators', {}).get('quote', [{}])[0]
                              .get('close', []) or []) if c is not None]
        if not close and closes:
            close = closes[-1]
        if not close:
            return None
        # 前一交易日收盤：從尾端往回找第一筆「跟現價不同」的收盤。
        # Yahoo 的日K陣列尾端偶爾會出現重複的收盤價（同一天被塞兩筆），
        # 若死抓倒數第二筆就會拿到跟現價一樣的數字，算出假的 0.00%。
        prev = None
        for c in reversed(closes):
            if abs(c - close) > max(0.005, abs(close) * 1e-6):
                prev = c
                break
        if prev is None:
            prev = meta.get('chartPreviousClose')
        if not prev:
            return None
        # 順手記下這筆報價的日期。回傳值維持既有的三元組（很多地方在用），
        # 日期改放進模組層的小字典，需要的頁面自己去查。
        # 沒有日期的話，畫面只能寫「既有收盤資料」，
        # 使用者分不出那是昨天的還是前天的——實際發生過。
        try:
            stamp = meta.get('regularMarketTime')
            if stamp:
                _QUOTE_DATES[symbol] = datetime.fromtimestamp(
                    int(stamp), timezone(timedelta(hours=-4))).strftime("%m/%d")
        except (TypeError, ValueError, OSError):
            pass
        return close, (close - prev) / prev * 100, close - prev
    except Exception as e:
        print(f"❌ 抓取 {symbol} 失敗: {e}")
        return None


# 今日已成功取得過官方盤中報價的標的。
#
# MIS 是逐檔回報，同一分鐘內不同次請求拿到的標的可能不一樣。
# 沒拿到的會退回 Yahoo 日線（那是昨收），於是同一檔在畫面上
# 一下有今日漲跌、一下變昨天的——實測同一分鐘兩次載入，
# 首頁正貢獻從 4 檔變 2 檔，旺矽、緯穎、禾伸堂整批消失。
#
# 這裡記住「今天已經拿到過的最後有效報價」，之後 MIS 暫缺時沿用它，
# 而不是倒退回昨收。日期換了就整批清空，不會把昨天的沿用到今天。
_STICKY_QUOTE_LOCK = threading.Lock()
_STICKY_QUOTES = {}
_STICKY_QUOTE_DAY = {"day": None}


def _sticky_quote_get(code):
    """取回今天已記住的報價；跨日會自動失效。"""
    today = taiwan_today().isoformat()
    with _STICKY_QUOTE_LOCK:
        if _STICKY_QUOTE_DAY["day"] != today:
            return None
        return _STICKY_QUOTES.get(str(code).strip())


def _sticky_quote_put(code, close, updated_at, source):
    """
    記下今天的有效收盤價。日期一換就先清空，避免沿用昨天的數字。

    只存收盤價不存漲跌幅：漲跌幅要拿當下的昨收去算，
    存起來之後若昨收基準有調整（例如除權），沿用舊的 pct 就會錯。
    """
    today = taiwan_today().isoformat()
    with _STICKY_QUOTE_LOCK:
        if _STICKY_QUOTE_DAY["day"] != today:
            _STICKY_QUOTES.clear()
            _STICKY_QUOTE_DAY["day"] = today
        _STICKY_QUOTES[str(code).strip()] = {
            "close": close, "updated_at": updated_at, "source": source,
        }


# 各代號最近一次取得報價的日期（美東時間），供畫面標示資料日。
# 只是顯示用的輔助資料，抓不到就不標，不影響任何計算。
_QUOTE_DATES = {}

# 盤前簡報要看的標的。想增減直接改這裡，格式是 (顯示名稱, Yahoo代號)
BRIEF_INDICES = [
    ("道瓊", "^DJI"), ("那斯達克", "^IXIC"),
    ("S&P 500", "^GSPC"), ("費城半導體", "^SOX"),
]
BRIEF_MACRO = [
    ("美10年債殖利率", "^TNX"), ("VIX 恐慌指數", "^VIX"),
    ("美元指數", "DX-Y.NYB"), ("布蘭特原油", "BZ=F"),
]
BRIEF_STOCKS = [
    ("輝達 NVDA", "NVDA"), ("博通 AVGO", "AVGO"), ("超微 AMD", "AMD"),
    ("美光 MU", "MU"), ("Lumentum LITE", "LITE"), ("台積電ADR", "TSM"),
]


def fetch_quotes_bulk(symbols, workers=12):
    """並行抓多個 Yahoo 代號的報價，回傳 {symbol: (價格, 漲跌幅%, 漲跌值) 或 None}。"""
    symbols = list(dict.fromkeys(s for s in symbols if s))
    if not symbols:
        return {}

    def safe(s):
        try:
            return fetch_quote(s)
        except Exception as e:
            print(f"⚠️ 並行抓取報價失敗 {s}: {e}")
            return None

    with ThreadPoolExecutor(max_workers=min(workers, len(symbols))) as ex:
        return dict(zip(symbols, ex.map(safe, symbols)))


def generate_morning_brief():
    """
    盤前總經簡報：美股指數、殖利率與波動率、台廠相關重要個股、總經新聞標題。
    數據全部來自實際報價；CPI／非農這類發布結果與解讀不自行生成，
    改列新聞標題與連結，由你自己判讀。
    """
    lines = [f"☀️ 盤前總經簡報　{taiwan_now().strftime('%m/%d')}", "═" * 13]

    # 十幾個代號一次並行抓完，取代原本一個一個等的做法
    all_syms = ([s for _l, s in BRIEF_INDICES] + [s for _l, s in BRIEF_MACRO]
                + [s for _l, s in BRIEF_STOCKS] + ["^TNX"])
    quotes = fetch_quotes_bulk(all_syms)

    def fmt_rows(title, targets, as_yield=False):
        block = [f"\n【{title}】"]
        got = False
        for label, sym in targets:
            q = quotes.get(sym)
            if not q:
                continue
            got = True
            close, pct, diff = q
            arrow = "⚪" if abs(pct) < 0.005 else ("🔴" if pct > 0 else "🟢")
            if as_yield:
                # 殖利率用「基點」表達比百分比變化直觀（升息循環常用語言）
                block.append(f"{arrow} {label}：{close:.3f}%（{diff*100:+.1f} bps）")
            else:
                block.append(f"{arrow} {label}：{close:,.2f}（{pct:+.2f}%）")
        return block if got else [f"\n【{title}】\n資料暫缺"]

    lines += fmt_rows("美股指數", BRIEF_INDICES)

    # 殖利率與 VIX 分開處理：^TNX 是殖利率本身，用 bps 表示變化才有意義
    lines.append("\n【債市與風險指標】")
    tnx = quotes.get("^TNX")
    if tnx:
        close, pct, diff = tnx
        arrow = "⚪" if abs(diff) < 0.0005 else ("🔴" if diff > 0 else "🟢")
        lines.append(f"{arrow} 美10年債殖利率：{close:.3f}%（{diff*100:+.1f} bps）")
    for label, sym in BRIEF_MACRO[1:]:
        q = quotes.get(sym)
        if not q:
            continue
        close, pct, _diff = q
        arrow = "⚪" if abs(pct) < 0.005 else ("🔴" if pct > 0 else "🟢")
        lines.append(f"{arrow} {label}：{close:,.2f}（{pct:+.2f}%）")

    lines += fmt_rows("重點個股", BRIEF_STOCKS)

    # 總經新聞：只給標題與連結，不生成解讀
    news = fetch_stock_news("CPI OR 非農 OR 聯準會 OR 美債殖利率", max_items=3, within_hours=36)
    if news:
        lines.append("\n【總經焦點】")
        for n in news:
            src = f"（{n['source']}）" if n["source"] else ""
            lines.append(f"・{n['title']}{src}")
            if n["link"]:
                lines.append(f"　{n['link']}")

    lines.append("\n═" * 1)
    lines.append("※ 為前一交易日收盤數據")
    brief = "\n".join(lines)
    return brief[:4750] + "\n…（已截斷）" if len(brief) > 4800 else brief


# --- 月營收（TWSE OpenAPI t187ap05_L，全上市公司；TPEx 補上櫃／興櫃） ---
_revenue_cache = {"period": None, "data": {}, "checked_at": 0,
                  "source": "none", "source_date": None}
_REVENUE_REFRESH_LOCK = threading.Lock()
REVENUE_CACHE_CHECK_SECONDS = 600


def _normalize_revenue_period(raw):
    """把月營收的民國年月轉成可比較的 YYYYMM 整數。

    官方常見格式是 11508；也容忍 115/08、115-08、202608 等格式。
    回傳 None 表示資料年月欄位異常，絕不把異常值當成有效月份。
    """
    t = str(raw or "").strip().replace("/", "").replace("-", "")
    if len(t) == 5 and t.isdigit():
        y, m = int(t[:3]), int(t[3:])
        if 1 <= m <= 12:
            return (y + 1911) * 100 + m
    if len(t) == 6 and t.isdigit():
        y, m = int(t[:4]), int(t[4:])
        if 2000 <= y <= 2100 and 1 <= m <= 12:
            return y * 100 + m
    return None


def _revenue_period_label(period):
    key = _normalize_revenue_period(period)
    return f"{key // 100:04d}-{key % 100:02d}" if key else str(period or "")


def _load_latest_revenue_history():
    """讀取資料庫已保存的最新月營收快照，不把資料庫內容冒充成今日更新。"""
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("""
            SELECT r.code, r.period, r.yoy_pct, r.cum_yoy_pct,
                   r.mom_pct, r.month_revenue
            FROM revenue_history r
            JOIN (SELECT MAX(period) AS latest_period FROM revenue_history) p
              ON r.period = p.latest_period
            ORDER BY r.code
        """)
        rows = cursor.fetchall()
        cursor.close()
    except Exception as exc:
        print(f"⚠️ 讀取最新月營收歷史快照失敗: {exc}")
        return {}, None
    finally:
        release_db_connection(conn)

    if not rows:
        return {}, None
    period = str(rows[0][1]) if rows[0][1] is not None else None
    data = {
        row[0]: {
            "yoy_pct": row[2],
            "cum_yoy_pct": row[3],
            "mom_pct": row[4],
            "month_revenue": row[5],
        }
        for row in rows
    }
    return data, period



class _RevenueHTMLTableParser(HTMLParser):
    """輕量解析 MOPS 月營收歷史 HTML；不依賴 pandas/lxml。"""
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._row = None
        self._cell = None
        self._in_cell = False

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == "tr":
            self._row = []
        elif tag in ("td", "th") and self._row is not None:
            self._cell = []
            self._in_cell = True

    def handle_data(self, data):
        if self._in_cell and self._cell is not None:
            self._cell.append(data)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ("td", "th") and self._in_cell and self._row is not None:
            text = re.sub(r"\s+", " ", "".join(self._cell)).strip()
            self._row.append(text)
            self._cell = None
            self._in_cell = False
        elif tag == "tr" and self._row is not None:
            if any(str(x).strip() for x in self._row):
                self.rows.append(self._row)
            self._row = None


def _parse_mops_revenue_html(text, target_period):
    """解析 MOPS t21sc03 月營收表，回傳與 OpenAPI 相同的資料結構。"""
    parser = _RevenueHTMLTableParser()
    try:
        parser.feed(text or "")
        parser.close()
    except Exception as exc:
        print(f"⚠️ MOPS 月營收 HTML 解析失敗: {exc}")
        return {}

    def norm(s):
        return re.sub(r"\s+", "", str(s or "")).replace("\u3000", "")

    def number(v):
        t = str(v or "").strip().replace(",", "").replace("%", "")
        if t in ("", "-", "--", "—", "－", "N/A", "NA"):
            return None
        # HTML 可能出現括號負數
        if t.startswith("(") and t.endswith(")"):
            t = "-" + t[1:-1]
        try:
            return float(t)
        except (ValueError, TypeError):
            return None

    result = {}
    target_label = _revenue_period_label(target_period)

    for row in parser.rows:
        cells = [str(x).strip() for x in row]
        nc = [norm(x) for x in cells]
        if len(cells) < 7:
            continue
        if not any("公司代號" in x for x in nc):
            continue
        if not any("當月營收" in x or "營業收入" in x for x in nc):
            continue

        # 這個頁面的欄位是固定且公開的；優先依標題找欄位，找不到才用標準順序。
        def find_col(*keywords):
            for i, x in enumerate(nc):
                if all(k in x for k in keywords):
                    return i
            return None

        code_i = find_col("公司代號")
        month_i = find_col("當月營收")
        yoy_i = find_col("去年同月增減")
        cum_i = find_col("累計營收")
        cum_yoy_i = find_col("累計營收增減")
        mom_i = find_col("前月比較增減")

        # 若標題列因 rowspan/colspan 被拆成多列，使用 MOPS 標準欄位順序。
        if code_i is None:
            code_i = 0
        if month_i is None:
            month_i = 2
        if yoy_i is None:
            yoy_i = 3
        if cum_i is None:
            cum_i = 4
        if cum_yoy_i is None:
            cum_yoy_i = 5
        if mom_i is None:
            mom_i = 6

        header_positions = (code_i, month_i, yoy_i, cum_i, cum_yoy_i, mom_i)
        if max(header_positions) >= len(cells):
            continue

        # 找到標題後，往後掃描同一 HTML 的資料列。
        header_pos = parser.rows.index(row)
        for data_row in parser.rows[header_pos + 1:]:
            vals = [str(x).strip() for x in data_row]
            if len(vals) <= max(header_positions):
                continue
            code = re.sub(r"\s+", "", vals[code_i])
            # MOPS 可能有「合計」或分類列，不要塞進個股資料。
            if not re.fullmatch(r"\d{4,6}[A-Za-z]?", code):
                continue
            if code in ("合計", "總計"):
                continue
            result[code] = {
                "yoy_pct": number(vals[yoy_i]),
                "cum_yoy_pct": number(vals[cum_yoy_i]),
                "mom_pct": number(vals[mom_i]),
                "month_revenue": number(vals[month_i]),
            }
        if result:
            break

    if result:
        print(f"✅ MOPS {target_label} 歷史月營收解析成功，共 {len(result)} 檔")
    return result


def _parse_mops_revenue_csv(raw, target_period, target_code=None):
    """快速解析 MOPS 官方 CSV；可只取單一股票，避免 HTML 全表解析。"""
    import csv
    key = _normalize_revenue_period(target_period)
    target = str(target_code or "").strip()
    if not raw:
        return {}
    text = None
    for enc in ("utf-8-sig", "utf-8", "cp950", "big5"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    if text is None:
        text = raw.decode("utf-8", errors="replace")

    lines = [ln for ln in text.replace("\r", "").split("\n") if ln.strip()]
    if not lines:
        return {}
    try:
        rows = list(csv.reader(lines))
    except Exception:
        return {}
    if not rows:
        return {}

    header_i = None
    for i, row in enumerate(rows[:20]):
        joined = "|".join(str(x or "").replace("\ufeff", "").strip() for x in row)
        if "公司代號" in joined and ("當月營收" in joined or "營業收入" in joined):
            header_i = i
            break
    if header_i is None:
        return {}

    header = [re.sub(r"\s+", "", str(x or "").replace("\ufeff", "")) for x in rows[header_i]]
    def col(*keys):
        for i, h in enumerate(header):
            if all(k in h for k in keys):
                return i
        return None
    code_i = col("公司代號")
    month_i = col("當月營收")
    yoy_i = col("去年同月增減")
    cum_yoy_i = col("累計營收增減")
    mom_i = col("前月比較增減")
    # CSV 欄位順序可能調整；尤其「累計營收增減」不能硬猜成第 6 欄。
    code_i = 0 if code_i is None else code_i
    month_i = 2 if month_i is None else month_i
    yoy_i = 3 if yoy_i is None else yoy_i
    if cum_yoy_i is None:
        # 常見新版格式的累計 YoY 百分比通常在含「累計＋增減／比較」的欄位。
        candidates = [i for i, h in enumerate(header)
                      if "累計" in h and any(x in h for x in ("增減", "比較", "%", "百分"))]
        cum_yoy_i = candidates[-1] if candidates else None
    if mom_i is None:
        candidates = [i for i, h in enumerate(header)
                      if "前月比較" in h or ("上月比較" in h and "%" in h)]
        mom_i = candidates[-1] if candidates else None

    def num(v):
        t = str(v or "").strip().replace(",", "").replace("%", "")
        if t in ("", "-", "--", "—", "－", "N/A", "NA"):
            return None
        if t.startswith("(") and t.endswith(")"):
            t = "-" + t[1:-1]
        try:
            return float(t)
        except (ValueError, TypeError):
            return None

    result = {}
    for row in rows[header_i + 1:]:
        required_indices = [i for i in (code_i, month_i, yoy_i, cum_yoy_i, mom_i) if i is not None]
        if required_indices and max(required_indices) >= len(row):
            continue
        code = re.sub(r"\s+", "", str(row[code_i] or ""))
        if not re.fullmatch(r"\d{4,6}[A-Za-z]?", code):
            continue
        if target and code.rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ") != target.rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ"):
            continue
        cum_value = num(row[cum_yoy_i]) if cum_yoy_i is not None and cum_yoy_i < len(row) else None
        # 若沒有累計 YoY 百分比欄，嘗試從「今年累計／去年累計」兩欄計算。
        if cum_value is None:
            cur_i = next((i for i, h in enumerate(header)
                          if "累計" in h and "營收" in h and not any(x in h for x in ("去年", "前期", "增減", "比較", "%", "百分"))), None)
            prev_i = next((i for i, h in enumerate(header)
                           if "累計" in h and ("去年" in h or "前期" in h) and not any(x in h for x in ("增減", "比較", "%", "百分"))), None)
            if cur_i is not None and prev_i is not None and cur_i < len(row) and prev_i < len(row):
                cur_v, prev_v = num(row[cur_i]), num(row[prev_i])
                if cur_v is not None and prev_v not in (None, 0):
                    cum_value = (cur_v / prev_v - 1.0) * 100.0
        result[code] = {
            "yoy_pct": num(row[yoy_i]) if yoy_i is not None and yoy_i < len(row) else None,
            "cum_yoy_pct": cum_value,
            "mom_pct": num(row[mom_i]) if mom_i is not None and mom_i < len(row) else None,
            "month_revenue": num(row[month_i]) if month_i is not None and month_i < len(row) else None,
        }
        if target:
            break
    return result


def _fetch_mops_revenue_csv(target_key, target_code=None, market=None):
    """優先使用 MOPS 官方靜態 CSV。比 HTML 快很多，且單一股票可找到後立即停止。"""
    key = _normalize_revenue_period(target_key)
    if not key:
        return {}, None
    roc_year = key // 100 - 1911
    month = key % 100
    period_text = f"{roc_year:03d}{month:02d}"

    market_text = str(market or "").strip().lower()
    if market_text in ("上櫃", "上柜", "tpex", "otc", "two"):
        markets = [("上櫃", "otc")]
    elif market_text in ("上市", "twse", "sii", "tse", "tse.tw"):
        markets = [("上市", "sii")]
    elif market_text in ("興櫃", "rotc", "emerging"):
        markets = [("興櫃", "rotc")]
    else:
        markets = [("上市", "sii"), ("上櫃", "otc"), ("興櫃", "rotc")]

    for label, market_path in markets:
        url = (
            "https://mops.twse.com.tw/server-java/FileDownLoad"
            f"?step=9&functionName=show_file&filePath=%2Fhome%2Fhtml%2Fnas%2Ft21%2F{market_path}%2F"
            f"&fileName=t21sc03_{roc_year}_{month}.csv"
        )
        try:
            r = _session.get(url, timeout=8, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36",
                "Referer": "https://mops.twse.com.tw/",
            })
            r.raise_for_status()
            data = _parse_mops_revenue_csv(r.content, key, target_code=target_code)
            if data:
                print(f"⚡ MOPS CSV 月營收成功（{period_text}/{label}），{('單股 '+str(target_code)) if target_code else str(len(data))+' 檔'}")
                return data, period_text
        except Exception as exc:
            print(f"⚠️ MOPS CSV {label} {period_text} 失敗: {exc}")
    return {}, None


def _fetch_mops_revenue_fallback(target_key, target_code=None, market=None):
    """官方月營收歷史 fallback：先走快速 CSV，失敗才退回 HTML。"""
    fast, fast_period = _fetch_mops_revenue_csv(target_key, target_code=target_code, market=market)
    if fast:
        return fast, fast_period

    key = _normalize_revenue_period(target_key)
    if not key:
        return {}, None
    roc_year = key // 100 - 1911
    month = key % 100
    period_text = f"{roc_year:03d}{month:02d}"
    market_text = str(market or "").strip().lower()
    if market_text in ("上櫃", "上柜", "tpex", "otc", "two"):
        endpoints = [("上櫃", f"https://mopsov.twse.com.tw/nas/t21/otc/t21sc03_{roc_year}_{month}_0.html")]
    elif market_text in ("上市", "twse", "sii", "tse", "tse.tw"):
        endpoints = [("上市", f"https://mopsov.twse.com.tw/nas/t21/sii/t21sc03_{roc_year}_{month}_0.html")]
    elif market_text in ("興櫃", "rotc", "emerging"):
        endpoints = [("興櫃", f"https://mopsov.twse.com.tw/nas/t21/rotc/t21sc03_{roc_year}_{month}_0.html")]
    else:
        endpoints = [
            ("上市", f"https://mopsov.twse.com.tw/nas/t21/sii/t21sc03_{roc_year}_{month}_0.html"),
            ("上櫃", f"https://mopsov.twse.com.tw/nas/t21/otc/t21sc03_{roc_year}_{month}_0.html"),
            ("興櫃", f"https://mopsov.twse.com.tw/nas/t21/rotc/t21sc03_{roc_year}_{month}_0.html"),
        ]
    combined = {}
    for label, url in endpoints:
        try:
            r = _session.get(url, timeout=10, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36",
                "Referer": "https://mops.twse.com.tw/",
            })
            r.raise_for_status()
            raw = r.content
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                text = raw.decode("cp950", errors="replace")
            data = _parse_mops_revenue_html(text, key)
            if target_code:
                data = {k: v for k, v in data.items() if k.rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ") == str(target_code).rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ")}
            combined.update(data)
            if target_code and combined:
                break
        except Exception as exc:
            print(f"⚠️ MOPS HTML {label} {period_text} fallback 失敗: {exc}")
    if combined:
        print(f"🛟 MOPS HTML 月營收 fallback 成功（{period_text}），共 {len(combined)} 檔")
        return combined, period_text
    return {}, None

def fetch_monthly_revenue(force_refresh=False, homepage=False):
    """抓最新一期月營收，涵蓋上市、上櫃、興櫃。

    重要原則：
    1. 以「所有回傳列中最大的資料年月」判定最新月份，不能拿第一列當月份。
    2. 每月 1～15 日是新月份公布高峰，這段期間即使有舊快照也必須重新問官方。
    3. warmup 會用 force_refresh=True，避免 Render worker 的記憶體快取
       把「尚未公告的新月份」誤當成已公告。
    4. 若官方端點暫時失敗，保留舊資料；但不把舊資料的月份偽裝成新月份。
    """
    now = time.time()
    today = taiwan_today()
    release_window = today.day <= 15

    if (not force_refresh and _revenue_cache["data"] and
            now - _revenue_cache.get("checked_at", 0) < REVENUE_CACHE_CHECK_SECONDS):
        return _revenue_cache["data"]

    # 首頁同步渲染不能等待官方月營收 API。
    # 首頁只讀既有共享快照／歷史快照；官方最新月份由 warmup／背景流程更新。
    if homepage:
        shared = _load_shared_data_snapshot("monthly_revenue")
        shared_data = (shared.get("payload") if shared else None) or {}
        shared_period = ((shared.get("source_meta") or {}).get("period")
                         if shared else None)
        if isinstance(shared_data, dict) and shared_data and shared_period:
            _revenue_cache.update({
                "period": str(shared_period), "data": shared_data,
                "checked_at": now, "source": "shared",
                "source_date": shared.get("data_date"),
            })
            print("⚡ 首頁月營收只讀 Supabase 快照（月份 %s），共 %s 筆" %
                  (shared_period, len(shared_data)))
            return shared_data

        history_data, history_period = _load_latest_revenue_history()
        if history_data:
            _revenue_cache.update({
                "period": history_period, "data": history_data,
                "checked_at": now, "source": "history",
                "source_date": None,
            })
            print("⚡ 首頁月營收改讀歷史快照（月份 %s），共 %s 筆" %
                  (history_period or "未知月份", len(history_data)))
            return history_data

        print("⚠️ 首頁沒有可用月營收快照，跳過官方抓取，避免阻塞首頁")
        return {}

    # 非公布期可以使用共享快照；公布期必須先問官方，避免卡在上個月。
    if not force_refresh and not release_window and not _revenue_cache["data"]:
        shared = _load_shared_data_snapshot("monthly_revenue")
        shared_data = (shared.get("payload") if shared else None) or {}
        shared_period = ((shared.get("source_meta") or {}).get("period")
                         if shared else None)
        if isinstance(shared_data, dict) and shared_data and shared_period:
            _revenue_cache.update({
                "period": str(shared_period), "data": shared_data,
                "checked_at": now, "source": "shared",
                "source_date": shared.get("data_date"),
            })
            print("⚡ 月營收改讀 Supabase 快照（月份 %s），共 %s 筆" %
                  (shared_period, len(shared_data)))
            return shared_data

    # force_refresh 時不要相信記憶體裡可能殘留的「月份標籤」。
    # 例如舊快取可能寫著 11509，但 9 月其實尚未公告；這時必須以資料庫
    # 真正存在的最新歷史資料（例如 11508）作為 fallback，而不是讓錯誤月份
    # 標籤一路污染後面的累計營收修復／評分。
    fallback_data = {} if force_refresh else (_revenue_cache.get("data") or {})
    fallback_period = None if force_refresh else _revenue_cache.get("period")
    history_data, history_period = _load_latest_revenue_history()
    if history_data:
        if (not fallback_data or force_refresh or
                not _normalize_revenue_period(fallback_period)):
            fallback_data, fallback_period = history_data, history_period
            _revenue_cache["period"] = history_period
            _revenue_cache["data"] = history_data
            _revenue_cache["source"] = "history"
            _revenue_cache["source_date"] = None
            print("🔄 月營收以資料庫最新已公告月份（%s）作為 fallback，繼續檢查官方新月份" %
                  (history_period or "未知月份"))

    _revenue_cache["checked_at"] = now

    def to_float(v):
        try:
            return float(str(v).replace(",", ""))
        except (ValueError, TypeError):
            return None

    sources = [
        f"{TWSE_BASE}/opendata/t187ap05_L",   # 上市
        f"{TPEX_BASE}/mopsfin_t187ap05_O",    # 上櫃
        f"{TPEX_BASE}/t187ap05_R",            # 興櫃
    ]

    fetched = fetch_json_bulk(sources, timeout=20)

    source_rows = {}
    source_periods = {}
    for url in sources:
        rows = fetched.get(url)
        if not isinstance(rows, list) or not rows:
            continue

        # 不再使用 rows[0] 判斷月份；同一批資料若排序改變，舊寫法會 silent failure。
        periods = []
        for row in rows:
            per = _pick(row, "資料年月", "Period")
            key = _normalize_revenue_period(per)
            if key:
                periods.append(key)
        if periods:
            source_rows[url] = rows
            source_periods[url] = max(periods)

    if not source_periods:
        print("⚠️ 月營收官方端點本次沒有有效資料，沿用既有月份 %s" %
              (fallback_period or "未知"))
        return fallback_data

    latest_key = max(source_periods.values())
    latest_period = f"{latest_key // 100 - 1911:03d}{latest_key % 100:02d}"

    # 三個市場必須以同一個資料年月組合；若某市場還停在上月，寧可暫時缺資料，
    # 也不能把 7 月與 8 月混在同一份「最新營收」快照裡。
    result = {}
    included_sources = []
    for url, source_key in source_periods.items():
        if source_key != latest_key:
            print("⚠️ 月營收來源落後，暫不混入：%s=%s（最新=%s）" %
                  (url, _revenue_period_label(source_key), _revenue_period_label(latest_key)))
            continue
        included_sources.append(url)
        for row in source_rows.get(url, []):
            per = _pick(row, "資料年月", "Period")
            if _normalize_revenue_period(per) != latest_key:
                continue
            code = _pick(row, "公司代號", "SecuritiesCompanyCode", "Code")
            if not code:
                continue
            # 官方 OpenAPI 的欄位名稱曾出現不同版本；不能只鎖死單一欄位名。
            # 先做多版本 alias，再從同一列的累計營收／去年累計營收直接計算。
            def _row_value_by_keywords(keys, must_have=(), must_not=()):
                for k, v in row.items():
                    nk = re.sub(r"\s+", "", str(k or ""))
                    if not all(x in nk for x in must_have):
                        continue
                    if any(x in nk for x in must_not):
                        continue
                    if v not in (None, ""):
                        return v
                return ""

            yoy_raw = _pick(
                row,
                "營業收入-去年同月增減(%)",
                "營業收入-去年同月增減百分比",
                "營業收入去年同月增減(%)",
                "去年同月增減(%)",
            )
            cum_raw = _pick(
                row,
                "累計營業收入-前期比較增減(%)",
                "累計營業收入-前期比較增減百分比",
                "累計營業收入前期比較增減(%)",
                "累計營業收入前期比較增減",
                "累計營收-前期比較增減(%)",
                "累計營收前期比較增減(%)",
                "累計營收增減(%)",
            )
            # 最後再用關鍵字掃描，容忍官方欄名的小幅改名。
            if not cum_raw:
                cum_raw = _row_value_by_keywords(
                    row, must_have=("累計",),
                )
                # 上面的寬鬆搜尋可能找到「累計營業收入」金額，不是百分比；
                # 若找到數字過大，改找帶「增減／比較／%」的欄位。
                try:
                    if cum_raw and abs(float(str(cum_raw).replace(",", ""))) > 1000:
                        cum_raw = ""
                except Exception:
                    pass
            if not cum_raw:
                cum_raw = _row_value_by_keywords(
                    row, must_have=("累計",),
                )
                for k, v in row.items():
                    nk = re.sub(r"\s+", "", str(k or ""))
                    if "累計" in nk and any(x in nk for x in ("增減", "比較", "%", "百分")) and v not in (None, ""):
                        cum_raw = v
                        break

            month_raw = _pick(row, "營業收入-當月營收", "當月營收")
            mom_raw = _pick(row, "營業收入-上月比較增減(%)", "營業收入-上月比較增減百分比", "上月比較增減(%)")

            # 若 API 完全沒有累計 YoY，直接用官方同一列的「今年累計」與「去年累計」計算，
            # 絕不把單月 YoY 當成累計 YoY。
            if not cum_raw:
                cur_cum = _row_value_by_keywords(row, must_have=("累計", "營業收入"), must_not=("去年", "前期", "比較", "增減", "%", "百分"))
                prev_cum = _row_value_by_keywords(row, must_have=("累計",), must_not=("增減", "%", "百分"))
                # 優先挑含「去年／前期」的欄位作為去年累計。
                for k, v in row.items():
                    nk = re.sub(r"\s+", "", str(k or ""))
                    if "累計" in nk and ("去年" in nk or "前期" in nk) and "增減" not in nk and "%" not in nk and v not in (None, ""):
                        prev_cum = v
                        break
                try:
                    a = to_float(cur_cum); b = to_float(prev_cum)
                    if a is not None and b not in (None, 0):
                        cum_raw = (a / b - 1.0) * 100.0
                except Exception:
                    pass

            result[code] = {
                "yoy_pct": to_float(yoy_raw),
                "cum_yoy_pct": to_float(cum_raw),
                "mom_pct": to_float(mom_raw),
                "month_revenue": to_float(month_raw),
            }

    if not result or not included_sources:
        print("⚠️ 月營收官方端點本次沒有有效資料，沿用既有月份 %s" %
              (fallback_period or "未知"))
        return fallback_data

    # 8 月營收在 9 月公布期，若官方仍只回 7 月，不可以把它當成新資料。
    # 這裡只拒絕「明顯舊於上一個完整月份」的結果，不自行捏造 8 月數字。
    expected_key = (today.year * 100 + today.month) - 1
    if today.month == 1:
        expected_key = (today.year - 1) * 100 + 12
    if release_window and latest_key < expected_key:
        print("⚠️ 月營收官方 OpenAPI 仍停在 %s，預期至少 %s；啟動 MOPS 歷史頁 fallback" %
              (_revenue_period_label(latest_key), _revenue_period_label(expected_key)))
        mops_data, mops_period = _fetch_mops_revenue_fallback(expected_key)
        if mops_data:
            latest_period = mops_period
            result = mops_data
            print("✅ 已使用 MOPS 歷史頁取得 %s 月營收，取代舊的 %s 月快照" %
                  (_revenue_period_label(expected_key), _revenue_period_label(latest_key)))
        else:
            print("⚠️ MOPS 歷史頁也無法取得 %s，保留舊資料，不猜測新月份" %
                  _revenue_period_label(expected_key))
            return fallback_data

    _revenue_cache["period"] = latest_period
    _revenue_cache["data"] = result
    _revenue_cache["source"] = "mops_history" if _normalize_revenue_period(latest_period) != latest_key else "external"
    _revenue_cache["source_date"] = today
    _revenue_cache["checked_at"] = now
    print("✅ 月營收抓取成功（%s；各來源 %s），共 %s 檔" %
          (_revenue_period_label(latest_key),
           ", ".join(_revenue_period_label(v) for v in source_periods.values()),
           len(result)))
    save_revenue_history(latest_period, result)
    _save_shared_data_snapshot(
        "monthly_revenue", result, data_date=today,
        source_meta={"source": "TWSE+TPEx", "period": latest_period},
    )
    return result

def score_from_revenue_growth(yoy_pct):
    """依營收年增率評分，作為「有題材／獲利」的量化依據（0-50分）。"""
    if yoy_pct is None:
        return 0
    if yoy_pct >= 50:
        return 50
    if yoy_pct >= 30:
        return 40
    if yoy_pct >= 15:
        return 30
    if yoy_pct >= 5:
        return 20
    if yoy_pct > 0:
        return 10
    return 0

# --- 大盤指數（Yahoo 日K，固定回傳最新一個交易日收盤資訊） ---
# 今日首頁與盤前摘要都會用到大盤；短時間內重整不需要重複打外部 API。
_taiex_cache = {"at": 0, "data": None}
TAIEX_CACHE_SECONDS = 60

# 首頁盤中大盤不能拿日K或昨日快照假裝即時；獨立以 TWSE MIS 的 t00 指數短快取。
_taiex_intraday_cache = {"day": None, "at": 0, "data": None}
TAIEX_INTRADAY_CACHE_SECONDS = 15
TAIEX_INTRADAY_MAX_AGE_SECONDS = 180


def _taiex_live_number(value):
    try:
        raw = str(value or "").replace(",", "").strip()
        return None if raw in ("", "-", "--") else float(raw)
    except (TypeError, ValueError):
        return None


def fetch_taiex_intraday(force_refresh=False, now=None):
    """取得 TWSE MIS 官方盤中加權指數；只接受今日且三分鐘內的實際報價。

    盤中取得失敗時回傳 None，呼叫端必須顯示資料暫缺，不得降級成日K／昨日收盤。
    """
    current = now or taiwan_now()
    if not _is_taiwan_intraday_window(current):
        return None
    today = current.date().isoformat()
    epoch_now = time.time()
    with _realtime_cache_lock:
        cached = _taiex_intraday_cache.get("data")
        if (not force_refresh and _taiex_intraday_cache.get("day") == today and
                cached is not None and
                epoch_now - _taiex_intraday_cache.get("at", 0) < TAIEX_INTRADAY_CACHE_SECONDS):
            return cached
    try:
        response = requests.get(
            "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
            params={"ex_ch": "tse_t00.tw", "json": "1", "delay": "0",
                    "_": int(epoch_now * 1000)},
            headers={"User-Agent": "Mozilla/5.0", "Accept-Language": "zh-TW,zh;q=0.9"},
            timeout=6)
        response.raise_for_status()
        rows = response.json().get("msgArray") or []
        row = next((item for item in rows if isinstance(item, dict) and
                    str(item.get("c") or "").lower() == "t00"), None)
        if not row:
            raise ValueError("TWSE MIS 未回傳 t00 加權指數")
        expected = current.strftime("%Y%m%d")
        if str(row.get("d") or "") != expected:
            raise ValueError(f"TWSE MIS 資料日 {row.get('d')} 非今日 {expected}")
        close, previous = _taiex_live_number(row.get("z")), _taiex_live_number(row.get("y"))
        if close is None or close <= 0 or previous is None or previous <= 0:
            raise ValueError("TWSE MIS 即時指數或昨收缺失")
        quote_epoch = _taiex_live_number(row.get("tlong"))
        if quote_epoch is not None:
            quote_epoch /= 1000.0
            if abs(epoch_now - quote_epoch) > TAIEX_INTRADAY_MAX_AGE_SECONDS:
                raise ValueError("TWSE MIS 即時指數時間過舊")
        quote_time = str(row.get("t") or row.get("%") or "").strip()
        if not quote_time:
            raise ValueError("TWSE MIS 未回傳即時時間")
        diff = close - previous
        data = {
            "close": close, "previous_close": previous, "diff": diff,
            "pct": diff / previous * 100, "date": expected,
            "updated_at": f"{expected[:4]}-{expected[4:6]}-{expected[6:]} {quote_time}",
            "source": "TWSE MIS 即時加權指數", "is_intraday": True,
        }
        with _realtime_cache_lock:
            _taiex_intraday_cache.update({"day": today, "at": epoch_now, "data": data})
        return data
    except Exception as exc:
        print(f"⚠️ 抓取 TWSE MIS 即時 TAIEX 失敗：{exc}")
        with _realtime_cache_lock:
            _taiex_intraday_cache.update({"day": today, "at": epoch_now, "data": None})
        return None


def fetch_taiex_official_close(now=None):
    """取得 TWSE MIS 同日加權指數正式收盤；資料不完整時回傳 None，不降級冒充收盤。

    Yahoo 日K在集合競價後可能仍停在盤中最後一筆（例如 2026/08/27 回 45,969），
    不能與前一日正式收盤相除後標為當日收盤漲跌。收盤後優先以 TWSE MIS 的
    t00 z/y 與收盤時間為唯一首頁收盤口徑。
    """
    current = now or taiwan_now()
    if not _taiwan_post_close(current):
        return None
    expected = current.strftime("%Y%m%d")
    try:
        response = requests.get(
            "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
            params={"ex_ch": "tse_t00.tw", "json": "1", "delay": "0",
                    "_": int(time.time() * 1000)},
            headers={"User-Agent": "Mozilla/5.0", "Accept-Language": "zh-TW,zh;q=0.9"},
            timeout=6)
        response.raise_for_status()
        rows = response.json().get("msgArray") or []
        row = next((item for item in rows if isinstance(item, dict) and
                    str(item.get("c") or "").lower() == "t00"), None)
        if not row or str(row.get("d") or "") != expected:
            raise ValueError("TWSE MIS 未回傳同日 t00 收盤資料")
        close = _taiex_live_number(row.get("z"))
        previous = _taiex_live_number(row.get("y"))
        close_time = str(row.get("t") or "").strip()
        try:
            hour, minute = (int(part) for part in close_time.split(":")[:2])
        except (TypeError, ValueError):
            hour = minute = -1
        if (close is None or close <= 0 or previous is None or previous <= 0 or
                (hour, minute) < (13, 30)):
            raise ValueError("TWSE MIS 正式收盤價格、昨收或收盤時間缺失")
        diff = close - previous
        return {
            "close": f"{close:,.2f}",
            "sign": "+" if diff > 0 else ("-" if diff < 0 else ""),
            "pts": f"{abs(diff):,.2f}",
            "pct": f"{diff / previous * 100:+.2f}",
            "date": expected,
            "previous_close": f"{previous:,.2f}",
            "updated_at": f"{expected[:4]}-{expected[4:6]}-{expected[6:]} {close_time}",
            "source": "TWSE MIS 加權指數正式收盤",
            "close_is_final": True,
        }
    except Exception as exc:
        print(f"⚠️ 抓取 TWSE MIS 正式 TAIEX 收盤失敗：{exc}")
        return None


_taifex_night_cache = {"at": 0, "data": None}
TAIFEX_NIGHT_CACHE_SECONDS = 300


TAIFEX_NIGHT_URL = "https://www.taifex.com.tw/cht/3/futDailyMarketReport"
TAIFEX_NIGHT_MAX_AGE_DAYS = 3


def _latest_taifex_night_data_date(reference_date=None):
    """盤前可用的最新 TX 夜盤歸屬日；週一回推至前週五。"""
    day = reference_date if isinstance(reference_date, date) else taiwan_today()
    day -= timedelta(days=1)
    while day.weekday() >= 5:
        day -= timedelta(days=1)
    return day


def _taifex_number(value):
    """把 TAIFEX HTML／JSON 的數字字串轉成 float；箭頭與缺值視為格式，不是數字。"""
    if value in (None, "", "-", "NULL", "null"):
        return None
    try:
        text = str(value).replace(",", "").replace("%", "").replace("−", "-")
        text = re.sub(r"[^0-9+\-.]", "", text).strip()
        if not text or text in ("-", "+", "."):
            return None
        return float(text)
    except (TypeError, ValueError):
        return None


def _taifex_clean_html_text(value):
    text = html.unescape(str(value or ""))
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _taifex_expiration_date(year, month):
    """TAIFEX 月台指期的第三個星期三，用來排除資料日後仍殘留的到期月。"""
    first = date(year, month, 1)
    days_to_wednesday = (2 - first.weekday()) % 7
    return first + timedelta(days=days_to_wednesday + 14)


def _taifex_month_is_expired(month_text, data_date):
    if not re.fullmatch(r"\d{6}", str(month_text or "")):
        return True
    try:
        year, month = int(month_text[:4]), int(month_text[4:6])
        month_date = date(year, month, 1)
        data_month = date(data_date.year, data_date.month, 1)
        if month_date < data_month:
            return True
        if month_date == data_month and data_date >= _taifex_expiration_date(year, month):
            return True
        return False
    except (TypeError, ValueError):
        return True


def _parse_taifex_night_html(page_text):
    """解析官方 futDailyMarketReport 的 TX 盤後主表，回傳候選列與資料日。"""
    heading = re.search(
        r"(\d{4}/\d{1,2}/\d{1,2})(?:\s|&nbsp;|&#160;)+15:00~次日05:00\s*盤後交易時段行情表",
        page_text or "", flags=re.IGNORECASE)
    if not heading:
        return None
    try:
        data_date = date.fromisoformat(heading.group(1).replace("/", "-"))
    except ValueError:
        return None

    table_match = re.search(
        r"盤後交易時段行情表.*?<table\b[^>]*>(.*?)</table>",
        page_text or "", flags=re.IGNORECASE | re.DOTALL)
    if not table_match:
        return None
    rows = []
    for row_html in re.findall(r"<tr\b[^>]*>(.*?)</tr>", table_match.group(1),
                               flags=re.IGNORECASE | re.DOTALL):
        cells = [
            _taifex_clean_html_text(cell)
            for cell in re.findall(r"<td\b[^>]*>(.*?)</td>", row_html,
                                   flags=re.IGNORECASE | re.DOTALL)
        ]
        if len(cells) < 8:
            continue
        contract_month = cells[1].strip()
        # 只接受單一月份；202609/202610 等價差列不能冒充近月。
        if not re.fullmatch(r"\d{6}", contract_month):
            continue
        last = _taifex_number(cells[5])
        if last is None or _taifex_month_is_expired(contract_month, data_date):
            continue
        rows.append({
            "month": contract_month,
            "close": last,
            "diff": _taifex_number(cells[6]),
            "pct": _taifex_number(cells[7]),
        })
    if not rows:
        return None
    return {"data_date": data_date, "rows": rows}


def fetch_taifex_night_summary():
    """取得官方 TX 近月盤後資料；以夜盤歸屬日查詢，過舊或解析失敗不顯示舊值。"""
    now = time.time()
    today = taiwan_today()
    expected_data_date = _latest_taifex_night_data_date(today)
    with _realtime_cache_lock:
        cached = _taifex_night_cache.get("data")
        cached_date = None
        try:
            if isinstance(cached, dict) and cached.get("date"):
                cached_date = date.fromisoformat(str(cached["date"]).replace("/", "-")[:10])
        except (TypeError, ValueError):
            cached_date = None
        # 快取壽命仍未到，但資料日若落後最新可用交易日，必須立即重抓。
        if (cached is not None and cached_date == expected_data_date and
                now - _taifex_night_cache.get("at", 0) < TAIFEX_NIGHT_CACHE_SECONDS):
            return cached
    # 夜盤 15:00 至次日 05:00 的資料，官方要求以次日歸屬日期查詢。
    query_dates = [today + timedelta(days=1)] + [today - timedelta(days=offset) for offset in range(0, 8)]
    headers = {"User-Agent": "Mozilla/5.0", "Accept-Language": "zh-TW,zh;q=0.9"}
    request_errors = []
    for query_date in query_dates:
        try:
            params = {
                "queryDate": query_date.strftime("%Y/%m/%d"),
                "marketCode": "1",
                "MarketCode": "1",
                "commodity_id": "TX",
                "commodity_id2": "",
            }
            # 官方 futDailyMarketReport 的查詢表單是 POST；使用 GET 可能只回傳
            # 預設頁面，導致日期／夜盤資料沒有跟著 queryDate 更新。
            response = requests.post(TAIFEX_NIGHT_URL, data=params,
                                     headers=headers, timeout=15)
            response.raise_for_status()
            parsed = _parse_taifex_night_html(response.text)
            if not parsed:
                continue
            data_date = parsed["data_date"]
            # 盤前只接受最新可用交易日的夜盤；不能因三日容許快取把 8/24
            # 仍包裝成 8/26 的可用夜盤。週一的最新值仍可合理地是前週五。
            if data_date > today or data_date < expected_data_date:
                continue
            row = min(parsed["rows"], key=lambda item: item["month"])
            result = {
                "close": row["close"],
                "diff": row.get("diff"),
                "pct": row.get("pct"),
                "date": data_date.strftime("%Y/%m/%d"),
                "contract": f"TX {row['month']}",
                "source": "TAIFEX futDailyMarketReport（官方盤後歸屬日）",
            }
            with _realtime_cache_lock:
                _taifex_night_cache["at"] = time.time()
                _taifex_night_cache["data"] = result
            return result
        except Exception as exc:
            request_errors.append(f"{query_date.isoformat()}: {exc}")
            continue
    if request_errors:
        print(f"⚠️ 抓取台指期夜盤官方資料部分日期失敗，已繼續回退：{request_errors[-1]}")
    # 不使用過時 OpenAPI 或舊快照填補，以免再次顯示錯價。
    with _realtime_cache_lock:
        _taifex_night_cache["at"] = time.time()
        _taifex_night_cache["data"] = None
    return None


def fetch_taiex_summary():
    """
    抓加權指數。收盤後以 TWSE MIS t00 的同日正式收盤優先；其他時段才使用
    Yahoo 的日K序列（^TWII）提供最新可驗證交易日收盤資訊。

    Yahoo 日K有時間戳，適合辨識一般交易日資料日；但集合競價後若其日K尚未
    寫入正式收盤，則不能拿日K的盤中最後一筆與昨日正式收盤混算為今日收盤報酬。
    當日官方 MIS 收盤暫缺時回傳 None，呼叫端必須明示資料尚未確認。
    回傳 dict（含 date），失敗回傳 None。
    """
    current = taiwan_now()
    if _taiwan_post_close(current):
        official_close = fetch_taiex_official_close(current)
        if official_close is not None:
            with _realtime_cache_lock:
                _taiex_cache["at"] = time.time()
                _taiex_cache["data"] = official_close
            return official_close
        # 收盤後不可退回可能尚未反映市撮價的 Yahoo 日K；寧可顯示資料待確認。
        return None
    now = time.time()
    with _realtime_cache_lock:
        if _taiex_cache["data"] is not None and now - _taiex_cache["at"] < TAIEX_CACHE_SECONDS:
            return _taiex_cache["data"]
    try:
        url = ("https://query1.finance.yahoo.com/v8/finance/chart/%5ETWII"
               "?range=5d&interval=1d")
        res = requests.get(url, timeout=8,
                           headers={'User-Agent': 'Mozilla/5.0'}).json()
        result = res.get("chart", {}).get("result", [])
        if not result:
            return None
        meta = result[0].get("meta", {})
        ts = result[0].get("timestamp", []) or []
        raw_closes = (result[0].get("indicators", {})
                      .get("quote", [{}])[0].get("close", []) or [])
        # 不能混用 meta.regularMarketPrice 與日K close：Yahoo 的 meta 行情有時仍
        # 停在前一筆，但日K已更新；混用會讓首頁在實際上漲日顯示前一日跌幅。
        bars = [(ts[idx] if idx < len(ts) else None, close)
                for idx, close in enumerate(raw_closes) if close is not None]
        if len(bars) < 2:
            return None
        tw_tz = timezone(timedelta(hours=8))
        last_ts, close = bars[-1]
        _previous_ts, prev = bars[-2]
        if not prev:
            return None
        bar_date = (datetime.fromtimestamp(last_ts, tw_tz).strftime("%Y%m%d")
                    if last_ts else None)
        diff = float(close) - float(prev)
        result = {
            "close": f"{float(close):,.2f}",
            "sign": "+" if diff > 0 else ("-" if diff < 0 else ""),
            "pts": f"{abs(diff):,.2f}",
            "pct": f"{diff / float(prev) * 100:+.2f}",
            "date": bar_date,
            "previous_close": f"{float(prev):,.2f}",
            "source": "Yahoo ^TWII 日K最後兩筆收盤",
            "close_is_final": False,
        }
        with _realtime_cache_lock:
            _taiex_cache["at"] = time.time()
            _taiex_cache["data"] = result
        return result
    except Exception as e:
        print(f"❌ 抓取大盤指數錯誤: {e}")
        return None


def _market_date_matches(value, expected_date):
    """首頁只接受資料日等於顯示交易日的大盤數值，避免舊快照冒充今日。"""
    if not value or not expected_date:
        return False
    try:
        parsed = date.fromisoformat(str(value).replace("/", "-")[:10])
    except ValueError:
        digits = re.sub(r"\D", "", str(value))
        if len(digits) != 8:
            return False
        try:
            parsed = datetime.strptime(digits, "%Y%m%d").date()
        except ValueError:
            return False
    return parsed == expected_date


# --- 三大法人合計買賣超金額（跟 T86 同體系的 rwd JSON API） ---
def fetch_institutional_total():
    try:
        url = "https://www.twse.com.tw/rwd/zh/fund/BFI82U"
        res = requests.get(url, params={"response": "json"}, timeout=10, headers={'User-Agent': 'Mozilla/5.0'}).json()
        if res.get("stat") != "OK":
            return None

        fields = res.get("fields", [])
        rows = res.get("data", [])

        def col(name, default=None):
            return fields.index(name) if name in fields else default

        name_i = col("單位名稱")
        buy_i = col("買進金額")
        sell_i = col("賣出金額")
        net_i = col("買賣差額")

        def to_int(s):
            try:
                return int(str(s).replace(",", ""))
            except (ValueError, TypeError):
                return None

        breakdown = {}
        total_net = None
        for row in rows:
            if name_i is None:
                continue
            name = row[name_i].strip()
            net_val = to_int(row[net_i]) if net_i is not None else None
            if net_val is None and buy_i is not None and sell_i is not None:
                b, s = to_int(row[buy_i]), to_int(row[sell_i])
                net_val = (b - s) if (b is not None and s is not None) else None
            if net_val is None:
                continue

            # 證交所回傳的資料本身就內含一列「合計」，直接採用它，
            # 不能把它跟其他列一起加總，否則總額會被重複計算一次。
            if "合計" in name:
                total_net = net_val
                continue

            breakdown[name] = net_val

        if not breakdown:
            return None

        # 萬一某天沒有「合計」列，才自行加總各單位
        if total_net is None:
            total_net = sum(breakdown.values())
        return {"total": total_net, "breakdown": breakdown}
    except Exception as e:
        print(f"❌ 抓取法人合計金額錯誤: {e}")
        return None

# --- 盤後解盤：使用者手動輸入關鍵字才觸發，不自動推播 ---
def build_market_recap():
    inst_data = fetch_institutional_data()
    if not inst_data:
        return "❌ 目前無法取得盤後資料，可能是非交易日或資料尚未公布，請稍後再試。"

    # 一定要標資料日期。沒有日期的話，非交易日或資料還沒公布時
    # 看到的是上一個交易日的數字，但畫面長得跟今天的一模一樣，
    # 使用者只會覺得「怎麼沒更新」而不知道原因。
    tw_today = taiwan_now().strftime("%m/%d")
    inst_dd = format_data_date(_t86_cache.get("data_date"))

    taiex = fetch_taiex_summary()
    taiex_dd = format_data_date(taiex.get("date")) if taiex else None

    lines = ["📊 盤後解盤"]

    # 大盤與法人來自不同資料源，發布時間不同步——各自標日期，
    # 不要用一個日期涵蓋整份報告。兩者同一天時才合併成一行寫。
    if taiex and taiex.get("close"):
        arrow = ("▲" if taiex.get("sign") == "+"
                 else ("▼" if taiex.get("sign") == "-" else "－"))
        tag = "" if taiex_dd == inst_dd else f"　{taiex_dd}"
        lines.append(f"─" * 14)
        lines.append(f"大盤 {taiex['close']}　{arrow}{taiex.get('pts','?')}"
                     f"（{taiex.get('pct','?')}%）{tag}")
    else:
        lines.append("─" * 14)
        lines.append("大盤：資料暫缺")

    if taiex_dd and taiex_dd == inst_dd:
        lines[0] = f"📊 盤後解盤　{inst_dd} 收盤"
    else:
        lines[0] = f"📊 盤後解盤"
        lines.insert(1, f"法人 {inst_dd}"
                        + (f"　大盤 {taiex_dd}" if taiex_dd else ""))

    stale = "" if inst_dd == tw_today else f"（法人非今日；今天是 {tw_today}）"
    if stale:
        lines.insert(1, stale)

    inst_total = fetch_institutional_total()
    if inst_total:
        total_yi = inst_total["total"] / 100_000_000
        lines.append(f"三大法人合計：{total_yi:+.1f}億")
        for name, val in inst_total["breakdown"].items():
            # 名稱裡的半形括號會讓「(2886) +22」這類樣式被當成電話號碼，
            # 這裡雖然沒有數字相鄰，仍統一成全形以免日後改動時踩到
            nm = name.replace("(", "（").replace(")", "）")
            lines.append(f"　{nm}　{val/100_000_000:+.1f}億")
    lines.append("─" * 14)

    stock_rows = [
        (code, info) for code, info in inst_data.items()
        if len(code) == 4 and code.isdigit()
        and not code.startswith("00")  # 排除 ETF
    ]
    buy_leaders = sorted(stock_rows, key=lambda x: x[1]["total_net_lots"], reverse=True)[:3]
    sell_leaders = sorted(stock_rows, key=lambda x: x[1]["total_net_lots"])[:3]

    lines.append("🟢 法人買超前3")
    for code, info in buy_leaders:
        lines.append(f"{info['name']}（{code}）+{info['total_net_lots']:,}張")

    lines.append("")
    lines.append("🔴 法人賣超前3")
    for code, info in sell_leaders:
        lines.append(f"{info['name']}（{code}）{info['total_net_lots']:,}張")

    if stale:
        lines += ["─" * 14,
                  "※ 今日資料尚未公布或非交易日，",
                  "　 以上為最近一個交易日的數字。",
                  "　 T86 約在收盤後陸續發布。"]
    return "\n".join(lines)


def build_market_recap_line_message(user_id, base_url=None):
    """LINE 盤後摘要：保留真實資料，改用分區卡片呈現並附網頁完整分析按鈕。"""
    recap_text = build_market_recap()
    web_url = _line_feature_web_url(user_id, "debrief", base_url)
    if not web_url:
        return TextSendMessage(text=recap_text)
    raw_lines = [line.rstrip() for line in recap_text.splitlines()]
    clean_lines = [line for line in raw_lines if line.strip("─").strip()]
    if clean_lines and clean_lines[0].startswith("📊"):
        clean_lines = clean_lines[1:]

    def find_line(prefix, start=0):
        return next((idx for idx in range(start, len(clean_lines))
                     if clean_lines[idx].startswith(prefix)), len(clean_lines))

    buy_idx = find_line("🟢")
    sell_idx = find_line("🔴", buy_idx)
    note_idx = find_line("※", sell_idx)
    top_lines = clean_lines[:buy_idx]
    buy_lines = clean_lines[buy_idx + 1:sell_idx] if buy_idx < len(clean_lines) else []
    sell_lines = clean_lines[sell_idx + 1:note_idx] if sell_idx < len(clean_lines) else []
    note_lines = clean_lines[note_idx:] if note_idx < len(clean_lines) else []

    def text_block(text, color="#454C55", size="sm", margin="none"):
        return {"type": "text", "text": text or "資料暫缺", "size": size,
                "color": color, "wrap": True, "margin": margin,
                "lineSpacing": "3px"}

    def recap_section(title, lines, color):
        if not lines:
            return None
        return {"type": "box", "layout": "vertical", "spacing": "xs",
                "margin": "md", "paddingAll": "12px", "cornerRadius": "10px",
                "backgroundColor": "#F9F9FB", "contents": [
                    {"type": "text", "text": title, "weight": "bold", "size": "sm",
                     "color": color},
                    text_block("\n".join(lines), margin="sm")
                ]}

    sections = []
    top_block = recap_section("收盤與法人資料", top_lines, "#6E5228")
    buy_block = recap_section("🟢 法人買超前 3", buy_lines, "#155C42")
    sell_block = recap_section("🔴 法人賣超前 3", sell_lines, "#A82A20")
    for block in (top_block, buy_block, sell_block):
        if block:
            sections.append(block)
    if note_lines:
        sections.append(text_block("\n".join(note_lines), color="#767D85", size="xs", margin="md"))

    bubble = {
        "type": "bubble",
        "body": {"type": "box", "layout": "vertical", "spacing": "none",
                 "paddingAll": "18px", "contents": [
            {"type": "text", "text": "📊 盤後收盤摘要", "weight": "bold",
             "size": "xl", "color": "#1B2027"},
            {"type": "text", "text": "資料依公開來源日期整理", "size": "xs",
             "color": "#767D85", "margin": "xs"},
            {"type": "separator", "margin": "md", "color": "#E8EAE6"},
            *sections,
            {"type": "separator", "margin": "lg", "color": "#E8EAE6"},
            {"type": "text", "text": "想看完整持股損益、今日判讀、走勢與風險分析，請開啟網頁版。",
             "size": "xs", "color": "#767D85", "wrap": True, "margin": "md"},
            {"type": "button", "style": "primary", "height": "sm",
             "color": "#6E5228", "margin": "md",
             "action": {"type": "uri", "label": "查看網頁版完整分析",
                        "uri": web_url}}
        ]},
        "styles": {"body": {"backgroundColor": "#FFFFFF"}}
    }
    return FlexSendMessage(alt_text=recap_text[:400], contents=bubble)


# --- 自選股健檢：用長線指標評估「這檔還健康嗎」，不是評估「今天漲不漲」 ---
def score_watchlist_chips(cum_lots, buy_days, streak):
    """
    籌碼分數（0-30）。看的是近10日法人的累計方向與持續性，
    不是單日買賣超——單日雜訊太大，隔天就翻臉的情況很常見。
    """
    if cum_lots > 0:
        base = min(20, 8 + cum_lots / 1500)  # 累計買超越多分數越高，20分封頂
        base += min(10, streak * 2)          # 連續買超再加成
        return round(min(30, base))
    if cum_lots == 0:
        return 12
    # 累計賣超，依賣超幅度扣分
    return max(0, round(10 + cum_lots / 3000))


def score_watchlist_position(price):
    """
    位階分數（0-20）。股價相對近期高點與均線的位置。
    高檔乖離大不代表不好，但持有時該知道自己站在哪。
    """
    score = 0
    close = price.get("close")
    pos = price.get("pos_vs_60d_high")
    ma20 = price.get("ma20")

    # 距離季線高點的位置：貼近高點代表趨勢強，但過度乖離要留意
    if pos is not None:
        if pos >= 0:
            score += 15   # 創新高，趨勢最強
        elif pos >= -8:
            score += 13
        elif pos >= -20:
            score += 9
        elif pos >= -35:
            score += 5
        else:
            score += 2    # 距高點超過35%，明顯轉弱
    else:
        score += 7

    # 站上或跌破20日均線
    if ma20 and close:
        diff = (close - ma20) / ma20 * 100
        if diff >= 20:
            # 乖離過大不直接扣分，也不再因「站得更遠」額外加分。
            # 追高風險改以獨立提示呈現，避免高分系統反而鼓勵追價。
            score += 10   # 與一般站穩均線之上同級
        elif diff >= 0:
            score += 10   # 站穩均線之上
        elif diff >= -8:
            score += 5
        else:
            score += 1    # 跌破均線且距離拉開
    else:
        score += 5

        # 位階只反映價格結構，不讓接近高點本身過度推高健康分。
    return min(20, round(score * 20 / 25))

def build_watchlist_advice(total, chip_score, pos_score, rev_score, val_score,
                           cum_lots, streak, price, cum_yoy, pe):
    """
    把四個面向的訊號合成一句可操作的觀察。
    規則式，不是預測——講的是「現在這組數字代表什麼、該注意什麼」。
    """
    close = price.get("close")
    ma20 = price.get("ma20")
    pos = price.get("pos_vs_60d_high")
    ma_diff = ((close - ma20) / ma20 * 100) if (ma20 and close) else None

    # 最優先：基本面惡化
    if cum_yoy is not None and cum_yoy < 0 and cum_lots < 0:
        return "⚠️ 營收衰退且法人同步出場，兩個面向一起轉弱，建議重新檢視持有理由"

    # 貴 + 弱：本益比偏高但股價已回落一段，通常代表市場在下修對它的成長預期。
    # 這個組合比「跌破月線」更有資訊量（它說明了為什麼弱），所以排在前面。
    #
    # 但不能只看 val_score 低就說「本益比偏高」——分數低有兩種原因：
    #   (a) 本益比真的高
    #   (b) 營收年增暴衝導致 PEG 失真，被降分示警（低基期效應）
    # 情況 (b) 的本益比可能只有 9 倍，硬說「偏高」是明顯錯誤的判讀。
    # 所以要拿實際的 PE 值把關，不是只信分數。
    expensive = pe is not None and pe >= 25
    if expensive and pos is not None and pos <= -20:
        if cum_lots < 0:
            return "🔻 本益比偏高但股價已回落一段，法人同步減碼，市場恐在重新評價其成長性"
        return "🤔 本益比偏高但股價已回落一段，市場可能在重新評價成長性，留意估值是否過去給太高"

    # 低本益比 × 高成長：多半是景氣循環股的獲利高點，或去年基期極低。
    # 這種組合看起來便宜，實際上最危險，值得單獨講一句。
    if (pe is not None and pe <= 15 and cum_yoy is not None and cum_yoy >= 80
            and pos is not None and pos <= -20):
        return ("⚠️ 本益比低但營收年增暴衝，多為低基期或獲利高點造成的失真；"
                "股價已回落一段，留意獲利能否延續")

    # 籌碼與趨勢同時轉弱
    if cum_lots < 0 and ma_diff is not None and ma_diff < 0:
        return "⚠️ 法人賣超且跌破月線，短線偏弱，若持有應設好停損位"

    if cum_lots < 0:
        return "🔻 法人近期站在賣方，但價格結構尚未破壞，可觀察是否只是短線調節"

    # 高乖離示警
    if ma_diff is not None and ma_diff >= 20:
        return "🔥 基本面與籌碼皆強，但短線乖離過大，此時進場成本偏高，等回測均線較穩"

    # 強勢且結構健康
    if total >= 70 and pos is not None and pos >= -8:
        return "✅ 籌碼、位階、基本面三方同向，趨勢完整，持有可續抱並以月線為防守"

    # 基本面好但還在低位（最值得留意的一種）
    if rev_score >= 18 and pos is not None and pos <= -20 and cum_lots > 0:
        return "💡 基本面佳但股價仍距高點一段，法人已在承接，屬落後補漲的觀察對象"

    if val_score <= 8 and rev_score >= 18:
        return "💰 成長性不錯但估值已偏貴，追價空間有限，等回檔較有利"

    if streak >= 3 and pos is not None and pos > -20:
        return "📈 法人持續買超且價格站在相對高位，趨勢延續中"

    if rev_score <= 10:
        return "📉 營收成長動能偏弱，基本面缺乏支撐，僅適合短線看待"

    return "😐 各面向訊號中性，暫無明顯方向，續觀察法人動向與月線支撐"



def _repair_missing_cumulative_revenue(codes, revenue_data, trace=None):
    """補修缺失的「累計營收年增率」。

    月營收快照可能有「當月 YoY」但 cum_yoy_pct 為 NULL；這不能直接把單月 YoY
    當成累計 YoY。這裡優先使用 DB 已保存的每月營收，必要時才向 MOPS 官方歷史頁
    補月份，最後用「今年 1 月至最新月」對「去年同期」的營收總額計算累計 YoY。
    只修使用者目前要求評分的股票，避免全市場一次打數百／數千次外部請求。
    """
    def _trace(stage, **data):
        if isinstance(trace, list):
            row = {"stage": stage}
            row.update(data)
            trace.append(row)

    if not isinstance(revenue_data, dict):
        _trace("invalid_revenue_data", type=type(revenue_data).__name__)
        return revenue_data or {}

    targets = []
    for code in codes or []:
        code = str(code).strip()
        info = revenue_data.get(code) or {}
        if info.get("cum_yoy_pct") is None:
            targets.append(code)
    if not targets:
        _trace("nothing_to_repair", codes=[str(c).strip() for c in (codes or [])])
        return revenue_data

    _trace("targets", targets=list(targets))

    # 最新完整月：先以目前月營收快照的 period 為準，沒有才退回今天的上個月。
    latest_key = _normalize_revenue_period(_revenue_cache.get("period"))
    if not latest_key:
        today = taiwan_today()
        y, m = today.year, today.month - 1
        if m == 0:
            y, m = y - 1, 12
        latest_key = y * 100 + m

    _trace("latest_period", latest_key=latest_key, cache_period=_revenue_cache.get("period"))

    def prev_month(key):
        y, m = divmod(int(key), 100)
        m -= 1
        if m == 0:
            y, m = y - 1, 12
        return y * 100 + m

    def months_through(key):
        y, m = divmod(int(key), 100)
        return [y * 100 + mm for mm in range(1, m + 1)]

    def code_matches(a, b):
        aa = str(a).strip().upper().rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        bb = str(b).strip().upper().rstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        return aa == bb

    # 一次讀出目標股票的既有歷史；通常這裡就能直接修好，不必打網路。
    db_rows = {c: {} for c in targets}
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute("""
            SELECT code, period, month_revenue, cum_yoy_pct
            FROM revenue_history
            WHERE code = ANY(%s)
            ORDER BY code, period
        """, (targets,))
        for code, period, month_revenue, cum_yoy in cur.fetchall():
            c = next((x for x in targets if code_matches(x, code)), str(code))
            db_rows.setdefault(c, {})[int(_normalize_revenue_period(period) or 0)] = {
                "month_revenue": month_revenue,
                "cum_yoy_pct": cum_yoy,
            }
        cur.close()
        release_db_connection(conn)
    except Exception as exc:
        print(f"⚠️ 累計營收修補讀 DB 失敗：{type(exc).__name__}: {exc}")
        _trace("db_error", error=f"{type(exc).__name__}: {exc}")
        try:
            release_db_connection(conn)
        except Exception:
            pass

    _trace("db_loaded", rows={c: len(v) for c, v in db_rows.items()}, latest={c: db_rows.get(c, {}).get(latest_key) for c in targets})

    def try_calculate(code):
        rows = db_rows.get(code, {})
        # 若最新期本身已有官方累計 YoY，直接採用，不必重新計算。
        latest_item = rows.get(latest_key)
        if latest_item and latest_item.get("cum_yoy_pct") is not None:
            return float(latest_item["cum_yoy_pct"])

        current_months = months_through(latest_key)
        prior_year_key = latest_key - 100
        prior_months = [k - 100 for k in current_months]
        cur_vals = []
        prev_vals = []
        for ck, pk in zip(current_months, prior_months):
            cv = rows.get(ck, {}).get("month_revenue")
            pv = rows.get(pk, {}).get("month_revenue")
            try:
                cv = float(cv) if cv is not None else None
                pv = float(pv) if pv is not None else None
            except (TypeError, ValueError):
                cv = pv = None
            if cv is None or pv is None:
                return None
            cur_vals.append(cv)
            prev_vals.append(pv)
        if cur_vals and sum(prev_vals) != 0:
            return (sum(cur_vals) / sum(prev_vals) - 1.0) * 100.0
        return None

    for code in targets:
        # ★ 重要修正：latest_key 是「全市場目前看到的最新月份」，不能直接
        # 當成「這一檔股票已公告的最新月份」。例如 2026/10/01 全市場資料
        # 可能已進入 11509，但 2308 尚未公告 9 月；2308 此時必須回退到
        # 自己資料庫真正存在的最新月份 11508，才能計算 1~8 月累計 YoY。
        rows = db_rows.get(code, {})
        db_latest_key = None
        for k in sorted(rows, reverse=True):
            item = rows.get(k) or {}
            if item.get("month_revenue") is not None or item.get("cum_yoy_pct") is not None:
                db_latest_key = k
                break

        calculation_key = latest_key
        _trace("stock_latest_period", code=code, global_latest=latest_key,
               db_latest=db_latest_key)

        # 先用這一檔目前已存在的最新 DB 資料試算。這一步會讓「尚未公告新月份」
        # 的股票直接使用上一個已公告月份，而不是卡在全市場新月份。
        if db_latest_key and db_latest_key < latest_key:
            calculation_key = db_latest_key
            def _try_calculate_at(key):
                item = rows.get(key)
                if item and item.get("cum_yoy_pct") is not None:
                    return float(item["cum_yoy_pct"])
                current_months = months_through(key)
                cur_vals, prev_vals = [], []
                for ck in current_months:
                    pk = ck - 100
                    cv = rows.get(ck, {}).get("month_revenue")
                    pv = rows.get(pk, {}).get("month_revenue")
                    try:
                        cv = float(cv) if cv is not None else None
                        pv = float(pv) if pv is not None else None
                    except (TypeError, ValueError):
                        cv = pv = None
                    if cv is None or pv is None:
                        return None
                    cur_vals.append(cv)
                    prev_vals.append(pv)
                if cur_vals and sum(prev_vals) != 0:
                    return (sum(cur_vals) / sum(prev_vals) - 1.0) * 100.0
                return None

            calculated = _try_calculate_at(calculation_key)
            if calculated is not None:
                revenue_data.setdefault(code, {})["cum_yoy_pct"] = calculated
                revenue_data.setdefault(code, {})["revenue_period"] = str(calculation_key)
                _trace("calculated_from_stock_latest", code=code, period=calculation_key,
                       cum_yoy_pct=calculated)
                print(f"✅ 累計營收依個股最新已公告月份修補：{code}/{calculation_key} = {calculated:+.2f}%")
                continue

        calculated = try_calculate(code)
        if calculated is not None:
            revenue_data.setdefault(code, {})["cum_yoy_pct"] = calculated
            _trace("calculated_from_db", code=code, cum_yoy_pct=calculated)
            print(f"✅ 累計營收由既有月資料修補：{code} = {calculated:+.2f}%")
            continue

        _trace("db_calculation_failed", code=code, available_periods=sorted(db_rows.get(code, {}).keys())[-8:])

        # 先直接問最新完整月的 MOPS 官方資料；若官方列本身有累計 YoY，這一步就結束。
        market = None
        try:
            mm = get_market_map() or {}
            market = mm.get(code)
        except Exception:
            market = None
        _trace("market_resolved", code=code, market=market)
        try:
            fetched, fetched_period = _fetch_mops_revenue_fallback(
                latest_key, target_code=code, market=market
            )
            _trace("mops_latest_result", code=code, fetched_period=fetched_period, found=bool(fetched), keys=list((fetched or {}).keys())[:10], item=(next((v for k, v in (fetched or {}).items() if code_matches(code, k)), None) if fetched else None))
            if fetched:
                item = fetched.get(code)
                if item is None:
                    item = next((v for k, v in fetched.items() if code_matches(code, k)), None)
                if item:
                    revenue_data.setdefault(code, {}).update(item)
                    if fetched_period:
                        save_revenue_history(fetched_period, {
                            code: item
                        })
                    if item.get("cum_yoy_pct") is not None:
                        print(f"✅ MOPS 直接補回累計營收：{code} = {float(item['cum_yoy_pct']):+.2f}%")
                        continue
                    db_rows.setdefault(code, {})[latest_key] = {
                        "month_revenue": item.get("month_revenue"),
                        "cum_yoy_pct": item.get("cum_yoy_pct"),
                    }
        except Exception as exc:
            _trace("mops_latest_error", code=code, error=f"{type(exc).__name__}: {exc}")
            print(f"⚠️ MOPS 最新月營收修補失敗 {code}: {type(exc).__name__}: {exc}")

        # 最新列仍沒有累計 YoY，就只為這檔股票補齊今年與去年同期的月營收。
        # 已存在 DB 的月份不再重抓。
        current_months = months_through(latest_key)
        needed = []
        rows = db_rows.setdefault(code, {})
        for ck in current_months:
            if ck not in rows or rows[ck].get("month_revenue") is None:
                needed.append(ck)
            pk = ck - 100
            if pk not in rows or rows[pk].get("month_revenue") is None:
                needed.append(pk)

        # 避免單一壞資料造成大量請求；最多補 24 個月。
        _trace("history_needed", code=code, needed=sorted(set(needed))[:24], count=len(set(needed)))
        for key in sorted(set(needed))[:24]:
            try:
                fetched, fetched_period = _fetch_mops_revenue_fallback(
                    key, target_code=code, market=market
                )
                if not fetched:
                    continue
                item = fetched.get(code)
                if item is None:
                    item = next((v for k, v in fetched.items() if code_matches(code, k)), None)
                if not item:
                    continue
                nk = _normalize_revenue_period(fetched_period or key) or key
                rows[nk] = {
                    "month_revenue": item.get("month_revenue"),
                    "cum_yoy_pct": item.get("cum_yoy_pct"),
                }
                save_revenue_history(fetched_period or str(key), {code: item})
                if item.get("cum_yoy_pct") is not None and nk == latest_key:
                    revenue_data.setdefault(code, {}).update(item)
            except Exception as exc:
                _trace("mops_history_error", code=code, period=key, error=f"{type(exc).__name__}: {exc}")
                print(f"⚠️ MOPS 歷史月營收修補失敗 {code}/{key}: {type(exc).__name__}: {exc}")

        # MOPS 補抓後，再以「這一檔實際存在的最新月份」重新計算一次。
        # 如果最新月份尚未公告，不應因全市場 latest_key 較新而直接判定資料不足。
        rows = db_rows.get(code, {})
        stock_latest_key = None
        for k in sorted(rows, reverse=True):
            item = rows.get(k) or {}
            if item.get("month_revenue") is not None or item.get("cum_yoy_pct") is not None:
                stock_latest_key = k
                break

        if stock_latest_key and stock_latest_key != latest_key:
            item = rows.get(stock_latest_key) or {}
            if item.get("cum_yoy_pct") is not None:
                calculated = float(item["cum_yoy_pct"])
            else:
                cur_vals, prev_vals = [], []
                for ck in months_through(stock_latest_key):
                    cv = rows.get(ck, {}).get("month_revenue")
                    pv = rows.get(ck - 100, {}).get("month_revenue")
                    try:
                        cv = float(cv) if cv is not None else None
                        pv = float(pv) if pv is not None else None
                    except (TypeError, ValueError):
                        cv = pv = None
                    if cv is None or pv is None:
                        cur_vals = []
                        break
                    cur_vals.append(cv); prev_vals.append(pv)
                calculated = ((sum(cur_vals) / sum(prev_vals) - 1.0) * 100.0
                              if cur_vals and sum(prev_vals) != 0 else None)
            if calculated is not None:
                revenue_data.setdefault(code, {})["cum_yoy_pct"] = calculated
                revenue_data.setdefault(code, {})["revenue_period"] = str(stock_latest_key)
                _trace("calculated_after_stock_fallback", code=code, period=stock_latest_key,
                       cum_yoy_pct=calculated)
                print(f"✅ 累計營收依個股最新月份完成修補：{code}/{stock_latest_key} = {calculated:+.2f}%")
                continue

        calculated = try_calculate(code)
        if calculated is not None:
            revenue_data.setdefault(code, {})["cum_yoy_pct"] = calculated
            _trace("calculated_after_mops", code=code, cum_yoy_pct=calculated, periods=len(db_rows.get(code, {})))
            print(f"✅ 累計營收計算修補完成：{code} = {calculated:+.2f}%")
        else:
            _trace("repair_failed", code=code, periods=sorted(db_rows.get(code, {}).keys())[-12:])
            print(f"⚠️ 累計營收仍無法計算：{code}（保留資料不足，不猜數字）")

    return revenue_data


@app.route("/web/admin/revenue-debug")
@web_login_required
def web_admin_revenue_debug(uid):
    """ADMIN ONLY：追蹤單一股票累計營收 YoY 從來源到五大因子的完整資料鏈。"""
    if not is_admin(uid):
        return make_response("Forbidden", 403)
    code = normalize_code(request.args.get("code") or "2308")
    if not re.fullmatch(r"\d{4,6}[A-Za-z]?", code or ""):
        return _workbench_json_response({"ok": False, "error": "股票代號格式錯誤"}, 400)

    trace = []
    out = {"ok": True, "code": code, "checked_at": datetime.now().isoformat()}
    try:
        raw = fetch_monthly_revenue() or {}
        out["cache"] = {"period": _revenue_cache.get("period"), "source": _revenue_cache.get("source"), "updated_at": str(_revenue_cache.get("updated_at")), "code_present": code in raw}
        out["fetch_monthly_revenue"] = raw.get(code) or next((v for k,v in raw.items() if str(k).strip()==code), None)
        try:
            market_map = get_market_map() or {}
            out["market"] = market_map.get(code)
        except Exception as exc:
            out["market_error"] = f"{type(exc).__name__}: {exc}"

        conn = get_db_connection()
        try:
            cur = conn.cursor()
            cur.execute("SELECT code, period, month_revenue, cum_yoy_pct FROM revenue_history WHERE code=%s ORDER BY period DESC LIMIT 24", (code,))
            rows = cur.fetchall()
            out["db_history"] = [{"code":r[0],"period":r[1],"month_revenue":r[2],"cum_yoy_pct":r[3]} for r in rows]
            cur.close()
        finally:
            release_db_connection(conn)

        latest_key = _normalize_revenue_period(_revenue_cache.get("period"))
        if latest_key:
            try:
                market = out.get("market")
                fetched, fetched_period = _fetch_mops_revenue_fallback(latest_key, target_code=code, market=market)
                item = next((v for k,v in (fetched or {}).items() if str(k).strip()==code), None)
                out["mops_direct"] = {"period": fetched_period, "item": item, "found": bool(item), "keys": list((fetched or {}).keys())[:20]}
            except Exception as exc:
                out["mops_direct"] = {"error": f"{type(exc).__name__}: {exc}"}

        # 這一步與正式評分完全相同，並保留每個分支的 trace。
        repaired = _repair_missing_cumulative_revenue([code], {code: dict(out["fetch_monthly_revenue"] or {})}, trace=trace)
        out["after_repair"] = repaired.get(code)
        try:
            scored = _compute_stock_watchlist_scores([code]) or {}
            item = scored.get(code) or {}
            out["final_score_path"] = {"cum_yoy": item.get("cum_yoy"), "revenue": item.get("revenue"), "valuation": item.get("valuation"), "total": item.get("total"), "pe": item.get("pe")}
        except Exception as exc:
            out["final_score_path_error"] = f"{type(exc).__name__}: {exc}"
        out["trace"] = trace
        return _workbench_json_response(out)
    except Exception as exc:
        out["ok"] = False
        out["error"] = f"{type(exc).__name__}: {exc}"
        out["trace"] = trace
        return _workbench_json_response(out, 500)


def _compute_stock_watchlist_scores(codes):
    """
    計算個股自選評分；LINE、持股頁、選股台共用「網頁五大因子模型」。
    這裡只統一模型，不調整五大因子的權重／門檻，待成效資料累積後再評估。
    """
    codes = [str(c).strip() for c in codes if c]
    if not codes:
        return {}

    institutional_data = fetch_institutional_data() or {}
    revenue_data = fetch_monthly_revenue() or {}
    # 五大因子真正使用前，先修補「有月營收、但累計 YoY 為 NULL」的個股。
    # 這是針對目前使用者的自選股做按需修補，不會把單月 YoY 冒充累計 YoY。
    revenue_data = _repair_missing_cumulative_revenue(codes, revenue_data)
    valuation_data = fetch_valuation() or {}
    industry_map = get_industry_map() or {}
    momentum_stats = get_industry_momentum(revenue_data, industry_map)
    streaks = get_consecutive_days_batch(codes)
    cum_map = get_cumulative_net_buy_for_codes(codes, days=10)
    price_map = get_realtime_stocks_bulk(codes)

    result = {}
    for code in codes:
        stock = price_map.get(code)
        if not stock:
            continue

        cum_lots, buy_days = cum_map.get(code, (0, 0))
        streak = streaks.get(code, 0)
        cum_yoy = revenue_data.get(code, {}).get("cum_yoy_pct")
        val = valuation_data.get(code, {}) or {}
        turnover = calc_turnover_billion(stock.get("close"), stock.get("volume"))

        model = score_stock_by_category(
            code, industry_map, stock, cum_yoy, val, streak,
            cum_lots, turnover, momentum_stats
        )
        # 「位階」與「籌碼／技術」是兩個不同概念：
        # 位階看股價相對 60 日高點與 20 日均線；籌碼／技術則沿用五大因子模型。
        # 舊版曾把 model["chip"] 寫進 position，導致首頁把籌碼／技術分數誤標成位階。
        position_score = score_watchlist_position(stock)
        category = model.get("category")
        total = model.get("total")
        if total is None:
            result[code] = {
                "code": code,
                "name": stock_display_name(code, institutional_data, stock.get("name")),
                "stock": stock,
                "total": None,
                "asset_type": "stock",
                "category": category,
                "factors": [],
                "cum_lots": cum_lots, "buy_days": buy_days, "streak": streak,
                "cum_yoy": cum_yoy, "pe": val.get("pe"),
            }
            continue

        caps = [float(x) for x in model.get("caps", (25,25,20,20,10))]
        factors = [
            {"name": "營收成長", "value": model.get("rev"), "max": caps[0]},
            {"name": "估值", "value": model.get("val"), "max": caps[1]},
            {"name": "產業動能", "value": model.get("mom"), "max": caps[2]},
            {"name": "法人連續性", "value": model.get("streak_score"), "max": caps[3]},
            {"name": "籌碼／技術", "value": model.get("chip"), "max": caps[4]},
        ]
        factor_details = _build_factor_details(
            code, stock, model, cum_yoy, val, streak, cum_lots, category
        )
        for factor in factors:
            detail = next((d for d in factor_details if d.get("name") == factor.get("name")), None)
            factor["details"] = detail.get("lines", []) if detail else []
        result[code] = {
            "code": code,
            "name": stock_display_name(code, institutional_data, stock.get("name")),
            "stock": stock,
            "total": int(round(total)),
            "asset_type": "stock",
            "category": category,
            "factors": factors,
            "chip": model.get("chip"),
            "position": position_score,
            "revenue": model.get("rev"),
            "valuation": model.get("val"),
            "momentum": model.get("mom"),
            "streak_score": model.get("streak_score"),
            "chip_tech": model.get("chip"),
            "caps": caps,
            "cum_lots": cum_lots, "buy_days": buy_days, "streak": streak,
            "cum_yoy": cum_yoy, "pe": model.get("pe"), "pb": model.get("pb"),
            "yield": model.get("yield"), "peg": model.get("peg"),
            "val_desc": model.get("val_desc"), "mom_desc": model.get("mom_desc"),
            "turnover": turnover,
        }
    return result


def compute_watchlist_scores(codes):
    """自選股評分總入口：個股與 ETF 分流，避免用錯商品模型。"""
    normalized = list(dict.fromkeys(
        str(code).strip().upper() for code in (codes or []) if str(code).strip()))
    if not normalized:
        return {}
    stock_codes = [code for code in normalized if not is_etf(code)]
    etf_codes = [code for code in normalized if is_etf(code)]
    result = {}
    if stock_codes:
        result.update(_compute_stock_watchlist_scores(stock_codes))
    if etf_codes:
        result.update(_compute_etf_watchlist_scores(etf_codes))
    return result


def save_watchlist_scores(user_id, scores):
    """存下今天的自選股分數。同一天重複寫入會覆蓋，cron 跑兩次也不會重複。"""
    if not scores:
        return
    rows = []
    for s in scores.values():
        factors = s.get("factors") or []
        by_name = {str(x.get("name")): x.get("value") for x in factors if isinstance(x, dict)}
        caps = s.get("caps") or []
        rows.append((
            str(user_id).strip(), s["code"], s.get("total"), s.get("chip"),
            s.get("position"), s.get("revenue"), s.get("valuation"),
            (s.get("stock") or {}).get("close"),
            (s.get("stock") or {}).get("support"),
            (s.get("stock") or {}).get("resistance"),
            s.get("asset_type") or ("etf" if is_etf(s.get("code")) else "stock"),
            s.get("category"), by_name.get("營收成長"), by_name.get("估值"),
            by_name.get("產業動能"), by_name.get("法人連續性"),
            by_name.get("籌碼／技術"), json.dumps(caps, ensure_ascii=False),
        ))
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        execute_values(
            cursor,
            """
            INSERT INTO watchlist_scores
                (user_id, code, snapshot_date, total, chip, position,
                 revenue, valuation, close, support, resistance, asset_type,
                 category, factor_revenue, factor_valuation, factor_momentum,
                 factor_streak, factor_chip_tech, factor_caps)
            VALUES %s
            ON CONFLICT (user_id, code, snapshot_date) DO UPDATE SET
                total = EXCLUDED.total, chip = EXCLUDED.chip,
                position = EXCLUDED.position, revenue = EXCLUDED.revenue,
                valuation = EXCLUDED.valuation, close = EXCLUDED.close,
                support = EXCLUDED.support, resistance = EXCLUDED.resistance,
                asset_type = EXCLUDED.asset_type, category = EXCLUDED.category,
                factor_revenue = EXCLUDED.factor_revenue,
                factor_valuation = EXCLUDED.factor_valuation,
                factor_momentum = EXCLUDED.factor_momentum,
                factor_streak = EXCLUDED.factor_streak,
                factor_chip_tech = EXCLUDED.factor_chip_tech,
                factor_caps = EXCLUDED.factor_caps
            """,
            rows,
            template="(%s, %s, CURRENT_DATE, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
            page_size=200,
        )
        conn.commit()
        cursor.close()
    except Exception as e:
        conn.rollback()
        print(f"❌ 寫入自選股評分快照失敗: {e}")
    finally:
        release_db_connection(conn)


def get_previous_scores(user_id, codes, days_back=7):
    """
    取每檔最近一筆「今天以前」的分數，用來比對變化。
    不硬性取昨天：週末與假日沒有快照，取最近一筆有紀錄的才不會整片空白。
    回傳 {code: {"total":…, "date":…, 各分項}}
    """
    codes = [str(c).strip() for c in codes if c]
    if not codes:
        return {}
    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT DISTINCT ON (code)
                   code, snapshot_date, total, chip, position, revenue, valuation,
                   asset_type
            FROM watchlist_scores
            WHERE user_id = %s AND code = ANY(%s)
              AND snapshot_date < CURRENT_DATE
              AND snapshot_date >= CURRENT_DATE - %s
            ORDER BY code, snapshot_date DESC
            """,
            (str(user_id).strip(), codes, days_back),
        )
        rows = cursor.fetchall()
        cursor.close()
        return {r[0]: {"date": r[1], "total": r[2], "chip": r[3],
                       "position": r[4], "revenue": r[5], "valuation": r[6],
                       "asset_type": r[7] or "stock"}
                for r in rows}
    except Exception as e:
        print(f"❌ 讀取歷史評分失敗: {e}")
        return {}
    finally:
        release_db_connection(conn)


def describe_score_change(cur, prev):
    """
    把分數變化講成一句話，並指出是哪個面向在動。
    只講變化夠大的（±5 分以上）——每天一兩分的波動是雜訊，
    每檔都報一次會讓真正重要的變化被淹沒。
    回傳 (箭頭符號, 說明文字) 或 (None, None)
    """
    if not prev or cur.get("total") is None or prev.get("total") is None:
        return None, None
    cur_type = cur.get("asset_type") or ("etf" if is_etf(cur.get("code")) else "stock")
    prev_type = prev.get("asset_type") or ("etf" if is_etf(cur.get("code")) else "stock")
    # 模型切換時不拿個股舊分項與 ETF 新分項硬比，等下一筆同模型快照。
    if cur_type != prev_type:
        return None, None
    diff = cur["total"] - prev["total"]
    if abs(diff) < 5:
        return None, None

    # 找出貢獻最多的面向，讓「為什麼變」有依據而不只是報數字。
    if cur_type == "etf":
        parts = [("同期超額報酬", (cur.get("chip") or 0) - (prev.get("chip") or 0)),
                 ("價格報酬", (cur.get("position") or 0) - (prev.get("position") or 0)),
                 ("配息殖利率", (cur.get("revenue") or 0) - (prev.get("revenue") or 0)),
                 ("風險控制", (cur.get("valuation") or 0) - (prev.get("valuation") or 0))]
    else:
        parts = [("籌碼", cur["chip"] - prev["chip"]),
                 ("位階", cur["position"] - prev["position"]),
                 ("營收", cur["revenue"] - prev["revenue"]),
                 ("估值", cur["valuation"] - prev["valuation"])]
    driver, dval = max(parts, key=lambda x: abs(x[1]))
    reason = f"，主要來自{driver}{dval:+d}" if abs(dval) >= 3 else ""
    arrow = "📈" if diff > 0 else "📉"
    return arrow, f"{prev['total']}→{cur['total']} 分（{diff:+d}）{reason}"


def build_web_factor_observation(score):
    """以網頁五大因子做純資料歸納；不沿用舊版四因子買賣話術。"""
    factors = [x for x in (score.get("factors") or []) if isinstance(x, dict) and x.get("max")]
    if not factors:
        return "目前沒有足夠的五大因子分項資料。"
    ranked = sorted(factors, key=lambda x: (float(x.get("value") or 0) / float(x.get("max") or 1)), reverse=True)
    strong = ranked[0]
    weak = ranked[-1]
    def label(x):
        ratio = float(x.get("value") or 0) / float(x.get("max") or 1)
        return "偏強" if ratio >= 0.8 else ("中上" if ratio >= 0.6 else ("中性" if ratio >= 0.4 else "偏弱"))
    cat = score.get("category") or "個股"
    return (f"📌 {cat}｜目前相對較強：{strong.get('name')}（{label(strong)}）；"
            f"主要較弱：{weak.get('name')}（{label(weak)}）。"
            "目前先沿用網頁五大因子模型，待成效資料累積後再評估是否調整因子。")


def _format_stock_detail_lines(code, name, stock, score=None, bd=None,
                               industry_label=None, score_change=None,
                               watchlist_status=None):
    """LINE 個股查詢：先講事實，再講五大因子；不把模型分數包裝成買賣結論。"""
    lines = [f"📊 {code} {name}"]
    if industry_label:
        lines.append(industry_label)
    lines.append("─" * 14)

    close, pct = stock.get("close"), stock.get("pct")
    if close is not None and pct is not None:
        lines.append(f"💰 {close:.2f}（{pct:+.2f}%）")
    elif close is not None:
        lines.append(f"💰 {close:.2f}（漲跌資料不足）")
    else:
        lines.append("💰 股價資料不足")
    high, low = stock.get("high"), stock.get("low")
    lines.append(f"高低 {high:.2f}/{low:.2f}" if high is not None and low is not None else "高低資料不足")
    volume = stock.get("volume")
    lines.append(f"📦 {int(volume / 1000):,} 張" if volume is not None else "📦 成交量資料不足")
    lines.append(f"🛡️ 支撐 {fmt_support(stock)}")
    lines.append(f"🚧 壓力 {fmt_resistance(stock.get('resistance'))}")

    if score:
        caps = score.get('caps',[25,25,20,20,10])
        lines += ["", "【五大因子】",
                  f"營收成長　{score.get('revenue', 0):.0f}/{caps[0]:.0f}",
                  f"估值　　　{score.get('valuation', 0):.0f}/{caps[1]:.0f}",
                  f"產業動能　{score.get('momentum', 0):.0f}/{caps[2]:.0f}",
                  f"法人連續性 {score.get('streak_score', 0):.0f}/{caps[3]:.0f}",
                  f"籌碼／技術 {score.get('chip_tech', 0):.0f}/{caps[4]:.0f}",
                  f"模型分數　{score['total']}／100"]
        if score_change:
            lines.append(score_change)

        cum_yoy, pe, pb, dy, peg = score.get("cum_yoy"), score.get("pe"), score.get("pb"), score.get("yield"), score.get("peg")
        lines += ["", "【關鍵數據】",
                  f"累計營收年增 {cum_yoy:+.1f}%" if cum_yoy is not None else "累計營收年增：資料不足",
                  f"PE {pe:.1f} 倍" if pe is not None else "PE：資料不足"]
        if score.get('category') == '電子':
            lines.append(f"估值模型：PE ÷ 累計營收年增率，PEG≈{peg:.2f}" if peg is not None else "估值模型：PE ÷ 累計營收年增率，PEG無法計算")
            lines.append("※ 這裡的 PEG 不是標準 EPS-PEG，僅作模型比較")
        else:
            lines.append(f"PB {pb:.2f} 倍" if pb is not None else "PB：資料不足")
            lines.append(f"殖利率 {dy:.2f}%" if dy is not None else "殖利率：資料不足")
        lines += ["", "【模型解讀】", build_web_factor_observation(score),
                  "※ 模型分數用來比較五大面向的相對強弱，不代表買賣建議。"]

    lines += ["", "【法人籌碼】近10日"]
    desc = describe_investor_breakdown(bd)
    lines.append(desc if desc else "　尚無法人歷史資料")
    lines += ["", "【位階】", build_position_desc(stock)]
    if watchlist_status:
        lines += ["", watchlist_status]
    return lines

def _flex_report_contents(text):
    """把報告逐行轉成 Flex 元件，讓重點字級與粗細一致。"""
    contents = []
    first = True
    for raw_line in str(text or "").split("\n"):
        line = raw_line.strip()
        if not line:
            continue
        if set(line) == {"─"}:
            contents.append({"type": "separator", "margin": "sm", "color": "#D9DDE2"})
            first = False
            continue

        component = {
            "type": "text",
            "text": line,
            "size": "sm",
            "color": "#454C55",
            "wrap": True,
            "margin": "none" if first else "xs",
        }
        if line.startswith("📊") or (line.startswith("【") and "📊" in line[:12]):
            component.update({"size": "md", "weight": "bold", "color": "#1B2027",
                              "margin": "none" if first else "sm"})
        elif line.startswith("💰"):
            component.update({"size": "md", "weight": "bold", "color": "#1B2027",
                              "margin": "md"})
        elif "綜合評分" in line:
            component.update({"size": "md", "weight": "bold", "color": "#1B2027",
                              "margin": "md"})
        elif line.startswith("【"):
            component.update({"weight": "bold", "color": "#1B2027", "margin": "md"})
        elif line.startswith("※"):
            component.update({"size": "xs", "color": "#6F7782", "margin": "md"})
        contents.append(component)
        first = False
    return contents


def _build_text_flex_message(text, alt_text=None):
    """把沒有可點擊元件的報告也放進與新聞版相同的 Flex 卡片。"""
    return FlexSendMessage(
        alt_text=(alt_text or text)[:400],
        contents={"type": "bubble",
                  "body": {"type": "box", "layout": "vertical",
                           "contents": _flex_report_contents(text),
                           "paddingAll": "18px",
                           "backgroundColor": "#FFFFFF"},
                  "styles": {"body": {"backgroundColor": "#FFFFFF"}}})


def build_single_stock_report(code, user_id=None):
    """
    單檔完整健檢。LINE 直接輸入代號就走這裡——
    單檔與多檔自選股共用同一套手機版欄位，避免相同功能出現兩種格式。
    """
    stock = get_realtime_stock(code)
    if not stock:
        return f"❌ 查無代號 {code} 的行情，請確認代號是否正確。"

    inst = fetch_institutional_data() or {}
    scores = compute_watchlist_scores([code])
    score = scores.get(code)
    ind_map = get_industry_map() or {}
    industry = ind_map.get(code)
    name = short_company_name(stock_display_name(code, inst, stock["name"]))

    score_change = None
    if score and user_id:
        prev = get_previous_scores(user_id, [code]).get(code)
        arrow, change_txt = describe_score_change(score, prev)
        if arrow:
            score_change = f"{arrow} {change_txt}"

    bd = get_investor_breakdown([code]).get(code)
    watchlist_status = None
    if user_id:
        in_wl = code in get_user_watchlist(user_id)
        watchlist_status = ("※ 已在自選清單" if in_wl
                            else f"※ 輸入「加 {code}」加入自選")

    lines = _format_stock_detail_lines(
        code, name, stock, score=score, bd=bd,
        industry_label=(f"📌 {score.get('category') or '個股'}" + (f"｜{industry_name(industry)}" if industry else "")) if score else (industry_name(industry) if industry else None),
        score_change=score_change, watchlist_status=watchlist_status)

    news = fetch_stock_news(
        name, max_items=2, within_hours=36,
        subject_name=name, known_names=_news_company_names([name]))
    core_report = "\n".join(lines)
    if not news:
        core_report += ("\n\n📰 相關新聞\n"
                        f"目前沒有抓到以{name}為主體的相關新聞。")
        return _build_text_flex_message(core_report)

    # 單檔查詢保留完整健檢文字，但新聞標題使用可點擊 Flex 元件，
    # 不把 Google News 的長網址直接顯示在聊天室。
    contents = _flex_report_contents(core_report)
    contents += [
        {"type": "separator", "margin": "lg", "color": "#E8EAE6"},
        {"type": "text", "text": "📰 相關新聞", "weight": "bold",
         "size": "sm", "color": "#1B2027", "margin": "lg"},
    ]
    for index, item in enumerate(news):
        src = f"（{item['source']}）" if item.get("source") else ""
        component = {"type": "text", "text": f"・{item['title']}{src}",
                     "size": "sm", "color": "#4A5F7A", "wrap": True,
                     "decoration": "underline",
                     "margin": "md" if index else "sm"}
        uri = _valid_news_uri(item.get("link"))
        if uri:
            component["action"] = {"type": "uri", "uri": uri}
        else:
            component.pop("decoration", None)
            component["color"] = "#454C55"
        contents.append(component)
    alt_text = core_report + "\n📰 相關新聞\n" + "；".join(
        item.get("title", "") for item in news)
    return FlexSendMessage(
        alt_text=alt_text[:400],
        contents={"type": "bubble",
                  "body": {"type": "box", "layout": "vertical",
                           "contents": contents, "paddingAll": "18px",
                           "backgroundColor": "#FFFFFF"},
                  "styles": {"body": {"backgroundColor": "#FFFFFF"}}})

def _etf_price_drawdown_summary(closes, close_dates):
    """用可取得的價格序列計算觀測期間最大回撤與是否回到前高。"""
    values = []
    for index, value in enumerate(closes or []):
        try:
            number = float(value)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        date_value = close_dates[index] if index < len(close_dates) else None
        values.append((number, date_value))
    if len(values) < 3:
        return None
    peak_value, peak_date = values[0]
    peak_index = 0
    max_drawdown = 0.0
    trough_index = 0
    trough_value = peak_value
    for index, (value, date_value) in enumerate(values):
        if value > peak_value:
            peak_value, peak_date = value, date_value
            peak_index = index
        drawdown = value / peak_value - 1.0 if peak_value else 0.0
        if drawdown < max_drawdown:
            max_drawdown = drawdown
            trough_index = index
            trough_value = value
    if max_drawdown >= 0:
        return {"max_drawdown": 0.0, "peak_date": peak_date,
                "trough_date": peak_date, "recovery_date": peak_date,
                "recovery_days": 0, "latest_gap": 0.0}
    recovery_index = None
    for index in range(trough_index + 1, len(values)):
        if values[index][0] >= peak_value:
            recovery_index = index
            break
    latest_gap = values[-1][0] / peak_value - 1.0 if peak_value else None
    return {
        "max_drawdown": max_drawdown * 100,
        "peak_date": peak_date,
        "trough_date": values[trough_index][1],
        "recovery_date": values[recovery_index][1] if recovery_index is not None else None,
        "recovery_days": (recovery_index - trough_index) if recovery_index is not None else None,
        "latest_gap": latest_gap * 100 if latest_gap is not None else None,
    }


def build_single_etf_report(code, user_id=None):
    """ETF 單檔摘要；不套用個股營收、PE 或法人籌碼評分。"""
    code = str(code).strip()
    meta = get_etf_metadata(code)
    stock = get_realtime_stock(code, rng="5y")
    if not stock:
        return f"❌ 查無 ETF {code} 的行情，請確認代號是否正確。"

    name = short_company_name(meta.get("name") or stock_display_name(code, fallback=stock.get("name")))
    close = stock.get("close")
    pct = stock.get("pct")
    lines = [f"📦 {code} {name}",
             f"{meta.get('category', '待分類')} ETF｜{meta.get('management_style', '待確認')}",
             "─" * 14]
    if close is not None and pct is not None:
        lines.append(f"💰 最新價格 {close:,.2f}（{pct:+.2f}%）")
    elif close is not None:
        lines.append(f"💰 最新價格 {close:,.2f}（漲跌資料不足）")
    else:
        lines.append("💰 價格資料不足")
    if stock.get("volume") is not None:
        lines.append(f"📦 成交量 {int(stock['volume'] / 1000):,} 張")

    lines += ["", "【ETF 商品】",
              f"管理方式：{meta.get('management_style', '待確認')}",
              f"策略分類：{meta.get('category', '待分類')}",
              f"追蹤基準：{meta.get('benchmark') or '資料待確認'}"]
    if meta.get("policy_note"):
        # 配息來源備註屬於配息區塊，避免和商品基本資料混在一起。
        policy_note = f"配息備註：{meta['policy_note']}"
    else:
        policy_note = None

    distribution_records = meta.get("distribution_records") or []
    lines += ["", "【配息明細】",
              f"配息政策：{_etf_distribution_label(meta.get('distribution_policy'))}"]
    if meta.get("distribution_frequency"):
        lines.append(f"配息頻率：{meta['distribution_frequency']}")
    if policy_note:
        lines.append(policy_note)
    if meta.get("distribution_policy") == "non_distributing":
        lines.append("現金配息：不適用（不分配／累積型）")
    elif distribution_records:
        latest = _etf_recent_distribution_records(meta, limit=1)
        latest = latest[0] if latest else distribution_records[0]
        latest_amount = latest.get("amount")
        latest_amount_text = (f"每單位 {float(latest_amount):.4f} 元"
                              if latest_amount is not None else "金額待確認")
        lines.append(f"最近一次除息：{latest.get('ex_date') or '未標日期'}・{latest_amount_text}")
        lines.append(f"官方已核實配息：{len(distribution_records)} 筆")
    elif meta.get("distribution_policy") == "distributing":
        lines.append("現金配息：官方已發生金額待確認；空白不視為 0 元")
    else:
        lines.append("現金配息：官方配息政策或金額待確認")
    if distribution_records:
        recent_records = _etf_recent_distribution_records(meta, limit=4)
        lines.append(_format_recent_distribution_records(recent_records))

    # 單檔報告只讀取既有 ranking snapshot，不為了顯示對照而重掃全市場。
    ranking_row = None
    ranking_period_label = None
    try:
        ranking_payload, _ranking_fresh, _ranking_source = _load_etf_product_ranking_snapshot()
        for period_key in ("short", "long"):
            period_rows = ((ranking_payload or {}).get("categories") or {}) \
                          .get(period_key, {})
            found = []
            for rows in period_rows.values() if isinstance(period_rows, dict) else []:
                if isinstance(rows, list):
                    found.extend(rows)
            ranking_row = next((item for item in found
                                if str(item.get("code") or "").strip().upper() == code.upper()), None)
            if ranking_row:
                period_info = ((ranking_payload or {}).get("periods") or {}).get(period_key) or {}
                ranking_period_label = period_info.get("label") or ("短期" if period_key == "short" else "長期")
                break
    except Exception as exc:
        print(f"⚠️ 單檔 ETF 報酬對照快照待確認: {exc}")

    if ranking_row:
        performance = _etf_performance_comparison(ranking_row)
        lines += ["", f"【報酬對照｜{ranking_period_label}】",
                  "價格報酬不含配息",
                  f"ETF 價格報酬：{performance['return_text']}",
                  f"同期大盤：{performance['market_text']}",
                  f"超額報酬：{performance['excess_text']}（{performance['verdict_text']}）"]
    else:
        lines += ["", "【報酬對照】", "ETF／同期大盤／超額報酬：待排名快照確認"]

    closes = [float(x) for x in (stock.get("closes") or []) if x not in (None, 0)]
    close_dates = stock.get("close_dates") or []
    if distribution_records and close is not None:
        lines += ["", "【配息統計】"]
        end_date = _parse_history_date(close_dates[-1]) if close_dates else taiwan_today()
        trailing = _etf_trailing_distribution_metrics(meta, end_date, close)
        stability = _etf_distribution_stability_metrics(meta, end_date, close)
        if trailing.get("status") == "verified":
            lines.append(f"近12個月官方現金配息：{float(trailing['amount']):.2f} 元")
            lines.append(f"原始近12個月參考殖利率：{float(trailing['yield_pct']):.2f}%（以期末價格估算，非含息總報酬）")
            if stability.get("stability_status") == "verified_four_records":
                lines.append(f"評分用穩定殖利率：{float(stability['score_yield_pct']):.2f}%（近4次中位數／平均值調整，避免單次高配息直接灌高分）")
            else:
                lines.append("評分用穩定殖利率：待近4次官方配息資料完整")
        elif trailing.get("status") == "partial":
            observed = trailing.get("observed_yield_pct")
            observed_text = (f"；觀察期率 {float(observed):.2f}%"
                             if observed is not None else "")
            lines.append(
                f"已發生現金配息：{float(trailing['amount']):.2f} 元（{int(trailing.get('count') or 0)} 次）"
                f"{observed_text}；官方紀錄覆蓋 {int(trailing.get('coverage_days') or 0)} 日，未滿 12 個月，暫不年化")
    if len(closes) >= 2 and closes[0] > 0:
        return_pct = (closes[-1] / closes[0] - 1) * 100
        observed = f"{close_dates[0]} 至 {close_dates[-1]}" if close_dates else "可取得價格期間"
        lines += ["", "【目前可計算】",
                  f"可取得期間價格變化：{return_pct:+.2f}%",
                  f"觀測期間：{observed}",
                  "※ 第一版先顯示可追溯的價格序列，不把價格變化冒充完整含息總報酬。"]
    else:
        lines += ["", "【目前可計算】", "價格歷史資料不足，暫不計算報酬"]

    drawdown = _etf_price_drawdown_summary(closes, close_dates)
    if drawdown:
        dd = float(drawdown.get("max_drawdown") or 0)
        lines += ["", "【風險觀察】", f"可取得價格期間最大回撤：{dd:+.1f}%"]
        if dd == 0:
            lines.append("恢復狀態：觀測期間尚無明顯回撤")
        elif drawdown.get("recovery_date"):
            lines.append(f"恢復狀態：已於 {drawdown['recovery_date']} 回到前高（{drawdown['recovery_days']} 個交易日）")
        else:
            latest_gap = drawdown.get("latest_gap")
            gap_text = f"；目前仍低於前高 {abs(float(latest_gap)):.1f}%" if latest_gap is not None and latest_gap < 0 else ""
            lines.append(f"恢復狀態：尚未回到前高，截至 {close_dates[-1] if close_dates else '資料日'}{gap_text}")
        lines.append("※ 目前使用價格序列計算，未把配息調整成含息總報酬回撤。")

    lines += ["", "【資料成熟度】",
              _etf_maturity_label(meta.get("listing_date")),
              f"成立日：{meta.get('inception_date') or '待確認'}",
              f"掛牌日：{meta.get('listing_date') or '待確認'}",
              "", "※ ETF 不套用個股營收、PE、法人籌碼評分；資料不足會明確標示。"]
    if user_id:
        in_wl = code in get_user_watchlist(user_id)
        lines.append("※ 已在自選清單" if in_wl else f"※ 輸入「加 {code}」加入自選")
    return _build_text_flex_message("\n".join(lines), alt_text=f"{code} {name} ETF 分析")


def build_healthcheck_report(user_id):
    """LINE 多檔自選健檢；每檔與單檔查詢共用同一套手機版面。"""
    codes = get_user_watchlist(user_id)
    if not codes:
        return "📂 自選股清單是空的\n輸入「加 3081」新增自選"

    scores = compute_watchlist_scores(codes)
    prev_scores = get_previous_scores(user_id, codes)
    tags = get_watchlist_tags(user_id)
    stock_codes = [code for code in codes if not is_etf(code)]
    breakdowns = get_investor_breakdown(stock_codes) if stock_codes else {}
    industry_map = get_industry_map() or {}

    rows = []
    for code in codes:
        tag = tags.get(code)
        score = scores.get(code)
        if not score:
            missing_label = (f"⚪ {code} ETF 資料待確認，暫不套用個股評分"
                             if is_etf(code) else f"⚪ {code} 查無行情")
            rows.append((tag, -1, missing_label))
            continue

        arrow, change_txt = describe_score_change(score, prev_scores.get(code))
        score_change = f"{arrow} {change_txt}" if arrow else None
        if score.get("asset_type") == "etf":
            lines = _format_etf_watchlist_lines(
                code, score, score_change=score_change,
                watchlist_status="※ 已在自選清單")
            sort_score = score.get("total") if score.get("total") is not None else -1
            rows.append((tag, sort_score, "\n".join(lines)))
            continue

        stock = score["stock"]
        name = score["name"]
        industry = industry_map.get(code)
        lines = _format_stock_detail_lines(
            code, name, stock, score=score, bd=breakdowns.get(code),
            industry_label=(f"📌 {score.get('category') or '個股'}" + (f"｜{industry_name(industry)}" if industry else "")) if score else (industry_name(industry) if industry else None),
            score_change=score_change,
            watchlist_status="※ 已在自選清單")
        rows.append((tag, score["total"], "\n".join(lines)))

    grouped = {}
    for tag, total, text in rows:
        grouped.setdefault(tag, []).append((total, text))

    order = [t for t in WATCHLIST_TAGS if t in grouped]
    if None in grouped:
        order.append(None)

    blocks = []
    has_tags = any(t is not None for t in grouped)
    for tag in order:
        items = sorted(grouped[tag], key=lambda x: x[0], reverse=True)
        numbered = [f"【{index}】 {text}"
                    for index, (_, text) in enumerate(items, start=1)]
        item_block = "\n\n────────────\n\n".join(numbered)
        if has_tags:
            icon = TAG_ICONS.get(tag, "📌")
            label = tag or "未分類"
            blocks.append(f"{icon}　{label}（{len(items)}）\n\n" + item_block)
        else:
            blocks.append(item_block)

    body = "\n\n".join(blocks)
    tag_hint = ("" if has_tags else
                "\n分類：輸入「加 2330 長線」或「分類 2330 短線」")
    has_stock = any(not is_etf(code) for code in codes)
    has_etf = any(is_etf(code) for code in codes)
    formula_lines = []
    if has_stock:
        formula_lines.append("個股評分＝營收成長25＋估值25＋產業動能20＋法人連續性20＋籌碼／技術10")
    if has_etf:
        formula_lines.append("ETF評分＝依類別權重計算超額報酬、價格報酬、配息殖利率、回撤、波動與資料完整度")
    formula_text = "\n".join(formula_lines)
    report = (
        f"📋 自選股健檢（{len(codes)}檔）\n\n{body}\n\n"
        f"{formula_text}\n"
        f"🟢70+ 🟡45-69 🔴<45{tag_hint}\n"
        f"※ ETF 與個股使用不同模型；觀察為數據歸納，非投資建議，請自行判斷"
    )
    if len(report) > 4800:
        report = report[:4750] + "\n\n…（清單過長，已截斷）"
    return report

def render_watchlist_web_body(user_id):
    """保留的內部舊版 renderer；目前不由 LINE 或網頁導覽使用，自選健檢留在 LINE。"""
    codes = get_user_watchlist(user_id)
    if not codes:
        return ('<div class="tabs">'
                '<a href="/web/screener?mode=blackhorse&view=list">黑馬</a>'
                '<a href="/web/screener?mode=radar&view=list">雷達</a>'
                '<a href="/web/chips">籌碼超人</a>'
                '<a href="/web/screener?mode=review">成效</a></div>'
                '<section class="card"><div class="empty">自選股清單是空的。<br><br>'
                '請回 LINE 輸入「加 2330」新增自選股。</div></section>')

    fetch_institutional_data()
    scores = compute_watchlist_scores(codes)
    prev_scores = get_previous_scores(user_id, codes)
    tags = get_watchlist_tags(user_id)
    breakdowns = get_investor_breakdown(codes)

    def data_date_text():
        value = _t86_cache.get("data_date")
        if isinstance(value, (datetime, date)):
            return value.isoformat()
        return str(value or "未標日期")

    grouped = {tag: [] for tag in WATCHLIST_TAGS}
    grouped[None] = []
    for code in codes:
        tag = tags.get(code)
        s = scores.get(code)
        if not s:
            grouped.setdefault(tag, []).append(
                '<div class="watchlist-card watchlist-muted"><h3>⚪ '
                f'{html.escape(str(code))}</h3><p>查無目前行情，暫不計算健檢分數。</p></div>')
            continue

        if s.get("asset_type") == "etf":
            arrow, change_txt = describe_score_change(s, prev_scores.get(code))
            score_change = f"{arrow} {change_txt}" if arrow else None
            etf_lines = _format_etf_watchlist_lines(
                code, s, score_change=score_change,
                watchlist_status="※ 已在自選清單")
            total = s.get("total")
            flag = ("🟢" if total is not None and total >= 70
                    else "🟡" if total is not None and total >= 45 else "⚪")
            score_class = ("watchlist-good" if total is not None and total >= 70
                           else "watchlist-mid" if total is not None and total >= 45
                           else "watchlist-muted")
            card = f'''<article class="watchlist-card {score_class} watchlist-etf-card">
  <div class="watchlist-card-head"><div><h3>{flag} {html.escape(str(s.get("name") or code))}</h3>
    <span class="watchlist-code">{html.escape(str(code))}　ETF 專用健檢</span></div>
    <strong class="watchlist-score">{html.escape(str(total)) if total is not None else "待確認"}<small>{"分" if total is not None else ""}</small></strong></div>
  <div class="watchlist-etf-lines">{"<br>".join(html.escape(str(line)) for line in etf_lines)}</div>
</article>'''
            grouped.setdefault(tag, []).append(card)
            continue

        stock = s["stock"]
        name = s["name"]
        cum_lots, buy_days, streak = s["cum_lots"], s["buy_days"], s["streak"]
        chip_score, pos_score = s["chip"], s["position"]
        rev_score, val_score = s["revenue"], s["valuation"]
        cum_yoy, pe = s["cum_yoy"], s["pe"]
        total = s["total"]
        flag = "🟢" if total >= 70 else ("🟡" if total >= 45 else "🔴")
        score_class = "watchlist-good" if total >= 70 else ("watchlist-mid" if total >= 45 else "watchlist-low")

        bd = breakdowns.get(code)
        trust = bd["trust"] if bd else None
        if trust and trust["streak"] >= 3:
            note = f"投信連 {trust['streak']} 日買超（累計 {trust['cum']:+,} 張）"
        elif cum_lots < 0:
            note = f"近10日賣超 {abs(cum_lots):,} 張"
        elif streak >= 3:
            note = f"連續買超 {streak} 天"
        elif cum_lots > 0:
            note = f"近10日買超 {cum_lots:,} 張（{buy_days} 天）"
        else:
            note = "近期無明顯動作"

        pos_txt = (f"距高點 {stock['pos_vs_60d_high']:+.1f}%"
                   if stock.get("pos_vs_60d_high") is not None else "位階資料不足")
        rev_txt = f"營收年增 {cum_yoy:+.1f}%" if cum_yoy is not None else "營收無資料"
        pe_txt = f"PE {pe:.1f}" if pe else "PE 無"
        advice = build_watchlist_advice(total, chip_score, pos_score, rev_score,
                                        val_score, cum_lots, streak, stock, cum_yoy, pe)
        arrow, change_txt = describe_score_change(s, prev_scores.get(code))
        bd_desc = describe_investor_breakdown(bd)
        breakdown_html = (f'<p class="watchlist-breakdown">{html.escape(bd_desc)}</p>'
                          if bd_desc else "")
        change_html = (f'<span class="watchlist-change">{html.escape(arrow)} '
                       f'{html.escape(change_txt)}</span>' if arrow else "")
        stock_name = html.escape(str(name or code))
        card = f'''<article class="watchlist-card {score_class}">
  <div class="watchlist-card-head"><div><h3>{flag} {stock_name}</h3>
    <span class="watchlist-code">{html.escape(str(code))}　{change_html}</span></div>
    <strong class="watchlist-score">{int(total)}<small>分</small></strong></div>
  <div class="watchlist-metrics"><span>現價 <b>{float(stock.get("close") or 0):,.2f}</b></span>
    <span>今日 <b class="{'up' if (stock.get('pct') or 0) > 0 else ('down' if (stock.get('pct') or 0) < 0 else 'flat')}">{float(stock.get("pct") or 0):+.2f}%</b></span>
    <span>{html.escape(pos_txt)}</span></div>
  <div class="watchlist-facts"><span>{html.escape(note)}</span>
    <span>{html.escape(rev_txt)}　{html.escape(pe_txt)}</span>
    <span>🛡️{html.escape(fmt_support(stock))}　🚧{html.escape(fmt_resistance(stock.get("resistance")))}</span></div>
  {breakdown_html}
  <div class="watchlist-advice">{html.escape(advice).replace(chr(10), "<br>")}</div>
</article>'''
        grouped.setdefault(tag, []).append(card)

    formula_lines = []
    if any(not is_etf(code) for code in codes):
        formula_lines.append("個股：營收成長 25＋估值 25＋產業動能 20＋法人連續性 20＋籌碼／技術 10")
    if any(is_etf(code) for code in codes):
        formula_lines.append("ETF：依類別權重計算超額報酬、價格報酬、配息殖利率、回撤、波動與資料完整度")
    formula_text = "<br>".join(html.escape(text) for text in formula_lines)

    tag_order = [tag for tag in WATCHLIST_TAGS if grouped.get(tag)]
    if grouped.get(None):
        tag_order.append(None)
    sections = []
    for tag in tag_order:
        label = tag or "未分類"
        icon = TAG_ICONS.get(tag, "📌")
        cards = "".join(grouped[tag])
        sections.append(f'<section class="watchlist-group"><h2>{icon} {html.escape(label)}'
                        f'<small>（{len(grouped[tag])}）</small></h2>{cards}</section>')

    return f'''<style>
.watchlist-meta{{padding:13px 15px;margin:0 0 14px;border-left:3px solid var(--brass);background:#F9F9FB;color:var(--ink-soft);font-size:12px;line-height:1.6}}
.watchlist-intro{{color:var(--ink-soft);font-size:13px;line-height:1.7;margin:0 0 15px}}
.watchlist-group{{margin:20px 0 0}}.watchlist-group>h2{{font-size:19px;margin:0 0 10px;padding-bottom:8px;border-bottom:1px solid var(--rule)}}.watchlist-group>h2 small{{font-size:12px;color:var(--ink-faint);font-weight:400;margin-left:5px}}
.watchlist-card{{background:#FFF;border:1px solid #E5E5EA;border-left:4px solid #B8B5AB;border-radius:12px;padding:15px;margin:10px 0;box-shadow:0 3px 13px rgba(35,39,35,.05)}}.watchlist-card.watchlist-good{{border-left-color:#087A4B}}.watchlist-card.watchlist-mid{{border-left-color:#B18A39}}.watchlist-card.watchlist-low{{border-left-color:#B52F2F}}.watchlist-card-head{{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}}.watchlist-card h3{{font-size:18px;margin:0 0 3px;line-height:1.35}}.watchlist-code{{color:var(--ink-soft);font-size:12px}}.watchlist-change{{color:var(--brass);margin-left:6px}}.watchlist-score{{font-size:25px;line-height:1;color:var(--ink);white-space:nowrap}}.watchlist-score small{{font-size:12px;font-weight:400;margin-left:2px}}.watchlist-metrics{{display:flex;flex-wrap:wrap;gap:8px;margin:13px 0 9px;padding:9px 0;border-top:1px solid #EFEFF4;border-bottom:1px solid #EFEFF4;color:var(--ink-soft);font-size:12px}}.watchlist-metrics span{{padding-right:10px;border-right:1px solid #E5E5EA}}.watchlist-metrics span:last-child{{border-right:0}}.watchlist-metrics b{{color:var(--ink);margin-left:3px}}.watchlist-facts{{display:grid;gap:4px;color:var(--ink-soft);font-size:12px;line-height:1.55}}.watchlist-breakdown{{margin:10px 0 0;padding-top:9px;border-top:1px solid #EFEFF4;color:var(--ink-soft);font-size:12px;line-height:1.55}}.watchlist-advice{{margin-top:10px;padding:10px 11px;background:#F9F9FB;border-radius:8px;color:var(--ink-soft);font-size:12px;line-height:1.65}}.watchlist-muted{{color:var(--ink-soft)}}.watchlist-muted h3{{color:var(--ink)}}
@media(max-width:640px){{.watchlist-metrics{{gap:6px}}.watchlist-metrics span{{padding-right:6px}}.watchlist-card h3{{font-size:17px}}}}
</style>
<div class="tabs"><a href="/web/screener?mode=blackhorse&view=list">黑馬</a><a href="/web/screener?mode=radar&view=list">雷達</a><a href="/web/chips">籌碼超人</a><a href="/web/screener?mode=review">成效</a></div>
<div class="watchlist-meta">資料來源：即時健檢計算　法人資料日：<b>{html.escape(data_date_text())}</b>　共 <b>{len(codes)}</b> 檔</div>
    <p class="watchlist-intro">{formula_text}。這裡是公開資料整理，提供檢視線索，不構成買賣建議。</p>
{"".join(sections)}'''


def build_line_watchlist_message(user_id, base_url=None):
    """LINE 自選股健檢：完整內容留在 LINE，避免與網頁版實際庫存混淆。"""
    report = build_healthcheck_report(user_id)
    if not report:
        return TextSendMessage(text="📂 自選股清單是空的\n輸入「加 3081」新增自選")
    msg=_build_text_flex_message(report, alt_text=report)
    web_url=_line_feature_web_url(user_id,"positions",base_url)
    if web_url and isinstance(msg,FlexSendMessage) and isinstance(msg.contents,dict):
        msg.contents["body"]["contents"] += [
            {"type":"separator","margin":"lg","color":"#E8EAE6"},
            {"type":"button","style":"primary","height":"sm","color":"#6E5228","margin":"md",
             "action":{"type":"uri","label":"查看完整自選健檢","uri":web_url}},
        ]
    return msg

# --- 個股新聞（Google News RSS，免費、可帶關鍵字查詢） ---
def _news_company_names(extra=None):
    """整理現有 stock_info 名稱，供新聞主體判斷使用；不建立人工公司清單。"""
    names = set()
    try:
        names.update((get_name_map() or {}).values())
    except Exception as exc:
        print(f"⚠️ 讀取新聞公司名稱對照失敗：{exc}")
    names.update((extra or []))
    names.update((STOCK_NAME_MAP or {}).values())
    return tuple(sorted({short_company_name(name).strip() for name in names
                         if str(name or "").strip() and len(short_company_name(name).strip()) >= 2}))


def _news_subject_relevant(title, subject_name, known_names=None):
    """用可解釋的規則判斷標題主體，避免只因提到自選股就收進來。"""
    title = str(title or "").strip()
    subject = short_company_name(subject_name or "").strip()
    if not title or not subject or subject.casefold() not in title.casefold():
        return False

    # 呼叫端未提供公司清單時，仍使用現有 stock_info 的全市場名稱；
    # 這能辨識「群創法說……台積電」這類另一家公司事件。
    known = {short_company_name(name).strip() for name in
             (known_names if known_names is not None else _news_company_names())
             if str(name or "").strip() and len(short_company_name(name).strip()) >= 2}
    others = [name for name in known
              if len(name) >= 2 and name.casefold() != subject.casefold()
              and name.casefold() in title.casefold()]
    if not others:
        return True

    # 「台積電｜群創法說……台積電合作未回應」這類標題即使後段
    # 再次提到台積電，事件主體仍是群創；只要其他公司緊接財經事件詞，排除。
    match = re.search(r"[|｜:：／/—–-]", title)
    if match:
        head, tail = title[:match.start()], title[match.end():]
        if subject.casefold() in head.casefold():
            event_terms = ("法說", "財報", "營收", "股價", "獲利", "展望", "股東會",
                           "公告", "接單", "產能", "配息", "除息", "合作")
            tail_lower = tail.casefold()
            for other in others:
                pos = tail_lower.find(other.casefold())
                if pos >= 0 and any(term in tail[pos:pos + 40] for term in event_terms):
                    return False

    # 另一家公司才是主詞，而目標股只出現在「未回應／提及／供應／影響」等
    # 關係語句後面時，視為延伸提及，不列入該自選股新聞。
    relation_terms = ("未回應", "未提及", "提及", "提到", "談及", "受惠", "供應",
                      "供應鏈", "客戶", "影響", "連帶", "旗下", "比較")
    title_lower = title.casefold()
    subject_lower = subject.casefold()
    start = 0
    while True:
        pos = title_lower.find(subject_lower, start)
        if pos < 0:
            break
        before = title[max(0, pos - 14):pos]
        if any(term.casefold() in before for term in relation_terms):
            return False
        # 目標名稱若只在標題後段出現，且後面緊接合作／供應／受惠等
        # 關係詞，通常是被提及的公司，不是新聞事件主體。
        after = title[pos + len(subject):pos + len(subject) + 24]
        mention_after_terms = ("合作", "效益", "供應", "供應鏈", "客戶", "受惠",
                               "帶動", "影響", "相關", "夥伴", "聯手", "攜手")
        if pos >= max(8, int(len(title) * 0.35)) and any(
                term in after for term in mention_after_terms):
            return False
        start = pos + len(subject_lower)
    return True


def fetch_stock_news(keyword, max_items=2, within_hours=30, subject_name=None,
                     known_names=None):
    """
    抓取最新新聞，只保留標題、來源、連結與發布時間。

    這裡不抓新聞內文、不自行解讀，也不把網址直接塞進 LINE 文字；
    呼叫端可以把標題做成可點擊的 URI。查詢同時加入股票／財經主題詞，
    並對標題做關鍵字、財經語境與重複過濾，降低無關結果。
    """
    import xml.etree.ElementTree as ET
    from urllib.parse import quote

    keyword_text = str(keyword or "").strip()
    query_terms = [part.strip() for part in keyword_text.split(" OR ")
                   if part.strip()]
    finance_terms = (
        "股價", "營收", "法人", "財報", "法說", "業績", "獲利", "展望",
        "訂單", "產能", "供應鏈", "股利", "配息", "除息", "投資", "併購",
        "增資", "減資", "公告", "買超", "賣超", "漲停", "跌停", "新高", "新低",
    )
    if len(query_terms) > 1:
        query_text = (f"({' OR '.join(query_terms)}) "
                      f"({' OR '.join(finance_terms[:16])})")
    else:
        one_term = query_terms[0] if query_terms else keyword_text
        query_text = f'"{one_term}" ({" OR ".join(finance_terms[:16])})'
    query = quote(query_text)
    url = (f"https://news.google.com/rss/search?q={query}"
           f"&hl=zh-TW&gl=TW&ceid=TW:zh-Hant")
    try:
        res = requests.get(url, timeout=10, headers={'User-Agent': 'Mozilla/5.0'})
        root = ET.fromstring(res.content)
    except Exception as e:
        print(f"❌ 抓取新聞失敗（{keyword}）: {e}")
        return []

    now = datetime.now(timezone.utc)
    items = []
    seen_titles = set()
    for item in root.findall(".//item"):
        title = (item.findtext("title") or "").strip()
        link = (item.findtext("link") or "").strip()
        source = (item.findtext("source") or "").strip()
        pub = item.findtext("pubDate")
        if not title:
            continue

        # Google News 常把媒體名放在標題末端；只在 source 欄位空白時切出來。
        if " - " in title and not source:
            title, source = title.rsplit(" - ", 1)
        title = title.strip()
        title_key = title.casefold()
        if title_key in seen_titles:
            continue

        # 股票查詢至少要在標題中出現股票名稱；OR 查詢則至少命中一個主題詞。
        title_lower = title.casefold()
        if query_terms and not any(term.casefold() in title_lower
                                   for term in query_terms):
            continue
        if len(query_terms) == 1 and not any(term in title for term in finance_terms):
            continue
        if subject_name and not _news_subject_relevant(title, subject_name, known_names):
            continue

        if pub:
            try:
                pub_dt = datetime.strptime(
                    pub, "%a, %d %b %Y %H:%M:%S %Z"
                ).replace(tzinfo=timezone.utc)
                age_seconds = (now - pub_dt).total_seconds()
                if age_seconds < -7200 or age_seconds > within_hours * 3600:
                    continue
            except ValueError:
                pass

        seen_titles.add(title_key)
        items.append({"title": title, "source": source.strip(), "link": link})
        if len(items) >= max_items:
            break
    return items


def build_news_digest(user_id):
    """
    自選股新聞摘要：LINE 只顯示相關新聞標題，標題本身可點擊查看原文。
    不在聊天室顯示完整網址，也不把新聞內文或 AI 解讀帶進來。
    """
    codes = get_user_watchlist(user_id)
    if not codes:
        return None

    # 名稱不必先重新抓整份法人行情，避免新聞指令被不必要的外部查詢拖慢。
    names = {code: stock_display_name(code) for code in codes}
    all_company_names = _news_company_names(names.values())

    def fetch_one(code):
        try:
            return fetch_stock_news(
                names[code], max_items=2, within_hours=36,
                subject_name=names[code], known_names=all_company_names)
        except Exception as e:
            print(f"⚠️ 並行抓新聞失敗 {code}: {e}")
            return []

    with ThreadPoolExecutor(max_workers=min(4, len(codes))) as ex:
        news_map = dict(zip(codes, ex.map(fetch_one, codes)))

    records = []
    seen = set()
    for code in codes:
        for item in (news_map.get(code) or []):
            title = str(item.get("title") or "").strip()
            if not title or title.casefold() in seen:
                continue
            seen.add(title.casefold())
            records.append({"code": code, "name": names[code], **item})

    if not records:
        return TextSendMessage(text="📰 自選股新聞\n\n今日沒有抓到符合自選股與財經主題的相關新聞。")

    # LINE 只做入口，最多顯示 8 個標題，避免又變成長篇報告。
    records = records[:8]
    web_url = _line_feature_web_url(user_id, "news")
    contents = [
        {"type": "text", "text": f"📰 自選股新聞｜{taiwan_now().strftime('%m/%d')}",
         "weight": "bold", "size": "xl", "color": "#1B2027"},
        {"type": "text", "text": "只顯示相關新聞標題；點擊標題即可查看原文。",
         "size": "xs", "color": "#767D85", "margin": "sm", "wrap": True},
    ]
    for index, item in enumerate(records):
        uri = _valid_news_uri(item.get("link"))
        component = {
            "type": "text",
            "text": f"・{item['name']}｜{item['title']}",
            "size": "sm", "color": "#4A5F7A", "wrap": True,
            "maxLines": 3, "margin": "md" if index else "lg",
        }
        if uri:
            component["decoration"] = "underline"
            component["action"] = {"type": "uri", "uri": uri}
        contents.append(component)

    alt_text = "📰 自選股新聞｜" + "；".join(item["title"] for item in records[:3])
    if web_url:
        contents += [
            {"type": "separator", "margin": "lg", "color": "#E8EAE6"},
            {"type": "button", "style": "primary", "height": "sm",
             "color": "#6E5228", "margin": "md",
             "action": {"type": "uri", "label": "查看完整自選股新聞", "uri": web_url}},
        ]
    return FlexSendMessage(
        alt_text=alt_text[:400],
        contents={
            "type": "bubble",
            "body": {"type": "box", "layout": "vertical",
                     "contents": contents, "paddingAll": "18px",
                     "backgroundColor": "#FFFFFF"},
            "styles": {"body": {"backgroundColor": "#FFFFFF"}},
        },
    )


# ── 推播額度保護 ──
# LINE 免費方案每月 200 則「主動推播」（回覆訊息不計入）。
# 以每人每個交易日 1 則計算，一個月約 20 個交易日 → 最多約 9 人。
#
# 沒有這道保護的話，開通人數一多，額度會在月中某天突然用完，
# 而且是「前面幾個人收到、後面的人沒收到」這種難以察覺的失敗——
# 使用者不會來抱怨，只會覺得這個服務時好時壞。
# 寧可一開始就明確擋下，並在回應裡講清楚超出多少。
PUSH_MONTHLY_QUOTA = 200
PUSH_TRADING_DAYS = 21          # 一個月的交易日數，抓保守值
PUSH_MAX_USERS = PUSH_MONTHLY_QUOTA // PUSH_TRADING_DAYS   # ≈ 9 人


ANOMALY_HARD_DAILY_CAP = int(os.environ.get("ANOMALY_HARD_DAILY_CAP", "8") or 8)

def push_to_users(users, build_fn, label):
    """
    對名單推播，並在超過額度上限時只送前 N 位。

    名單順序來自資料庫（依 user_id 固定排序），所以「前 N 位」每次都一樣，
    不會今天這幾個收到、明天換另幾個——後者更糟，因為每個人都只收到一半。
    回傳統計字串。
    """
    over = max(0, len(users) - PUSH_MAX_USERS)
    targets = users[:PUSH_MAX_USERS]

    sent, failed, empty = 0, 0, 0
    for uid in targets:
        if is_user_quiet_hours(uid):
            print(f"🔕 {label}跳過靜音時段 {uid}")
            continue
        msg = build_fn(uid)
        if not msg:
            empty += 1
            continue
        try:
            outbound = (msg if isinstance(msg, (TextSendMessage, FlexSendMessage))
                        else TextSendMessage(text=str(msg)))
            _push_line_with_retry(uid, outbound)
            sent += 1
        except Exception as e:
            print(f"❌ {label}推播失敗 {uid}: {e}")
            failed += 1

    result = f"{label} done. sent={sent}, failed={failed}, empty={empty}"
    if over:
        warn = (f"⚠️ 已開通 {len(users)} 人，超過免費方案可負擔的 "
                f"{PUSH_MAX_USERS} 人，本次只推播前 {PUSH_MAX_USERS} 位。"
                f"請用「停用 N」減少開通人數。")
        print(warn)
        result += f" | {warn}"
    return result


@app.route("/cron/push-news", methods=["POST", "GET"])
def cron_push_news():
    """盤後推播自選股新聞。建議每個交易日 15:00 跑一次，一天一則。"""
    secret = request.args.get("token")
    if secret != os.environ.get("CRON_SECRET"):
        abort(403)
    return run_in_background(
        "新聞推播",
        lambda: push_to_users(get_notify_users(), build_news_digest, "新聞推播")), 200


# --- 排程推播訊息建構與 Cron 端點 ---
def build_digest(user_id):
    codes = get_user_watchlist(user_id)
    if not codes:
        return None
    inst_data = fetch_institutional_data()
    price_map = get_realtime_stocks_bulk(codes)   # 並行抓，取代逐檔序列請求
    lines = [f"☀️ 【每日自選股摘要】", "─" * 14]
    for code in codes:
        data = price_map.get(code)
        if data:
            name = stock_display_name(code, inst_data, data["name"])
            light = "🔴" if data['pct'] >= 0 else "🟢"
            lines.append(
                f"\n{light} {name} {code}｜{data['close']:.2f}（{data['pct']:+.2f}%）\n"
                f"🛡️ 支撐：{fmt_support(data)} | 🚧 壓力：{fmt_resistance(data['resistance'])}"
            )
        else:
            lines.append(f"\n⚪ {code} 查無行情")
    return "\n".join(lines)

def build_morning_push(user_id):
    """保留純文字版本，供沒有網頁入口時的相容 fallback 使用。"""
    return build_today_attention_push(user_id)


DEFAULT_WEB_BASE_URL = "https://stock-bot-6xct.onrender.com"
_morning_macro_cache = {"date": None, "lines": [], "data": None, "news": None}
_morning_macro_cache_lock = threading.Lock()


def public_web_base_url(base_url=None):
    """取得 LINE 推播可開啟的公開網址；背景 cron 沒有 request context。"""
    return (base_url or os.environ.get("WEB_BASE_URL")
            or os.environ.get("RENDER_EXTERNAL_URL")
            or DEFAULT_WEB_BASE_URL).rstrip("/")


def _morning_macro_data():
    """取得盤前 LINE 的美股與總經資料；同一天共用一次結果。"""
    today = taiwan_today()
    with _morning_macro_cache_lock:
        if (_morning_macro_cache.get("date") == today
                and _morning_macro_cache.get("data") is not None):
            return list(_morning_macro_cache["data"])

    symbols = ([s for _label, s in BRIEF_INDICES]
               + [s for _label, s in BRIEF_MACRO])
    quotes = fetch_quotes_bulk(symbols)
    data = []
    for group, targets in (("美股指數", BRIEF_INDICES),
                           ("風險指標", BRIEF_MACRO)):
        for label, symbol in targets:
            q = quotes.get(symbol)
            if q:
                close, pct, diff = q
                data.append({"group": group, "label": label, "symbol": symbol,
                             "close": close, "pct": pct, "diff": diff})
            else:
                data.append({"group": group, "label": label, "symbol": symbol,
                             "close": None, "pct": None, "diff": None})
    with _morning_macro_cache_lock:
        _morning_macro_cache["date"] = today
        _morning_macro_cache["data"] = list(data)
    return data


def _morning_macro_lines():
    """純文字 fallback 用的盤前美股與總經摘要。"""
    lines = ["☀️ 盤前／總經"]
    for group in ("美股指數", "風險指標"):
        values = []
        for item in _morning_macro_data():
            if item["group"] != group:
                continue
            if item["pct"] is None:
                values.append(f"{item['label']} 資料暫缺")
            else:
                arrow = "⚪" if abs(item["pct"]) < 0.005 else ("🔴" if item["pct"] > 0 else "🟢")
                values.append(f"{arrow} {item['label']} {item['pct']:+.2f}%")
        lines.append(("美股　" if group == "美股指數" else "風險　") + "　".join(values))
    return lines


def _morning_macro_news():
    """取得最多兩則近期總經新聞；沒有真實新聞就不顯示新聞區塊。"""
    today = taiwan_today()
    with _morning_macro_cache_lock:
        if (_morning_macro_cache.get("date") == today
                and _morning_macro_cache.get("news") is not None):
            return list(_morning_macro_cache["news"])
    try:
        items = fetch_stock_news(
            "CPI OR 非農 OR 聯準會 OR 美債殖利率",
            max_items=2, within_hours=36
        ) or []
    except Exception as exc:
        print(f"⚠️ 盤前總經新聞抓取失敗：{exc}")
        items = []
    news = []
    for item in items[:2]:
        if not item.get("title"):
            continue
        news.append({"title": str(item.get("title")),
                     "source": str(item.get("source") or ""),
                     "link": str(item.get("link") or "")})
    with _morning_macro_cache_lock:
        _morning_macro_cache["date"] = today
        _morning_macro_cache["news"] = list(news)
    return news


def _valid_news_uri(value):
    """只允許新聞原文的 HTTP／HTTPS 網址進入 LINE URI action。"""
    try:
        parsed = urlparse(str(value or "").strip())
        if parsed.scheme.lower() not in ("http", "https") or not parsed.netloc:
            return None
        return parsed.geturl()
    except Exception:
        return None


def _morning_macro_news_lines():
    lines = []
    for item in _morning_macro_news():
        source = f"（{item['source']}）" if item["source"] else ""
        line = f"・{item['title']}{source}"
        uri = _valid_news_uri(item.get("link"))
        if uri:
            line += f"\n　{uri}"
        lines.append(line)
    return lines


def _macro_metric_box(item):
    """Flex 的單一指標格：保留原 2×2 卡片尺寸，同時顯示現值與日漲跌幅。"""
    pct = item.get("pct")
    close = item.get("close")
    if close is None:
        current_value = "資料暫缺"
    elif item.get("symbol") == "^TNX":
        current_value = f"{close:.3f}%"
    else:
        current_value = f"{close:,.2f}"

    if pct is None:
        change_value = "—"
        value_color = "#767D85"
    else:
        change_value = f"{pct:+.2f}%"
        value_color = "#B52F2F" if pct > 0 else ("#087A4B" if pct < 0 else "#767D85")

    metric_row = {
        "type": "box", "layout": "horizontal", "alignItems": "center",
        "margin": "sm", "contents": [
            {"type": "text", "text": current_value, "size": "sm",
             "weight": "bold", "color": "#454C55", "flex": 1,
             "wrap": False, "maxLines": 1},
            {"type": "text", "text": change_value, "size": "sm",
             "weight": "bold", "color": value_color, "align": "end",
             "flex": 0, "wrap": False, "maxLines": 1},
        ]
    }
    return {
        "type": "box", "layout": "vertical", "flex": 1,
        "backgroundColor": "#F9F9FB", "cornerRadius": "8px",
        "paddingAll": "10px", "contents": [
            {"type": "text", "text": item["label"], "size": "xs",
             "color": "#454C55", "wrap": True, "maxLines": 2},
            metric_row,
        ]
    }


def _macro_metric_rows(group):
    items = [item for item in _morning_macro_data() if item["group"] == group]
    rows = []
    for index in range(0, len(items), 2):
        pair = items[index:index + 2]
        contents = [_macro_metric_box(item) for item in pair]
        if len(contents) == 1:
            contents.append({"type": "box", "layout": "vertical", "flex": 1,
                             "contents": []})
        rows.append({"type": "box", "layout": "horizontal", "spacing": "sm",
                     "margin": "sm" if rows else "none", "contents": contents})
    return rows


