@app.route("/check-revenue", methods=["POST", "GET"])
def check_revenue():
    """
    診斷月營收：直接顯示證交所／櫃買回的最新月份，以及快照存的月份。

    使用者回報「營收沒更新」時，光看程式碼分不出是：
      (a) 官方還沒公布　(b) 抓到了但沒存　(c) 存了但畫面讀舊快照
    這三種。把三邊的月份並排列出來就一目了然。
    """
    if request.args.get("token") != os.environ.get("CRON_SECRET"):
        abort(403)
    lines = [f"月營收診斷　{taiwan_now().strftime('%Y-%m-%d %H:%M:%S')}", "=" * 56, ""]

    snap = _load_shared_data_snapshot("monthly_revenue")
    if snap:
        lines.append("【Supabase 快照】")
        lines.append(f"  月份　{(snap.get('source_meta') or {}).get('period')}")
        lines.append(f"  資料日　{snap.get('data_date')}")
        lines.append(f"  筆數　{len(snap.get('payload') or {})}")
    else:
        lines.append("【Supabase 快照】無或已過期")
    lines.append("")

    lines.append("【記憶體快取】")
    lines.append(f"  月份　{_revenue_cache.get('period')}")
    lines.append(f"  來源　{_revenue_cache.get('source')}")
    lines.append(f"  筆數　{len(_revenue_cache.get('data') or {})}")
    lines.append("")

    lines.append("【官方端點目前回的最新月份】")
    # 網址必須跟 fetch_monthly_revenue 用的完全一致，
    # 否則診斷測的是另一組端點，結果不代表實際抓取的狀況。
    # 先前診斷把興櫃寫成 mopsfin_t187ap05_R（正式用的是 t187ap05_R），
    # 又用 requests.get 而不是 _session，才會出現「上櫃查詢失敗」的假警報。
    endpoints = [(f"{TWSE_BASE}/opendata/t187ap05_L", "上市"),
                 (f"{TPEX_BASE}/mopsfin_t187ap05_O", "上櫃"),
                 (f"{TPEX_BASE}/t187ap05_R", "興櫃")]
    for url, label in endpoints:
        try:
            # 一定要用 _session：櫃買中心的憑證缺少 Subject Key Identifier，
            # 直接 requests.get 會被新版 OpenSSL 拒絕。
            # 正式抓取本來就走 _session，診斷用 requests.get 只會產生
            # 「上櫃查詢失敗」的假警報——先前就是這樣誤判成真的抓不到。
            r = _session.get(url, timeout=12)
            r.raise_for_status()
            data = r.json()
            if not isinstance(data, list) or not data:
                lines.append(f"  {label}：回傳空資料")
                continue
            # 欄位名要跟 fetch_monthly_revenue 用的一致：
            # 月份在「資料年月」（民國格式，例如 11507 ＝ 115 年 7 月），
            # 不是「年度」「月份」——先前用錯鍵，所以一直顯示「無法解析」。
            periods = {}
            sample = None
            for row in data:
                per = str(row.get("資料年月") or row.get("Period") or "").strip()
                if per:
                    periods[per] = periods.get(per, 0) + 1
                code = str(row.get("公司代號") or row.get("SecuritiesCompanyCode")
                           or row.get("Code") or "").strip()
                if sample is None and code == "8996":
                    sample = row
            if periods:
                shown = "、".join(f"{p}（{n} 筆）" for p, n
                                  in sorted(periods.items(), reverse=True)[:3])
                lines.append(f"  {label}：{shown}")
            else:
                keys = list(data[0].keys())[:8] if data else []
                lines.append(f"  {label}：無法解析月份，欄位有 {keys}")
            if sample:
                lines.append(f"    高力 8996：資料年月 "
                             f"{sample.get('資料年月')}　"
                             f"當月營收 {sample.get('營業收入-當月營收')}　"
                             f"年增 {sample.get('營業收入-去年同月增減(%)')}%")
            elif label == "上市":
                lines.append("    （這批資料裡沒有 8996）")
        except Exception as exc:
            lines.append(f"  {label}：查詢失敗 {type(exc).__name__}: {exc}")

    def roc_to_ad(p):
        """11507 → 2026-07。民國年直接看不出是哪一年，換算後才好比對。"""
        t = str(p or "").strip()
        if len(t) == 5 and t.isdigit():
            return f"{int(t[:3]) + 1911}-{t[3:]}"
        return t

    lines.append("")
    lines.append("【換算成西元】")
    lines.append(f"  記憶體　{roc_to_ad(_revenue_cache.get('period'))}")
    if snap:
        lines.append(f"  快照　　{roc_to_ad((snap.get('source_meta') or {}).get('period'))}")

    lines += ["", "-" * 56, "判讀：",
              "・官方月份＝快照月份＝記憶體月份 → 官方本來就還沒公布新的",
              "・官方比快照新 → 抓取或寫入有問題",
              "・快照比記憶體新 → 該重啟或等快取過期"]
    return plain_text_page(lines), 200


@app.route("/check-mis", methods=["POST", "GET"])
def check_mis():
    """
    診斷 TWSE MIS 盤中報價。用法：/check-mis?token=...&codes=6488,3532,2308

    為什麼需要：實測發現同一時間有些持股拿得到盤中價、有些停在昨收，
    而且不是流動性問題（成交量很大的也會）。程式端只知道「MIS 沒回可用值」，
    看不出是沒回、回了但欄位是 '-'、還是日期對不上。
    這裡直接把原始回應攤開，才有辦法判斷。
    """
    if request.args.get("token") != os.environ.get("CRON_SECRET"):
        abort(403)

    raw = request.args.get("codes", "")
    codes = [c for c in re.findall(r"\d{4,6}[A-Za-z]?", raw)][:20]
    if not codes:
        return plain_text_page(["請帶 codes 參數，例如：",
                                "/check-mis?token=...&codes=6488,3532,2308"]), 200

    lines = [f"TWSE MIS 原始回應診斷　{taiwan_now().strftime('%Y-%m-%d %H:%M:%S')}",
             f"盤中時段：{_is_taiwan_intraday_window()}　"
             f"收盤後：{_taiwan_post_close()}",
             "=" * 62, ""]

    symbols = []
    for code in codes:
        symbols.extend((f"tse_{code}.tw", f"otc_{code}.tw"))

    today_key = taiwan_today().strftime("%Y%m%d")
    got = {}
    try:
        response = requests.get(
            "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
            params={"ex_ch": "|".join(symbols), "json": "1", "delay": "0",
                    "_": int(time.time() * 1000)},
            headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
        payload = response.json()
        lines.append(f"HTTP {response.status_code}　rtcode={payload.get('rtcode')}　"
                     f"msgArray {len(payload.get('msgArray') or [])} 筆")
        lines.append("")
        for item in payload.get("msgArray") or []:
            if not isinstance(item, dict):
                continue
            code = str(item.get("c") or "").strip()
            got.setdefault(code, []).append(item)
    except Exception as exc:
        lines.append(f"❌ 查詢失敗：{type(exc).__name__}: {exc}")
        return plain_text_page(lines), 200

    lines.append("代號    市場  日期      時間      z(成交)   y(昨收)  v(量)  判定")
    lines.append("-" * 62)
    for code in codes:
        items = got.get(code)
        if not items:
            lines.append(f"{code:<7} —     MIS 完全沒有回這個代號")
            continue
        for item in items:
            ch = str(item.get("ch") or "")
            market = "上市" if ch.startswith("tse") or "tse" in ch else "上櫃"
            d = str(item.get("d") or "-")
            t = str(item.get("t") or "-")
            z = str(item.get("z") or "-")
            y = str(item.get("y") or "-")
            v = str(item.get("v") or "-")
            # 重現程式的判定條件，看它為什麼被略過
            why = "採用"
            if d != today_key:
                why = f"略過：日期非今日（{d}）"
            elif z in ("", "-", "--"):
                pz = str(item.get("pz") or "-")
                why = ("採用 pz 備援" if pz not in ("", "-", "--")
                       else "略過：z 與 pz 都無值")
            elif y in ("", "-", "--"):
                why = "略過：無昨收 y"
            lines.append(f"{code:<7} {market}  {d:<9} {t:<9} {z:<9} {y:<8} {v:<6} {why}")

    lines += ["", "-" * 62,
              "判讀：",
              "・「MIS 完全沒有回這個代號」→ 市場別可能查錯（上市查成上櫃或反之）",
              "・「日期非今日」→ MIS 給的是上一個交易日，通常是開盤前",
              "・「z 與 pz 都無值」→ 該檔當下真的沒有成交價",
              "・「採用」卻在畫面看到昨收 → 問題在快取或前端，不在抓取"]
    return plain_text_page(lines), 200


@app.route("/check-inst", methods=["POST", "GET"])
def check_inst():
    """
    診斷單一代號的法人歷史。用法：/check-inst?token=...&code=6669

    把資料庫裡實際存的每日數字逐列印出來，並標出「近10日」查詢實際
    用到哪幾天——數字對不上時，多半不是加總錯，而是取到的日期範圍
    跟你以為的不一樣（例如某些日期只有上櫃資料、或回補漏了某天）。

    每個查詢各自借連線、各自處理錯誤：把三個查詢包在同一個 try 裡的話，
    任何一步出錯都會讓整頁只剩一行錯誤訊息，而且錯誤還可能被包裝成
    看似無關的樣子（例如連線在前一個錯誤後進入異常狀態，
    下一個查詢就報 SSL 錯誤），完全看不出真正壞在哪一步。
    """
    if request.args.get("token") != os.environ.get("CRON_SECRET"):
        abort(403)
    code = normalize_code(request.args.get("code", "")) or "2330"
    try:
        days = max(1, min(60, int(request.args.get("days") or 15)))
    except ValueError:
        days = 15

    def q(sql, params, label):
        """跑一個查詢，回傳 (結果, 錯誤訊息)。錯誤不往外拋，讓其他步驟照跑。"""
        conn = get_db_connection()
        try:
            cur = conn.cursor()
            cur.execute(sql, params)
            rows = cur.fetchall()
            cur.close()
            return rows, None
        except Exception as e:
            print(f"❌ check-inst [{label}] 失敗: {e}")
            return [], f"{type(e).__name__}: {e}"
        finally:
            release_db_connection(conn)

    lines = [f"代號 {code} 的法人歷史", "=" * 58, ""]
    errors = []

    all_rows, err = q(
        "SELECT DISTINCT trade_date FROM inst_history "
        "ORDER BY trade_date DESC LIMIT %s", (days,), "交易日清單")
    if err:
        errors.append(f"[交易日清單] {err}")
    all_dates = [r[0] for r in all_rows]

    rows, err = q(
        "SELECT trade_date, foreign_net_lots, trust_net_lots, "
        "dealer_net_lots, total_net_lots FROM inst_history "
        "WHERE code = %s ORDER BY trade_date DESC LIMIT %s",
        (code, days), "個股明細")
    if err:
        errors.append(f"[個股明細] {err}")

    counts = {}
    if all_dates:
        cnt_rows, err = q(
            "SELECT trade_date, COUNT(*) FROM inst_history "
            "WHERE trade_date >= %s GROUP BY trade_date",
            (all_dates[-1],), "每日檔數")
        if err:
            errors.append(f"[每日檔數] {err}")
        counts = dict(cnt_rows)

    if errors:
        lines.append("⚠️ 部分查詢失敗：")
        lines += [f"　{e}" for e in errors]
        lines.append("")

    if not all_dates:
        lines.append("資料庫裡沒有任何法人歷史，先跑 /cron/fetch-t86 或 /backfill。")
        return plain_text_page(lines), 200

    lines.append(f"資料庫最近 {len(all_dates)} 個交易日："
                 f"{all_dates[0]} ~ {all_dates[-1]}")
    lines.append("")
    lines.append("日期          外資    投信    自營    合計   全市場  10日窗")
    lines.append("-" * 58)

    win10 = set(all_dates[:10])
    have = {r[0] for r in rows}
    sums = [0, 0, 0, 0]
    for d, f, t, dl, tot in rows:
        f, t, dl, tot = (f or 0), (t or 0), (dl or 0), (tot or 0)
        n = counts.get(d, 0)
        thin = " <少" if 0 < n < 1500 else ""
        if d in win10:
            sums[0] += f; sums[1] += t; sums[2] += dl; sums[3] += tot
        lines.append(f"{d}  {f:>7,} {t:>7,} {dl:>7,} {tot:>7,}  {n:>6,}{thin}"
                     f"   {'Y' if d in win10 else ''}")

    lines += ["-" * 58,
              f"10日窗加總　外資 {sums[0]:+,}　投信 {sums[1]:+,}　"
              f"自營 {sums[2]:+,}　合計 {sums[3]:+,}",
              ""]

    missing = [d for d in all_dates[:10] if d not in have]
    if missing:
        lines.append(f"⚠️ 窗內有 {len(missing)} 天缺這檔的紀錄："
                     + "、".join(str(d) for d in missing))
    else:
        lines.append("窗內每一天都有這檔的紀錄")

    # 交易日連續性檢查：資料庫少了某一天時，10 日窗會悄悄往前多抓一天，
    # 數字照樣算得出來也看起來合理，只有跟外部資料對帳才會發現。
    gaps = []
    for i in range(len(all_dates) - 1):
        delta = (all_dates[i] - all_dates[i + 1]).days
        if delta > 4:      # 跨週末最多 3 天，超過代表中間漏了交易日
            gaps.append(f"{all_dates[i + 1]} → {all_dates[i]}（相隔 {delta} 天）")
    if gaps:
        lines += ["", "⚠️ 日期序列有異常間隔，可能漏抓了交易日："]
        lines += [f"　{g}" for g in gaps]
        lines.append("　用 /backfill?days=5&offset=N 回補")

    thin_days = [d for d in all_dates[:10] if 0 < counts.get(d, 0) < 1500]
    if thin_days:
        lines += ["", "⚠️ 以下日期全市場檔數偏少，可能只存到單一市場："]
        lines += [f"　{d}　{counts.get(d, 0):,} 檔" for d in thin_days]

    return plain_text_page(lines), 200


@app.route("/check-industry", methods=["POST", "GET"])
def check_industry():
    """列出每個產業別代碼＋對照名稱＋3家範例公司，用來人工確認對照表正確。"""
    secret = request.args.get("token")
    if secret != os.environ.get("CRON_SECRET"):
        abort(403)

    conn = get_db_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT code, name, industry FROM stock_info ORDER BY industry, code")
        rows = cursor.fetchall()
        cursor.close()
    except Exception as e:
        return f"查詢失敗: {e}", 500
    finally:
        release_db_connection(conn)

    grouped = {}
    for code, name, ind in rows:
        grouped.setdefault(ind, []).append(f"{name}({code})")

    lines = []
    for ind in sorted(grouped):
        samples = "、".join(grouped[ind][:3])
        lines.append(f"{ind} = {industry_name(ind)}　共{len(grouped[ind])}檔　例：{samples}")

    return "產業別對照確認\n\n" + "\n".join(lines), 200


@app.route("/backfill", methods=["POST", "GET"])
def backfill_t86():
    """
    回補過去的 T86 歷史資料。
    用法：/backfill?token=你的CRON_SECRET&days=10&offset=0
      days   一次回補幾天（預設 10，上限 15，避免 Render timeout）
      offset 從幾天前開始往回算（第一次 0，第二次 10，第三次 20...）
    重複回補同一天不會產生重複資料。
    """
    secret = request.args.get("token")
    if secret != os.environ.get("CRON_SECRET"):
        abort(403)

    try:
        days = min(int(request.args.get("days", 5)), 15)
        offset = int(request.args.get("offset", 0))
    except ValueError:
        return "參數錯誤：days 與 offset 必須是數字", 400

    saved, skipped = [], []
    for i in range(offset, offset + days):
        query_date = (taiwan_now() - timedelta(days=i)).strftime("%Y%m%d")
        data = _fetch_t86_for_date(query_date)
        if data:
            save_t86_history(query_date, data)
            saved.append(f"{query_date}({len(data)})")
        else:
            skipped.append(query_date)
        time.sleep(1.2)  # 禮貌等待，避免被 TWSE 擋

    total_days = get_history_days_count()
    return (
        f"回補完成\n"
        f"成功：{len(saved)} 天 → {', '.join(saved) if saved else '無'}\n"
        f"無資料（假日或未公布）：{len(skipped)} 天 → {', '.join(skipped) if skipped else '無'}\n"
        f"目前資料庫累積：{total_days} 個交易日\n"
        f"下一批請用 offset={offset + days}"
    ), 200


