def _leaderboard_periods_for_admin(target_date):
    d = target_date if isinstance(target_date, date) else date.fromisoformat(str(target_date))
    q = (d.month - 1) // 3 + 1
    return [("month", f"{d.year}-{d.month:02d}", f"{d.year}/{d.month:02d} 月榜"), ("season", f"{d.year}Q{q}", f"{d.year} 第 {q} 季")]

def _leaderboard_admin_members():
    conn = get_db_connection()
    try:
        cur = conn.cursor(); cur.execute("SELECT m.user_id, m.nickname FROM leaderboard_members m ORDER BY m.nickname, m.user_id")
        rows = cur.fetchall(); cur.close(); return [(str(r[0]), str(r[1] or r[0])) for r in rows]
    except Exception as exc:
        print(f"⚠️ 讀取排行榜成員失敗：{exc}"); return []
    finally: release_db_connection(conn)

def _send_manual_leaderboard_settlement(target_ids, periods):
    sent = failed = 0
    for target_uid in target_ids:
        try:
            msg = build_leaderboard_settlement_push(target_uid, periods)
            if msg: _push_line_with_retry(target_uid, msg); sent += 1
        except Exception as exc:
            failed += 1; print(f"❌ 管理員手動發送排行榜結算通知失敗 {target_uid}: {exc}")
    return sent, failed

@app.route('/web/admin/leaderboard-settlement', methods=['GET','POST'])
@web_login_required
def web_admin_leaderboard_settlement(uid):
    if not is_admin(uid): return make_response('Forbidden',403)
    # 管理頁 GET 不能因為排行榜成員資料暫時讀取失敗而整頁 500；
    # 發送前再做必要的資料驗證。
    try:
        members = _leaderboard_admin_members()
    except Exception as exc:
        print(f"❌ 排行榜結算通知頁讀取成員失敗：{exc}")
        members = []
    if request.method == 'POST':
        if not valid_web_csrf(): return make_response('CSRF validation failed',403)
        try: settlement_date = date.fromisoformat(str(request.form.get('settlement_date') or taiwan_today().isoformat()).strip())
        except Exception: return make_response('結算日期格式錯誤',400)
        kinds = request.form.getlist('period_kind'); periods = [p for p in _leaderboard_periods_for_admin(settlement_date) if p[0] in kinds]
        if not periods: return make_response('請至少選擇本月或本季',400)
        target_mode = str(request.form.get('target_mode') or 'all')
        if target_mode == 'selected':
            selected = {str(x).strip() for x in request.form.getlist('target_user_id') if str(x).strip()}; target_ids = [member_uid for member_uid,_ in members if member_uid in selected]
        else: target_ids = [member_uid for member_uid,_ in members]
        if not target_ids: return redirect('/web/admin/leaderboard-settlement?status=' + quote('沒有可發送的排行榜成員'))
        # 不在 HTTP request 裡重建整個排行榜。
        # 原本這裡先跑 save_leaderboard_rank_snapshots() + force_rebuild=True，
        # 會重新抓大量行情，導致手機瀏覽器的按鈕長時間停在「處理中…」，
        # 甚至還沒走到 LINE push 就超時。排行榜本身已經在頁面上完成更新，
        # 手動通知只負責「發 LINE」，所以把發送工作放到背景。
        def _send_job():
            sent, failed = _send_manual_leaderboard_settlement(target_ids, periods)
            print(f"📤 管理員手動排行榜結算通知完成：sent={sent}, failed={failed}, periods={periods}")
            return f"已發送 {sent} 人，失敗 {failed} 人"
        try:
            result = run_in_background("管理員排行榜結算通知", _send_job)
        except Exception as exc:
            print(f"❌ 啟動管理員排行榜結算通知失敗：{exc}")
            return make_response('通知啟動失敗：' + html.escape(str(exc)), 500)
        return redirect('/web/admin/leaderboard-settlement?status=' + quote('已開始發送 LINE 通知｜' + str(result)))
    status = request.args.get('status',''); default_date = taiwan_today().isoformat()
    options = ''.join(f'<label style="display:flex;gap:8px;align-items:center;padding:8px 0"><input type="checkbox" name="target_user_id" value="{html.escape(member_uid)}">{html.escape(nickname)}</label>' for member_uid,nickname in members)
    if not options:
        options = '<span class="more-note">目前沒有可發送的排行榜成員；若剛新增成員，請先重新整理排行榜快照。</span>'
    body = f"""<div class="more-hero"><div class="eyebrow">ADMIN ONLY</div><h1>🏆 排行榜結算通知</h1><p>只在管理員按下發送後才會透過 LINE 通知，不會自動推播。</p></div>
    <div class="admin-panel"><h3>📅 結算內容</h3><form method="post" action="/web/admin/leaderboard-settlement" data-form-purpose="leaderboard-settlement"><input type="hidden" name="csrf_token" value="{html.escape(current_web_csrf_token())}"><label>結算日期<br><input name="settlement_date" type="date" value="{default_date}"></label><div style="margin-top:12px"><label><input type="checkbox" name="period_kind" value="month" checked> 📅 本月結算</label><br><label><input type="checkbox" name="period_kind" value="season" checked> 🏆 本季結算</label></div><h3 style="margin-top:18px">📱 發送對象</h3><label><input type="radio" name="target_mode" value="all" checked onchange="document.getElementById('targets').style.opacity='.55'"> 全部排行榜成員</label><label style="display:block;margin-top:8px"><input type="radio" name="target_mode" value="selected" onchange="document.getElementById('targets').style.opacity='1'"> 指定成員</label><div id="targets" style="margin-top:8px;max-height:260px;overflow:auto;opacity:.55;border:1px solid #eee;border-radius:12px;padding:10px">{options or '<span>目前沒有排行榜成員</span>'}</div><button type="submit" style="margin-top:16px;padding:12px 18px;border:0;border-radius:12px;background:#6E5228;color:#fff;font-weight:800">📤 開始發送 LINE 結算通知</button></form></div>
    <div class="admin-panel"><h3>預覽內容</h3><p>🏁 排行榜已完成結算<br><br>📅 月榜／🏆 賽季榜<br><br>本期排行榜資料已更新完成，成績單已產生。<br>前往排行榜查看你的最終排名、報酬與結算成績。</p><p class="more-note">使用者收到訊息後，按鈕會直接進入排行榜。</p></div><div class="admin-panel"><a href="/web/admin">← 返回管理員後台</a></div>{('<div class="admin-panel" style="color:#176b3a"><b>'+html.escape(status)+'</b></div>') if status else ''}"""
    return render_page('排行榜結算通知', body, 'more')

@app.route('/web/admin/data-cleanup', methods=['GET','POST'])
@web_login_required
def web_admin_data_cleanup(uid):
    if not is_admin(uid): return make_response('Forbidden',403)
    if request.method=='POST':
        if not valid_web_csrf(): return make_response('CSRF validation failed',403)
        action=str(request.form.get('action') or '').strip(); table=str(request.form.get('table') or '').strip()
        if action!='cleanup' or table not in RETENTION_DAYS: return make_response('未知清理操作',400)
        col,days=RETENTION_DAYS[table]; conn=get_db_connection(); deleted=0
        try:
            cur=conn.cursor()
            if days: cur.execute(f"DELETE FROM {table} WHERE {col} < CURRENT_DATE - %s",(days,))
            else: cur.execute(f"DELETE FROM {table} WHERE {col} < NOW()")
            deleted=cur.rowcount; conn.commit(); cur.close()
        except Exception as exc:
            try: conn.rollback()
            except Exception: pass
            print(f"❌ 管理員清理 {table} 失敗：{exc}"); return make_response('清理失敗：'+html.escape(str(exc)),500)
        finally: release_db_connection(conn)
        print(f"🧹 管理員 {uid} 清理 {table}: {deleted:,} 筆")
        return redirect('/web/admin/data-cleanup?cleaned='+quote(f'{table}｜{deleted:,} 筆'))
    health=_system_health_summary(); candidates=_cleanup_candidates(); cleaned=request.args.get('cleaned')
    rss_pct=health['rss_pct']; peak_pct=health['peak_24h_pct']
    def level(p): return '🟢 正常' if p<70 else ('🟡 注意' if p<85 else ('🟠 高風險' if p<95 else '🔴 接近上限'))
    db_days=health.get('db_days_to_limit'); growth=health.get('db_growth_per_day')
    forecast=(f'依最近 7 天樣本估算，約 {db_days:.0f} 天後達 500 MB' if db_days else '尚無足夠歷史樣本，持續收集後才會估算')
    preview=[]
    for item in candidates:
        table=item['table']; count=item['count']; est=_fmt_mb_bytes(item['estimated_bytes']); oldest=html.escape(str(item['oldest'] or '—'))
        if count:
            table_q=html.escape(table,quote=True)
            btn=f'''<form method="post" onsubmit="return confirm('確定刪除 {table} 中超過保留期限的 {count:,} 筆資料？此動作無法復原。')">{csrf_hidden_input()}<input type="hidden" name="action" value="cleanup"><input type="hidden" name="table" value="{table_q}"><button class="danger-btn">🗑️ 刪除 {count:,} 筆（約 {est}）</button></form>'''
            status=f'<b style="color:#b42318">可清理 {count:,} 筆</b> · 最舊 {oldest} · 約 {est}'
        else:
            btn='<span class="clean-ok">目前沒有符合條件的舊資料</span>'; status=f'<span class="clean-ok">目前沒有符合條件的舊資料</span> · 最舊 {oldest}'
        preview.append(f'<div class="clean-row"><div><h3>{html.escape(table)}</h3><small>欄位：{html.escape(item["column"])} · 保留 {item["days"]} 天 · 總筆數 {item["total"]:,} · 表大小 {_fmt_mb_bytes(item["size"])}</small><p>{status}</p></div><div>{btn}</div></div>')
    flash=f'<div class="clean-flash">✅ {html.escape(cleaned)}</div>' if cleaned else ''
    growth_text=f' · 最近樣本約 +{_fmt_mb_bytes(growth)}/天' if growth else ''
    body=f'''<style>.clean-wrap{{max-width:900px;margin:auto}}.health-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0}}.health-card,.clean-panel{{background:#fff;border:1px solid #e4e8ee;border-radius:18px;padding:16px;margin:10px 0}}.health-card b{{font-size:24px;display:block;margin:4px 0}}.health-card small,.clean-row small{{color:#667085;line-height:1.6}}.health-meter{{height:9px;background:#edf0f4;border-radius:99px;overflow:hidden;margin:10px 0}}.health-meter i{{display:block;height:100%;width:{min(max(rss_pct,0),100):.1f}%;background:#111;border-radius:99px}}.clean-row{{padding:15px 0;border-bottom:1px solid #edf0f4;display:flex;justify-content:space-between;gap:15px;align-items:center}}.clean-row:last-child{{border-bottom:0}}.clean-row h3{{margin:0 0 4px}}.clean-row p{{margin:8px 0 0}}.danger-btn{{border:0;background:#b42318;color:#fff;border-radius:11px;padding:10px 14px;font-weight:800;white-space:nowrap}}.clean-ok{{color:#16803c;font-weight:700}}.clean-flash{{background:#ecfdf3;color:#067647;border:1px solid #abefc6;border-radius:14px;padding:12px;margin:12px 0}}@media(max-width:700px){{.health-grid{{grid-template-columns:1fr}}.clean-row{{display:block}}.danger-btn{{margin-top:10px;width:100%}}}}</style><div class="clean-wrap"><div class="more-hero"><div class="eyebrow">ADMIN ONLY</div><h1>🗄️ 資料清理 & 系統健康</h1><p>先看實際可清理數量，再決定要刪多少。核心資料不提供一鍵清空。</p></div>{flash}<div class="health-grid"><div class="health-card"><small>目前 Worker RSS</small><b>{_fmt_mb_bytes(health['rss'])} / {RENDER_MEMORY_LIMIT_MB:.0f} MB</b><div class="health-meter"><i></i></div><span>{level(rss_pct)} · {rss_pct:.1f}%</span></div><div class="health-card"><small>24 小時已記錄峰值</small><b>{_fmt_mb_bytes(health['peak_24h'])}</b><span>{level(peak_pct)} · {peak_pct:.1f}%</span><br><small>⚠️ 這是單一 Gunicorn worker RSS，不代表 Render 整個服務總 RAM。</small></div><div class="health-card"><small>Supabase 資料庫</small><b>{_fmt_mb_bytes(health['db_bytes'])} / 500 MB</b><span>{health['db_bytes']/(500*1024*1024)*100:.1f}%</span><br><small>{forecast}{growth_text}</small></div></div><div class="clean-panel"><h2>📊 可清理資料預覽</h2>{''.join(preview) or '<div class="more-note">目前沒有可清理資料表。</div>'}</div><div class="clean-panel"><b>安全規則</b><p class="more-note">刪除只依程式內建白名單與保留期限執行；不接受前端任意 SQL。刪除前會再次確認，不會碰 users、positions、realized_trades、position_change_logs。</p></div></div>'''
    return render_page('資料清理',body,'more')

